                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}
    </div>
  );
}

import React from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

// Helper fractions: percentage of face area that needs masking.
// e.g. "1/4" = 25% of the face area gets masked.
export const COVERAGE_FACTORS = [
  "1/8", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8",
  "1", "1-1/8", "1-1/4", "1-3/8", "1-1/2", "1-5/8", "1-3/4", "1-7/8", "2",
];

export const parseImperialFraction = (s) => {
  if (typeof s !== "string") return parseFloat(s) || 0;
  let total = 0;
  let rest = s;
  const [whole, fracPart] = s.split("-");
  if (fracPart !== undefined) {
    total += parseFloat(whole) || 0;
    rest = fracPart;
  }
  const [num, den] = rest.split("/");
  if (den !== undefined) {
    const n = parseFloat(num);
    const d = parseFloat(den);
    if (d) total += n / d;
  } else {
    total += parseFloat(rest) || 0;
  }
  return total;
};

/**
 * Reusable paint-mask + coverage helper input pair.
 *  - faceAreaSqft: the face area to compute coverage from (caller must compute & pass).
 *  - bothSides:    if true, multiplies the helper result by 2.
 *  - value:        current paint_mask_sqft
 *  - factor:       current coverage factor string ("1/4", etc.)
 *  - onChange({ paint_mask_sqft, approx_coverage_factor })
 */
export default function PaintCoverageHelper({
  faceAreaSqft = 0,
  bothSides = false,
  value = 0,
  factor = "1/4",
  onChange,
  className = "",
}) {
  const setFactor = (f) => {
    const frac = parseImperialFraction(f);
    const sides = bothSides ? 2 : 1;
    const calculated = (parseFloat(faceAreaSqft) || 0) * frac * sides;
    onChange({
      paint_mask_sqft: Number.isFinite(calculated) ? calculated : 0,
      approx_coverage_factor: f,
    });
  };

  const setManual = (v) => {
    onChange({
      paint_mask_sqft: parseFloat(v) || 0,
      approx_coverage_factor: factor,
    });
  };

  return (
    <div className={`grid grid-cols-1 md:grid-cols-2 gap-3 ${className}`}>
      <div>
        <Label className="text-xs">Paint Mask Square Feet</Label>
        <Input
          type="number"
          min="0"
          step="0.25"
          value={value || ""}
          onFocus={(e) => e.target.select()}
          onChange={(e) => setManual(e.target.value)}
          className="mt-1"
        />
        <p className="text-[11px] text-slate-500 mt-1">Manually enter sqft or use the helper.</p>
      </div>
      <div>
        <Label className="text-xs">Approx. Coverage Helper</Label>
        <Select value={factor || "1/4"} onValueChange={setFactor}>
          <SelectTrigger className="mt-1">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {COVERAGE_FACTORS.map((f) => (
              <SelectItem key={f} value={f}>{f}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <p className="text-[11px] text-slate-500 mt-1">
          {faceAreaSqft > 0
            ? <>Face area: <strong>{faceAreaSqft.toFixed(2)} sqft</strong>{bothSides ? " × 2 sides" : ""}</>
            : <>Calculates mask sqft based on face area.</>}
        </p>
      </div>
    </div>
  );
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Trash2, Users, Wand2 } from "lucide-react";
import { recalcPersonnelRow, suggestPersonnelForProject } from "./equipmentSuggester";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

const ROLE_OPTIONS = ["Crew Lead", "Installer", "Helper"];

const emptyRow = () => ({
  name: "",
  role: "Installer",
  hourly_rate: 0,
  hours: 0,
  total_cost: 0,
});

export default function PersonnelSelector({
  personnel = [],
  onChange,
  projectLaborHours = 0,
  roleRates = {},
  items = [],
  issues = [],
}) {
  // Resolve the rate for a given role (fallback to Installer rate, then 0)
  const rateForRole = (role) => {
    const r = parseFloat(roleRates[role]);
    if (!isNaN(r) && r > 0) return r;
    const fallback = parseFloat(roleRates.Installer);
    return !isNaN(fallback) ? fallback : 0;
  };

  const handleAdd = () => {
    const row = emptyRow();
    row.hourly_rate = rateForRole(row.role);
    onChange([...personnel, row]);
  };

  const handleUpdate = (idx, patch) => {
    const next = [...personnel];
    const merged = { ...next[idx], ...patch };
    // When the role changes, auto-fill the rate from the role's setting
    if ("role" in patch && patch.role !== next[idx].role) {
      merged.hourly_rate = rateForRole(patch.role);
    }
    next[idx] = recalcPersonnelRow(merged);
    onChange(next);
  };

  const handleRemove = (idx) => {
    if (!confirm(`Remove "${personnel[idx]?.name || "this person"}"?`)) return;
    const next = [...personnel];
    next.splice(idx, 1);
    onChange(next);
  };

  // Quick-fill: build a suggested crew from project height & letter count.
  // Uses the shared suggestPersonnelForProject helper so the auto-trigger and
  // the manual button produce the exact same crew.
  const handleAutoFillCrew = () => {
    const newCrew = suggestPersonnelForProject(items, projectLaborHours, rateForRole);
    onChange(newCrew);
  };

  // Pricing diagnostics — per-field aria-invalid + inline message.
  const rowIssues = (idx, field) => issuesForField(issues, field, null, idx);
  const rowInvalid = (idx, field) => rowIssues(idx, field).length > 0;
  const rowAria = (idx, field) => (rowInvalid(idx, field)
    ? { "aria-invalid": true, "aria-describedby": `clp-crew-${idx}-${field}-issue` }
    : {});
  const RowIssue = ({ idx, field }) => {
    const fi = rowIssues(idx, field);
    if (!fi.length) return null;
    return (
      <p id={`clp-crew-${idx}-${field}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">
        {fi[0].message}
      </p>
    );
  };

  const totalCost = personnel.reduce(
    (s, p) => {
      if (s === null) return null;
      const v = channelNumber(p.total_cost);
      return v === null ? null : s + v;
    },
    0
  );
  const totalHours = personnel.reduce(
    (s, p) => {
      if (s === null) return null;
      const v = channelNumber(p.hours);
      return v === null ? null : s + v;
    },
    0
  );

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3 flex flex-row items-center justify-between flex-wrap gap-2">
        <div>
          <CardTitle className="text-lg flex items-center gap-2">
            <Users className="w-5 h-5 text-purple-600" />
            Personnel ({personnel.length})
          </CardTitle>
          <p className="text-xs text-slate-500 mt-1">
            Assign crew members and their hours for this job.
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={handleAutoFillCrew}
            className="h-9 text-xs"
            title="Auto-suggest crew based on project size & height"
          >
            <Wand2 className="w-3.5 h-3.5 mr-1" /> Auto-Suggest Crew
          </Button>
          <Button
            size="sm"
            onClick={handleAdd}
            className="bg-purple-600 hover:bg-purple-700 text-white"
          >
            <Plus className="w-4 h-4 mr-1" /> Add Person
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {personnel.length === 0 ? (
          <div className="border-2 border-dashed border-slate-300 bg-slate-50/50 rounded-lg p-8 text-center">
            <Users className="w-8 h-8 text-slate-400 mx-auto mb-2" />
            <p className="text-sm text-slate-600 font-medium">No personnel assigned</p>
            <p className="text-xs text-slate-500 mt-1">
              Add crew members or use Auto-Suggest to populate based on the project.
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {personnel.map((row, idx) => (
              <div
                key={idx}
                className="border border-slate-200 rounded-lg p-3 bg-slate-50/50"
              >
                <div className="grid md:grid-cols-12 gap-2 items-end">
                  <div className="md:col-span-3">
                    <Label className="text-xs">Name</Label>
                    <Input
                      value={row.name}
                      onChange={(e) => handleUpdate(idx, { name: e.target.value })}
                      placeholder="e.g. Mike"
                      className="h-8 mt-0.5"
                    />
                  </div>
                  <div className="md:col-span-3">
                    <Label className="text-xs">Role</Label>
                    <select
                      value={row.role || "Installer"}
                      onChange={(e) => handleUpdate(idx, { role: e.target.value })}
                      className="h-8 mt-0.5 w-full border border-slate-200 rounded-md px-2 text-sm bg-white"
                    >
                      {ROLE_OPTIONS.map((r) => (
                        <option key={r} value={r}>{r}</option>
                      ))}
                    </select>
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Rate $/hr</Label>
                    <Input
                      type="number"
                      step="0.01"
                      value={row.hourly_rate}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hourly_rate: channelDraftValue(e.target.value) })
                      }
                      className={`h-8 mt-0.5 ${rowInvalid(idx, "hourly_rate") ? "border-red-500" : ""}`}
                      {...rowAria(idx, "hourly_rate")}
                    />
                    <RowIssue idx={idx} field="hourly_rate" />
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Hours</Label>
                    <Input
                      type="number"
                      step="0.25"
                      value={row.hours}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hours: channelDraftValue(e.target.value) })
                      }
                      className={`h-8 mt-0.5 ${rowInvalid(idx, "hours") ? "border-red-500" : ""}`}
                      {...rowAria(idx, "hours")}
                    />
                    <RowIssue idx={idx} field="hours" />
                  </div>
                  <div className="md:col-span-1">
                    <Label className="text-xs">Total</Label>
                    <div className="h-8 mt-0.5 text-sm font-medium flex items-center tabular-nums">
                      {fmt(row.total_cost)}
                    </div>
                  </div>
                  <div className="md:col-span-1 flex items-end justify-end">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleRemove(idx)}
                      className="text-red-500 hover:bg-red-50 h-8 w-8 p-0"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
            <div className="flex justify-between pt-2 border-t border-slate-200 text-sm">
              <div>
                <span className="text-slate-500">Total Hours:</span>{" "}
                <span className="font-semibold tabular-nums">{Number.isFinite(totalHours) ? totalHours.toFixed(2) : "—"}</span>
                {projectLaborHours > 0 && (
                  <span className="text-xs text-slate-400 ml-2">
                    (calculated: {projectLaborHours.toFixed(2)} hrs)
                  </span>
                )}
              </div>
              <div className="text-right">
                <span className="text-xs text-slate-500">Total Personnel Cost: </span>
                <span className="text-lg font-bold tabular-nums">{fmt(totalCost)}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Camera, Loader2, Upload, Wand2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { ESTIMATOR_AI_MODEL } from "../../../base44/shared/estimatorAiModelPolicy.js";

const SCHEMA = {
  type: "object",
  properties: {
    estimated_height_feet: { type: "number", description: "Estimated install height from ground in feet" },
    wall_material: {
      type: "string",
      enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"],
      description: "Best guess of the wall material"
    },
    recommended_install_type: {
      type: "string",
      enum: ["flush_mount", "halo_lit", "raceway", "dimensional_lettering"]
    },
    site_conditions: {
      type: "object",
      properties: {
        parapet: { type: "boolean" },
        poor_electrical_access: { type: "boolean" },
        thick_hollow_walls: { type: "boolean" }
      }
    },
    confidence: { type: "string", enum: ["low", "medium", "high"] },
    reasoning: { type: "string", description: "Brief explanation of what was observed" }
  }
};

export default function PhotoEstimateModal({ open, onClose, onApply }) {
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const handleFile = (f) => {
    if (!f) return;
    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
    setResult(null);
    setError(null);
  };

  const analyze = async () => {
    if (!file) return;
    setLoading(true);
    setError(null);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      const res = await base44.integrations.Core.InvokeLLM({
        model: ESTIMATOR_AI_MODEL,
        prompt: `You're a sign installer reviewing a photo of a site where channel letters will be installed.
Analyze the photo and estimate:
- The install height (feet from ground to where letters will go)
- The wall material (eifs, stucco, brick, concrete, metal, wood, glass, drywall)
- Recommended install type (flush_mount, halo_lit, raceway, dimensional_lettering)
- Site conditions: is there a parapet? poor electrical access? thick hollow walls?
- Your confidence level (low/medium/high)

Be specific and practical — these will be used in an estimate.`,
        file_urls: [file_url],
        response_json_schema: SCHEMA
      });
      setResult(res);
    } catch (e) {
      setError(e.message || "Analysis failed");
    }
    setLoading(false);
  };

  const apply = () => {
    if (!result) return;
    onApply(result);
    handleClose();
  };

  const handleClose = () => {
    setFile(null);
    setPreviewUrl(null);
    setResult(null);
    setError(null);
    onClose();
  };

  const confidenceColor = {
    high: "bg-green-100 text-green-800 border-green-200",
    medium: "bg-amber-100 text-amber-800 border-amber-200",
    low: "bg-red-100 text-red-800 border-red-200",
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Camera className="w-5 h-5 text-purple-600" />
            Photo → Estimate
          </DialogTitle>
          <p className="text-xs text-slate-500">Upload a photo of the install site — AI will estimate height, wall material, and conditions.</p>
        </DialogHeader>

        <div className="space-y-3">
          {!previewUrl ? (
            <label className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 rounded-lg p-8 cursor-pointer hover:border-purple-400 hover:bg-purple-50/50 transition-colors">
              <Upload className="w-8 h-8 text-slate-400 mb-2" />
              <span className="text-sm font-medium text-slate-700">Click to upload a site photo</span>
              <span className="text-xs text-slate-500 mt-1">JPG, PNG, or HEIC</span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => handleFile(e.target.files?.[0])}
              />
            </label>
          ) : (
            <div className="relative">
              <img src={previewUrl} alt="Site preview" className="w-full max-h-64 object-contain rounded-lg border border-slate-200 bg-slate-50" />
              <Button
                variant="outline"
                size="sm"
                onClick={() => { setFile(null); setPreviewUrl(null); setResult(null); }}
                className="absolute top-2 right-2 h-7 text-xs bg-white"
              >
                Change
              </Button>
            </div>
          )}

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">{error}</div>
          )}

          {result && (
            <div className="border border-purple-200 bg-purple-50/40 rounded-lg p-3 space-y-2">
              <div className="flex items-center justify-between">
                <div className="text-xs font-semibold text-purple-900 flex items-center gap-1">
                  <Wand2 className="w-3.5 h-3.5" />
                  AI Analysis
                </div>
                {result.confidence && (
                  <span className={`text-[10px] px-1.5 py-0.5 rounded border ${confidenceColor[result.confidence]}`}>
                    {result.confidence} confidence
                  </span>
                )}
              </div>
              <div className="grid grid-cols-2 gap-2 text-xs">
                <Field label="Install Height" value={`${result.estimated_height_feet || 0} ft`} />
                <Field label="Wall Material" value={result.wall_material || "—"} />
                <Field label="Recommended" value={result.recommended_install_type?.replace(/_/g, " ") || "—"} />
                <Field
                  label="Conditions"
                  value={[
                    result.site_conditions?.parapet && "parapet",
                    result.site_conditions?.poor_electrical_access && "poor electrical",
                    result.site_conditions?.thick_hollow_walls && "thick walls"
                  ].filter(Boolean).join(", ") || "none noted"}
                />
              </div>
              {result.reasoning && (
                <div className="text-[11px] text-slate-600 italic border-t border-purple-200 pt-1.5">
                  {result.reasoning}
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={handleClose} disabled={loading}>Cancel</Button>
          {!result ? (
            <Button onClick={analyze} disabled={!file || loading} className="bg-purple-600 hover:bg-purple-700 text-white">
              {loading ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Analyzing...</> : <><Camera className="w-4 h-4 mr-2" /> Analyze Photo</>}
            </Button>
          ) : (
            <Button onClick={apply} className="bg-green-600 hover:bg-green-700 text-white">
              <Wand2 className="w-4 h-4 mr-2" /> Apply to New Line Item
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const Field = ({ label, value }) => (
  <div className="bg-white rounded border border-purple-100 px-2 py-1.5">
    <div className="text-[10px] uppercase tracking-wide text-slate-500">{label}</div>
    <div className="font-medium text-slate-800 capitalize">{value}</div>
