// Sticky summary card for the right side of the Vinyl Estimator page.
// Rolls up across all workflows + installation + travel + personnel + markup.
//
// Pricing-availability: every number the card shows is either the real live
// rollup or the saved acknowledged snapshot. When current pricing is
// unavailable the card says so ("Saved amounts (not current pricing)") and
// shows "Not saved" for anything with no snapshot — never a laundered $0.


import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Save, Loader2, AlertTriangle } from "lucide-react";
import { hasIssueFor, hasVinylCostSnapshot, vinylDraftValue } from "./vinylPricingAvailability";

const fmt = (n) => `$${Number(n || 0).toFixed(2)}`;
const money = (v) => hasVinylCostSnapshot(v)
  ? fmt(v)
  : <span className="text-amber-700 font-medium">Not saved</span>;

const Line = ({ label, value, muted }) => (
  <div className={`flex justify-between text-sm ${muted ? "text-slate-500" : "text-slate-800"}`}>
    <span className="truncate pr-2">{label}</span>
    <span className="tabular-nums shrink-0">{value}</span>
  </div>
);

export default function VinylProjectSummaryCard({
  rollup, project, onUpdateProject, onSave, isSaving,
  pricingUnavailable = false, pricingBlocked = false, issues = [], issuesId = "vinyl-pricing-issues",
}) {
  const laborLabel = hasVinylCostSnapshot(rollup.laborHours)
    ? `Labor · ${rollup.laborHours.toFixed(2)} hr`
    : "Labor";
  return (
    <Card className="sticky top-4 bg-white border-0 shadow-sm">
      <CardHeader className="pb-2"><CardTitle className="text-base">Estimate Summary</CardTitle></CardHeader>
      <CardContent className="space-y-3 text-sm">
        {pricingUnavailable && (
          <div className="flex items-start gap-2 text-[11px] text-amber-900 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
            <AlertTriangle className="w-3 h-3 mt-0.5 flex-shrink-0" />
            <span>
              <b>Saved amounts (not current pricing)</b> — current pricing is unavailable.
              Fix the flagged values to reprice{pricingBlocked ? "; saving is paused until then" : ""}.
            </span>
          </div>
        )}
        <div className="space-y-1">
          <Line label="Vinyl"    value={money(rollup.vinylCost)} />
          <Line label="Laminate" value={money(rollup.laminateCost)} muted />
          <Line label="Ink"      value={money(rollup.inkCost)} muted />
          <Line label="Blade"    value={money(rollup.bladeCost)} muted />
        </div>

        <div className="border-t pt-2 space-y-1">
          <Line label="Machine Time" value={money(rollup.machineCost)} />
          <Line label={laborLabel} value={money(rollup.laborCost)} />
        </div>

        {(rollup.equipmentCost > 0 || rollup.personnelCost > 0 || rollup.travelCost > 0
          || rollup.equipmentCost === null || rollup.personnelCost === null || rollup.travelCost === null) && (
          <div className="border-t pt-2 space-y-1">
            {(rollup.equipmentCost === null || rollup.equipmentCost > 0) && <Line label="Equipment" value={money(rollup.equipmentCost)} />}
            {(rollup.personnelCost === null || rollup.personnelCost > 0) && <Line label="Personnel" value={money(rollup.personnelCost)} />}
            {(rollup.travelCost === null || rollup.travelCost > 0)    && <Line label="Travel"    value={money(rollup.travelCost)} />}
          </div>
        )}

        <div className="border-t pt-3 space-y-2">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <Label className="text-[11px]">Supplies %</Label>
              <Input type="number" step="0.5"
                value={project.supplies_percent_of_materials ?? ""}
                onChange={(e) => onUpdateProject({ supplies_percent_of_materials: vinylDraftValue(e.target.value) })}
                aria-invalid={hasIssueFor(issues, "supplies_percent_of_materials") || undefined}
                aria-describedby={hasIssueFor(issues, "supplies_percent_of_materials") ? issuesId : undefined}
                className="h-8 text-sm tabular-nums" />
            </div>
            <div>
              <Label className="text-[11px]">Extra Supplies $</Label>
              <Input type="number" step="1"
                value={project.extra_supplies_cost ?? ""}
                onChange={(e) => onUpdateProject({ extra_supplies_cost: vinylDraftValue(e.target.value) })}
                aria-invalid={hasIssueFor(issues, "extra_supplies_cost") || undefined}
                aria-describedby={hasIssueFor(issues, "extra_supplies_cost") ? issuesId : undefined}
                className="h-8 text-sm tabular-nums" />
            </div>
          </div>
          <Line label="Supplies Total" value={money(rollup.supplies)} muted />
        </div>

        <div className="border-t pt-3 space-y-2">
          <div>
            <Label className="text-[11px]">Markup %</Label>
            <Input type="number" step="0.5"
              value={project.markup_percent ?? ""}
              onChange={(e) => onUpdateProject({ markup_percent: vinylDraftValue(e.target.value) })}
              aria-invalid={hasIssueFor(issues, "markup_percent") || undefined}
              aria-describedby={hasIssueFor(issues, "markup_percent") ? issuesId : undefined}
              className="h-8 text-sm tabular-nums" />
          </div>
          <Line label="Subtotal" value={money(rollup.subtotal)} muted />
          <Line label="Markup"   value={money(rollup.markupAmount)} muted />
        </div>

        <div className="border-t pt-3 bg-slate-900 text-white -mx-6 -mb-6 px-6 py-4 rounded-b-xl">
          <div className="flex justify-between font-bold text-lg">
            <span>Total</span>
            <span className="tabular-nums">
              {hasVinylCostSnapshot(rollup.totalCost) ? fmt(rollup.totalCost) : <span className="text-amber-300">Not saved</span>}
            </span>
          </div>
        </div>

        {project?.updated_date && (<div className="mt-1 text-[10px] text-gray-400">Last saved {new Date(project.updated_date).toLocaleString()}</div>)}
        <Button onClick={onSave} disabled={isSaving || pricingBlocked}
          className="w-full bg-emerald-600 hover:bg-emerald-700 text-white mt-3 disabled:opacity-60">
          {isSaving ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Save className="w-4 h-4 mr-1" />}
          Save Estimate
        </Button>
        {pricingBlocked && (
          <p className="text-[11px] text-amber-800 text-center">
            Fix the flagged pricing values to save — unavailable pricing is never written as $0.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

// Roll layout visualizer with drag-and-drop part repositioning.
//
// Each placed item has:
//   - outer rect (w × h)        = part + bleed halo (the reserved real-estate on the roll)
//   - inner part rect (partW × partH)  = actual artwork (centered inside outer)
// The bleed halo renders as hatched waste so it reads as "empty space around the part".
//
// Drag & drop:
//   Click + drag any part to slide it around the roll. We snap-collide against other
//   parts (with the workflow's H/V gutters) and the usable column edges. On drop we
//   call onItemsMove(updates) where updates = [{ shelfIdx, itemIdx, x, y }].
//   Because the data model is shelf-based, we re-shelf the part if its new y crosses
//   into another shelf row.

import React, { useMemo, useState, useRef, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { ZoomIn, ZoomOut, RotateCcw, ArrowDown, Move } from "lucide-react";

const PALETTE = [
  "#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6",
  "#ec4899", "#14b8a6", "#f97316", "#6366f1", "#84cc16",
];

const fmt = (n) => Number(n || 0).toFixed(2);

const computeWasteRects = (shelves, usableWidth, gutterV) => {
  const wastes = [];
  shelves.forEach((sh, sIdx) => {
    if (sh.items.length === 0) return;
    const last = sh.items[sh.items.length - 1];
    const rightEdge = last.x + last.w;
    if (rightEdge < usableWidth - 0.01) {
      wastes.push({ x: rightEdge, y: sh.y, w: usableWidth - rightEdge, h: sh.height });
    }
    const next = shelves[sIdx + 1];
    if (next && next.y > sh.y + sh.height) {
      wastes.push({ x: 0, y: sh.y + sh.height, w: usableWidth, h: next.y - sh.y - sh.height });
    }
  });
  return wastes;
};

export default function VinylRollVisualizer({
  calc,
  showRegistrationMarks = false,
  onItemMove, // optional: (newPos) => void  — { shelfIdx, itemIdx, x }
}) {
  const {
    shelves, usableWidth, effectiveRollWidth, leadingEdge, trailingEdge,
    lengthConsumedIn, totalLengthIn, partsPlaced, partsUnplaced,
    wastedSqFt, usedSqFt, gutterV, gutterH,
  } = calc;

  const [zoom, setZoom] = useState(1);
  const svgRef = useRef(null);

  // Local drag overrides — keyed by `${shelfIdx}-${itemIdx}` => new x
  const [dragOverrides, setDragOverrides] = useState({});
  const [dragging, setDragging] = useState(null); // { shelfIdx, itemIdx, startSvgX, startX }

  const colorFor = useMemo(() => {
    const map = {};
    let i = 0;
    shelves.forEach(sh => sh.items.forEach(it => {
      if (!(it.itemIdx in map)) { map[it.itemIdx] = PALETTE[i % PALETTE.length]; i++; }
    }));
    return map;
  }, [shelves]);

  const wasteRects = useMemo(() => computeWasteRects(shelves, usableWidth, gutterV), [shelves, usableWidth, gutterV]);

  const drawWidth  = Math.max(1, effectiveRollWidth);
  const drawHeight = Math.max(12, lengthConsumedIn);

  const targetW = 520;
  const baseScale = targetW / drawWidth;
  const svgW = drawWidth * baseScale * zoom;
  const cappedH = Math.min(900, drawHeight * baseScale);
  const svgH = cappedH * zoom;

  const viewBox = `0 0 ${drawWidth} ${drawHeight}`;
  const usableX = (effectiveRollWidth - usableWidth) / 2;

  // Convert client px to SVG user units
  const clientToSvg = useCallback((clientX, clientY) => {
    const svg = svgRef.current;
    if (!svg) return { x: 0, y: 0 };
    const pt = svg.createSVGPoint();
    pt.x = clientX; pt.y = clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return { x: 0, y: 0 };
    const local = pt.matrixTransform(ctm.inverse());
    return { x: local.x, y: local.y };
  }, []);

  const handleMouseDown = (e, shelfIdx, itemIdx, item) => {
    if (!onItemMove) return;
    e.stopPropagation();
    e.preventDefault();
    const { x: svgX } = clientToSvg(e.clientX, e.clientY);
    setDragging({ shelfIdx, itemIdx, startSvgX: svgX, startX: item.x });
  };

  const handleMouseMove = (e) => {
    if (!dragging) return;
    const { x: svgX } = clientToSvg(e.clientX, e.clientY);
    const sh = shelves[dragging.shelfIdx];
    const it = sh.items[dragging.itemIdx];
    let newX = dragging.startX + (svgX - dragging.startSvgX);

    // Clamp + collision against neighbors with gutterH spacing
    const minX = (() => {
      const prev = sh.items[dragging.itemIdx - 1];
      return prev ? prev.x + prev.w + gutterH : 0;
    })();
    const maxX = (() => {
      const next = sh.items[dragging.itemIdx + 1];
      const rightLimit = next ? next.x - gutterH - it.w : usableWidth - it.w;
      return Math.max(minX, rightLimit);
    })();
    newX = Math.max(minX, Math.min(maxX, newX));

    setDragOverrides(prev => ({ ...prev, [`${dragging.shelfIdx}-${dragging.itemIdx}`]: newX }));
  };

  const handleMouseUp = () => {
    if (!dragging) return;
    const key = `${dragging.shelfIdx}-${dragging.itemIdx}`;
    const newX = dragOverrides[key];
    if (newX !== undefined && onItemMove) {
      onItemMove({ shelfIdx: dragging.shelfIdx, itemIdx: dragging.itemIdx, x: newX });
    }
    setDragging(null);
    // keep overrides until parent re-renders; clear next tick
    setTimeout(() => setDragOverrides({}), 0);
  };

  const regMarks = useMemo(() => {
    if (!showRegistrationMarks) return [];
    const marks = [];
    const spacing = 12;
    const startY = leadingEdge + 0.5;
    const endY = drawHeight - trailingEdge - 0.5;
    for (let y = startY; y < endY; y += spacing) {
      marks.push({ x: usableX + 0.3, y });
      marks.push({ x: usableX + usableWidth - 0.3, y });
    }
    return marks;
  }, [showRegistrationMarks, leadingEdge, trailingEdge, drawHeight, usableX, usableWidth]);

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-3 text-xs text-slate-600 items-center">
        <Stat label="Roll Width"      value={`${fmt(effectiveRollWidth)}″`} />
        <Stat label="Usable Width"    value={`${fmt(usableWidth)}″`} />
        <Stat label="Content Length"  value={`${fmt(totalLengthIn)}″`} />
        <Stat label="Roll Consumed"   value={`${fmt(lengthConsumedIn / 12)} ft`} />
        <Stat label="Parts Placed"    value={partsPlaced} />
        {partsUnplaced > 0 && <Stat label="Unplaced" value={partsUnplaced} tone="bad" />}
        <Stat label="Used"            value={`${fmt(usedSqFt)} sqft`} />
        <Stat label="Waste"           value={`${fmt(wastedSqFt)} sqft`} tone="warn" />
        <div className="ml-auto flex items-center gap-1">
          {onItemMove && (
            <span className="text-[10px] text-slate-500 mr-2 inline-flex items-center gap-1">
              <Move className="w-3 h-3" /> Drag parts to reposition
            </span>
          )}
          <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => setZoom(z => Math.max(0.5, z - 0.25))} title="Zoom out">
            <ZoomOut className="w-3.5 h-3.5" />
          </Button>
          <span className="text-[11px] tabular-nums w-10 text-center">{Math.round(zoom * 100)}%</span>
          <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => setZoom(z => Math.min(4, z + 0.25))} title="Zoom in">
            <ZoomIn className="w-3.5 h-3.5" />
          </Button>
          <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => setZoom(1)} title="Reset zoom">
            <RotateCcw className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      <div className="bg-slate-100 rounded-lg border border-slate-200 overflow-hidden">
        <div className="overflow-auto p-3" style={{ maxHeight: 600 }}>
          <svg
          ref={svgRef}
          width={svgW} height={svgH} viewBox={viewBox}
          preserveAspectRatio="xMidYMin meet"
          style={{ background: "#e2e8f0", display: "block", userSelect: "none" }}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
        >
          <defs>
            <pattern id="wasteHatch" patternUnits="userSpaceOnUse" width="1.4" height="1.4" patternTransform="rotate(45)">
              <rect width="1.4" height="1.4" fill="#fecaca" fillOpacity="0.4" />
              <line x1="0" y1="0" x2="0" y2="1.4" stroke="#dc2626" strokeWidth="0.18" strokeOpacity="0.6" />
            </pattern>
            <pattern id="bleedHatch" patternUnits="userSpaceOnUse" width="1.0" height="1.0" patternTransform="rotate(45)">
              <rect width="1.0" height="1.0" fill="#fed7aa" fillOpacity="0.5" />
              <line x1="0" y1="0" x2="0" y2="1.0" stroke="#ea580c" strokeWidth="0.12" strokeOpacity="0.6" />
            </pattern>
            <marker id="arrow" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="3" markerHeight="3" orient="auto">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="white" fillOpacity="0.6" />
            </marker>
          </defs>

          {/* Roll backdrop */}
          <rect x={0} y={0} width={drawWidth} height={drawHeight} fill="#f1f5f9" />

          {/* Usable column */}
          <rect x={usableX} y={leadingEdge} width={usableWidth} height={Math.max(0, drawHeight - leadingEdge - trailingEdge)} fill="#ffffff" />

          {/* Waste rects */}
          {wasteRects.map((w, i) => (
            <rect key={`w-${i}`} x={usableX + w.x} y={leadingEdge + w.y} width={w.w} height={w.h} fill="url(#wasteHatch)" />
          ))}

          {/* Leading / trailing edge */}
          <rect x={0} y={0} width={drawWidth} height={leadingEdge} fill="#fef3c7" />
          <rect x={0} y={drawHeight - trailingEdge} width={drawWidth} height={trailingEdge} fill="#fef3c7" />

          {/* Margin columns */}
          <rect x={0} y={0} width={usableX} height={drawHeight} fill="#fde68a" fillOpacity="0.55" />
          <rect x={usableX + usableWidth} y={0} width={drawWidth - usableX - usableWidth} height={drawHeight} fill="#fde68a" fillOpacity="0.55" />

          {/* Registration marks */}
          {regMarks.map((m, i) => (
            <g key={`reg-${i}`} stroke="#0f172a" strokeWidth={0.07} fill="none">
              <line x1={m.x - 0.4} y1={m.y} x2={m.x + 0.4} y2={m.y} />
              <line x1={m.x} y1={m.y - 0.4} x2={m.x} y2={m.y + 0.4} />
              <circle cx={m.x} cy={m.y} r="0.25" />
            </g>
          ))}

          {/* Parts */}
          {shelves.map((sh, sIdx) =>
            sh.items.map((it, iIdx) => {
              const fill = colorFor[it.itemIdx] || "#3b82f6";
              const dragKey = `${sIdx}-${iIdx}`;
              const xOverride = dragOverrides[dragKey];
              const itemX = xOverride !== undefined ? xOverride : it.x;
              const bleed = it.bleed || 0;
              const partW = it.partW ?? it.w;
              const partH = it.partH ?? it.h;
              const isDragging = dragging && dragging.shelfIdx === sIdx && dragging.itemIdx === iIdx;

              return (
                <g
                  key={`${sIdx}-${iIdx}`}
                  onMouseDown={(e) => handleMouseDown(e, sIdx, iIdx, it)}
                  style={{ cursor: onItemMove ? (isDragging ? "grabbing" : "grab") : "default" }}
                >
                  {/* OUTER (bleed halo) — only renders if bleed > 0 */}
                  {bleed > 0 && (
                    <rect
                      x={usableX + itemX} y={leadingEdge + it.y}
                      width={it.w} height={it.h}
                      fill="url(#bleedHatch)"
                      stroke="#ea580c" strokeWidth={0.04} strokeDasharray="0.3,0.2"
                    />
                  )}

                  {/* INNER (actual part) */}
                  <rect
                    x={usableX + itemX + bleed} y={leadingEdge + it.y + bleed}
                    width={partW} height={partH}
                    fill={fill} fillOpacity={isDragging ? 0.6 : 0.85}
                    stroke="#0f172a" strokeWidth={0.05}
                  />

                  {/* Feed direction arrow */}
                  {partW > 6 && partH > 6 && (
                    <path
                      d={`M ${usableX + itemX + bleed + partW / 2} ${leadingEdge + it.y + bleed + 0.5}
                          L ${usableX + itemX + bleed + partW / 2} ${leadingEdge + it.y + bleed + Math.min(partH - 1, 2.2)}`}
                      stroke="white" strokeWidth={0.18} strokeOpacity="0.6"
                      markerEnd="url(#arrow)" pointerEvents="none"
                    />
                  )}

                  {partW > 6 && partH > 4 && (
                    <text
                      x={usableX + itemX + bleed + partW / 2}
                      y={leadingEdge + it.y + bleed + partH / 2}
                      textAnchor="middle" dominantBaseline="middle"
                      fontSize={Math.min(partW / 7, partH / 3, 2.2)}
                      fill="white"
                      style={{ pointerEvents: "none", fontWeight: 600 }}
                    >
                      {partW.toFixed(1)}×{partH.toFixed(1)}{it.rotated ? " ↻" : ""}
                    </text>
                  )}
                </g>
              );
            })
          )}

          {/* Roll outline */}
          <rect x={0} y={0} width={drawWidth} height={drawHeight} fill="none" stroke="#0f172a" strokeWidth={0.1} pointerEvents="none" />
          </svg>
        </div>

        {/* Pinned footer — always visible regardless of SVG scroll */}
        <div className="border-t border-slate-300 bg-slate-50 px-3 py-2 space-y-1">
          <div className="flex items-center justify-center gap-1 text-[10px] text-slate-500">
            <ArrowDown className="w-3 h-3" /> Print feed direction (top → bottom)
          </div>
          <div className="flex flex-wrap gap-3 text-[11px]">
            <LegendChip color="#fde68a" label="Margin (unprintable)" />
            <LegendChip color="#fef3c7" label="Leading/trailing edge waste" />
            <LegendSwatchHatch label="Waste in usable area" patternId="legendHatchWaste" baseFill="#fecaca" stroke="#dc2626" />
            <LegendSwatchHatch label="Bleed halo (waste around part)" patternId="legendHatchBleed" baseFill="#fed7aa" stroke="#ea580c" />
            {showRegistrationMarks && <LegendChip color="#0f172a" label="Registration marks" />}
            <LegendChip color="#ffffff" label="Usable" border />
            {Object.entries(colorFor).map(([idx, c]) => (
              <LegendChip key={idx} color={c} label={`Item ${parseInt(idx) + 1}`} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

const Stat = ({ label, value, tone }) => {
  const toneClass = tone === "bad" ? "text-red-600" : tone === "warn" ? "text-amber-600" : "text-slate-800";
  return (
    <div className="flex items-baseline gap-1">
      <span className="text-slate-500">{label}:</span>
      <span className={`font-semibold tabular-nums ${toneClass}`}>{value}</span>
    </div>
  );
};

const LegendChip = ({ color, label, border }) => (
  <span className="inline-flex items-center gap-1">
    <span className="inline-block w-3 h-3 rounded-sm" style={{ background: color, border: border ? "1px solid #94a3b8" : "none" }} />
    <span className="text-slate-600">{label}</span>
  </span>
);

const LegendSwatchHatch = ({ label, patternId, baseFill, stroke }) => (
  <span className="inline-flex items-center gap-1">
    <svg width="12" height="12" className="inline-block">
      <defs>
        <pattern id={patternId} patternUnits="userSpaceOnUse" width="4" height="4" patternTransform="rotate(45)">
          <rect width="4" height="4" fill={baseFill} fillOpacity="0.6" />
          <line x1="0" y1="0" x2="0" y2="4" stroke={stroke} strokeWidth="1" />
        </pattern>
      </defs>
      <rect width="12" height="12" fill={`url(#${patternId})`} stroke="#94a3b8" strokeWidth="0.5" />
    </svg>
    <span className="text-slate-600">{label}</span>
  </span>
);

// "Best Roll Width" recommender — Feature #10.
//
// Looks at vinyls that share a `product_group_key` (or fall back to the same
// vinyl_name + manufacturer + product_series) with the currently-selected
// vinyl. For each candidate width, re-runs the nesting calculator and picks
// the cheapest viable option. Shows a one-click swap.

import { useMemo } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Lightbulb, ArrowRight } from "lucide-react";
import { calculateVinylProject } from "./vinylNestingCalculator";
import { vinylMaterialIssues } from "./vinylPricingAvailability";

const fmt = (n) => `$${(Number(n) || 0).toFixed(2)}`;

// Build the candidate group for a vinyl: same product_group_key if set,
// otherwise same vinyl_name + manufacturer + product_series.
const groupCandidates = (vinyl, allVinyls) => {
  if (!vinyl) return [];
  const base = allVinyls.filter(v =>
    v.id !== vinyl.id && v.is_active !== false && v.show_in_vinyl_estimator !== false && !v.is_laminate
  );
  if (vinyl.product_group_key) {
    return base.filter(v => v.product_group_key === vinyl.product_group_key);
  }
  return base.filter(v =>
    (v.vinyl_name || "").trim() === (vinyl.vinyl_name || "").trim() &&
    (v.manufacturer || "") === (vinyl.manufacturer || "") &&
    (v.product_series || "") === (vinyl.product_series || "")
  );
};

export default function VinylRollWidthRecommender({
  workflow, vinyl, vinyls, printer, cutter, laminator, transferTape, laminate,
  operatorRate, currentCalc, onPick,
}) {
  const candidates = useMemo(() => groupCandidates(vinyl, vinyls), [vinyl, vinyls]);

  const evaluated = useMemo(() => {
    // A held calc has no honest total to compare against — no recommendations.
    if (!vinyl || candidates.length === 0 || !currentCalc || currentCalc.__held) return [];
    const baseArgs = {
      items: workflow.items || [],
      printer, cutter, laminator,
      laminate, transferTape,
      operatorHourlyRate: operatorRate,
      applyPrint: !!workflow.apply_print,
      applyCut: !!workflow.apply_cut,
      applyLaminate: !!workflow.apply_laminate,
      applyTransferTape: !!workflow.apply_transfer_tape,
      printQuality: workflow.print_quality || printer?.default_print_quality || "high_quality",
      weedingDifficulty: workflow.weeding_difficulty || "moderate",
      installMinutesPerPart: workflow.install_minutes_per_part,
      personnel: workflow.personnel || [],
      spoilageBufferPercent: workflow.spoilage_buffer_percent || 0,
      setupFeeFloor: workflow.setup_fee_floor || 0,
    };
    return candidates
      // A candidate whose own record can't produce a real price would compare
      // a laundered $0 — exclude it, never recommend it.
      .filter(c => vinylMaterialIssues(c, "vinyl", 0, c.id).length === 0)
      .map(c => {
        const calc = calculateVinylProject({ ...baseArgs, vinyl: c });
        return {
          vinyl: c,
          totalCost: calc.totalCost,
          partsUnplaced: calc.partsUnplaced,
          totalRollSqFtPulled: calc.totalRollSqFtPulled,
        };
      })
      .filter(r => r.partsUnplaced === 0)
      .sort((a, b) => a.totalCost - b.totalCost);
  }, [candidates, workflow, printer, cutter, laminator, laminate, transferTape, vinyl, operatorRate, currentCalc]);

  if (!vinyl || candidates.length === 0 || !currentCalc || currentCalc.__held) return null;

  const currentTotal = currentCalc.totalCost || 0;
  const best = evaluated[0];
  // Only suggest if there's a meaningful saving (>2% AND >$1)
  const savings = best ? currentTotal - best.totalCost : 0;
  const showSuggestion = best && savings > 1 && savings / Math.max(currentTotal, 1) > 0.02;

  return (
    <Card className={showSuggestion ? "border-amber-300 bg-amber-50" : "border-slate-200 bg-slate-50"}>
      <CardContent className="p-3 text-xs space-y-2">
        <div className="flex items-center gap-2 font-medium text-slate-800">
          <Lightbulb className={`w-3.5 h-3.5 ${showSuggestion ? "text-amber-600" : "text-slate-500"}`} />
          Roll-Width Options
          <span className="text-[10px] text-slate-500">({candidates.length} alternates in this product group)</span>
        </div>
        {showSuggestion ? (
          <div className="flex items-center justify-between gap-2 bg-white border border-amber-200 rounded p-2">
            <div>
              <div className="font-semibold text-amber-900">
                Switch to {best.vinyl.roll_width_inches}″ width
              </div>
              <div className="text-[11px] text-slate-600">
                Current {vinyl.roll_width_inches}″ = {fmt(currentTotal)} → {best.vinyl.roll_width_inches}″ = {fmt(best.totalCost)}
                <span className="ml-1 text-emerald-700 font-medium">save {fmt(savings)}</span>
              </div>
            </div>
            <Button size="sm" className="h-7 bg-amber-600 hover:bg-amber-700 text-white" onClick={() => onPick(best.vinyl.id)}>
              Use this <ArrowRight className="w-3 h-3 ml-1" />
            </Button>
          </div>
        ) : (
          <div className="text-[11px] text-slate-600">
            Current {vinyl.roll_width_inches}″ width is already the most cost-effective for this part set.
          </div>
        )}
        {evaluated.length > 1 && (
          <div className="flex flex-wrap gap-1 pt-1">
            {evaluated.map(opt => (
              <button type="button"
                key={opt.vinyl.id}
                onClick={() => onPick(opt.vinyl.id)}
                className="text-[10px] px-2 py-0.5 rounded border border-slate-200 bg-white hover:border-blue-300 hover:bg-blue-50 tabular-nums"
                title={`${opt.vinyl.vinyl_name} ${opt.vinyl.roll_width_inches}″`}
              >
                {opt.vinyl.roll_width_inches}″ · {fmt(opt.totalCost)}
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// Searchable popup picker for vinyl / laminate rolls.
// Replaces the plain <Select> dropdown when there are too many options to scan.
// Supports free-text search (name, manufacturer, series, color, category, finish)
// and sorting by name / manufacturer / category / roll width.

import React, { useMemo, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, Check, ArrowUpDown } from "lucide-react";

const SORTS = {
  name: { label: "Name", fn: (a, b) => (a.vinyl_name || "").localeCompare(b.vinyl_name || "") },
  manufacturer: { label: "Manufacturer", fn: (a, b) => (a.manufacturer || "").localeCompare(b.manufacturer || "") },
  category: { label: "Category", fn: (a, b) => (a.vinyl_category || "").localeCompare(b.vinyl_category || "") },
  width: { label: "Roll Width", fn: (a, b) => (a.roll_width_inches || 0) - (b.roll_width_inches || 0) },
};

const matchesQuery = (v, q) => {
  if (!q) return true;
  const hay = [
    v.vinyl_name, v.manufacturer, v.product_series, v.color_name,
    v.vinyl_category, v.finish, v.vinyl_use_case,
  ].filter(Boolean).join(" ").toLowerCase();
  return q.toLowerCase().split(/\s+/).every(term => hay.includes(term));
};

export default function VinylSearchPickerDialog({
  open, onOpenChange, options, selectedId, onSelect, title = "Select Vinyl", allowNone = false,
}) {
  const [query, setQuery] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("q") || ""; } catch { return ""; }
  });
  const [sortKey, setSortKey] = useState("name");

  const filtered = useMemo(() => {
    const list = options.filter(v => matchesQuery(v, query));
    return [...list].sort(SORTS[sortKey].fn);
  }, [options, query, sortKey]);

  const handlePick = (id) => {
    onSelect(id);
    onOpenChange(false);
    setQuery("");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
        </DialogHeader>

        <div className="flex items-center gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <Input
              autoFocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search name, color, manufacturer, category…"
              className="pl-8 h-9"
            />
          </div>
          <Select value={sortKey} onValueChange={setSortKey}>
            <SelectTrigger className="h-9 w-44">
              <ArrowUpDown className="w-3.5 h-3.5 mr-1 text-slate-400" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {Object.entries(SORTS).map(([k, s]) => (
                <SelectItem key={k} value={k}>Sort: {s.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="text-[11px] text-slate-500 px-1">{filtered.length} of {options.length} shown</div>

        <div className="flex-1 overflow-y-auto -mx-1 px-1 space-y-1">
          {allowNone && (
            <button type="button"
              onClick={() => handlePick("")}
              className={`w-full text-left px-3 py-2 rounded-lg border transition-colors flex items-center justify-between ${
                !selectedId ? "border-blue-300 bg-blue-50" : "border-slate-200 hover:bg-slate-50"
              }`}
            >
              <span className="text-sm text-slate-600 italic">None</span>
              {!selectedId && <Check className="w-4 h-4 text-blue-600" />}
            </button>
          )}
          {filtered.map(v => {
            const isSel = v.id === selectedId;
            return (
              <button type="button"
                key={v.id}
                onClick={() => handlePick(v.id)}
                className={`w-full text-left px-3 py-2 rounded-lg border transition-colors flex items-center justify-between gap-3 ${
                  isSel ? "border-blue-300 bg-blue-50" : "border-slate-200 hover:bg-slate-50"
                }`}
              >
                <div className="min-w-0">
                  <div className="text-sm font-medium text-slate-900 truncate">
                    {v.vinyl_name}{v.roll_width_inches ? ` · ${v.roll_width_inches}″` : ""}
                  </div>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {v.manufacturer && <Badge variant="outline" className="text-[10px]">{v.manufacturer}</Badge>}
                    {v.vinyl_category && <Badge variant="outline" className="text-[10px]">{v.vinyl_category}</Badge>}
                    {v.finish && <Badge variant="outline" className="text-[10px]">{v.finish}</Badge>}
                    {v.color_name && <Badge variant="outline" className="text-[10px]">{v.color_name}</Badge>}
                  </div>
                </div>
                {isSel && <Check className="w-4 h-4 text-blue-600 flex-shrink-0" />}
              </button>
            );
          })}
          {filtered.length === 0 && (
            <div className="text-center text-sm text-slate-400 py-10">No matches for “{query}”.</div>
          )}
        </div>

        <div className="flex justify-end pt-2 border-t">
          <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>Cancel</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// Roll-stock + multi-roll planning warning. Features #6 & #37.

import React from "react";
import { AlertTriangle, Layers, CheckCircle2 } from "lucide-react";

export default function VinylStockWarning({ stockUsage, vinyl }) {
  if (!stockUsage || !vinyl) return null;
  const { rollsNeeded, percentOfRoll, fullRollsNeeded, exceedsOneRoll } = stockUsage;

  if (!exceedsOneRoll && percentOfRoll < 90) {
    return (
      <div className="flex items-center gap-2 text-xs text-emerald-700 bg-emerald-50 border border-emerald-200 rounded px-2 py-1.5">
        <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" />
        Uses <b className="tabular-nums">{percentOfRoll.toFixed(1)}%</b> of one roll.
      </div>
    );
  }

  if (!exceedsOneRoll) {
    return (
      <div className="flex items-center gap-2 text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
        <AlertTriangle className="w-3.5 h-3.5 flex-shrink-0" />
        Uses <b className="tabular-nums">{percentOfRoll.toFixed(1)}%</b> of a single roll — very close to the end.
      </div>
    );
  }

  return (
    <div className="flex items-start gap-2 text-xs text-red-800 bg-red-50 border border-red-200 rounded px-2 py-1.5">
      <Layers className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
      <div>
        <div className="font-semibold">Multi-roll job</div>
        <div>
          Needs <b className="tabular-nums">{rollsNeeded.toFixed(2)}</b> rolls
          {" "}(<b>{fullRollsNeeded}</b> full rolls of {vinyl.vinyl_name}).
          Each roll has its own leading/trailing edge waste — costs are estimated based on total pulled length.
        </div>
      </div>
    </div>
  );
}

// Right-side summary panel — cost breakdown + supplies & markup inputs.

import React from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const fmt = (n) => `$${Number(n || 0).toFixed(2)}`;

const Line = ({ label, value, muted, bold }) => (
  <div className={`flex justify-between text-sm ${muted ? "text-slate-500" : "text-slate-800"} ${bold ? "font-bold text-base" : ""}`}>
    <span>{label}</span>
    <span className="tabular-nums">{value}</span>
  </div>
);

export default function VinylSummaryPanel({
  calc, vinyl, laminate, printer, cutter, laminator,
  suppliesPercent, onSuppliesPercentChange,
  extraSupplies, onExtraSuppliesChange,
  markupPercent, onMarkupPercentChange,
  personnelCost = 0,
}) {
  const baseSupplies = (calc.materialCost || 0) * ((parseFloat(suppliesPercent) || 0) / 100);
  const supplies = baseSupplies + (parseFloat(extraSupplies) || 0);
  const subtotal = calc.totalCost + supplies + personnelCost;
  const markupAmt = subtotal * ((parseFloat(markupPercent) || 0) / 100);
  const grandTotal = subtotal + markupAmt;

  return (
    <Card className="sticky top-4">
      <CardHeader className="pb-2"><CardTitle className="text-base">Estimate Summary</CardTitle></CardHeader>
      <CardContent className="space-y-3 text-sm">
        <div className="space-y-1">
          <Line label={`Vinyl${vinyl ? ` · ${vinyl.vinyl_name}` : ""}`} value={fmt(calc.vinylCost)} />
          {laminate && <Line label={`Laminate · ${laminate.vinyl_name}`} value={fmt(calc.laminateCost)} />}
          {printer && <Line label="Ink" value={fmt(calc.inkCost)} muted />}
          {cutter && <Line label="Blade Wear" value={fmt(calc.bladeCost)} muted />}
        </div>

        <div className="border-t pt-2 space-y-1">
          <Line label="Machine Time" value={fmt(calc.machineCost)} />
          <Line label={`Labor · ${calc.laborHours.toFixed(2)} hr`} value={fmt(calc.laborCost)} />
          {personnelCost > 0 && <Line label="Personnel" value={fmt(personnelCost)} />}
        </div>

        <div className="border-t pt-3 space-y-2">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <Label className="text-[11px]">Supplies %</Label>
              <Input type="number" step="0.5" value={suppliesPercent} onChange={(e) => onSuppliesPercentChange(parseFloat(e.target.value) || 0)} className="h-8 text-sm tabular-nums" />
            </div>
            <div>
              <Label className="text-[11px]">Extra Supplies $</Label>
              <Input type="number" step="1" value={extraSupplies} onChange={(e) => onExtraSuppliesChange(parseFloat(e.target.value) || 0)} className="h-8 text-sm tabular-nums" />
            </div>
          </div>
          <Line label="Supplies Total" value={fmt(supplies)} muted />
        </div>

        <div className="border-t pt-3 space-y-2">
          <div>
            <Label className="text-[11px]">Markup %</Label>
            <Input type="number" step="0.5" value={markupPercent} onChange={(e) => onMarkupPercentChange(parseFloat(e.target.value) || 0)} className="h-8 text-sm tabular-nums" />
          </div>
          <Line label="Subtotal" value={fmt(subtotal)} muted />
          <Line label="Markup" value={fmt(markupAmt)} muted />
        </div>

        <div className="border-t pt-3 bg-slate-900 text-white -mx-6 -mb-6 px-6 py-4 rounded-b-xl">
          <div className="flex justify-between font-bold text-lg">
            <span>Total</span>
            <span className="tabular-nums">{fmt(grandTotal)}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// One vinyl workflow card.
// Upgrades:
//   #1  Manual part order toggle (override NFDH height-sort)
//   #5  Workflow preset bar
//   #6  Stock usage warning
//   #14 Color tag in header
//   #16 Apply / save template button
//   #19 Per-part cost passed into the parts table
//   #20 + #21 Yield/margin badge in header
//   #22 Vinyl comparison panel
//   #33 Tab-level "issue" dot via _hasIssues

import { useState, useMemo, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Sliders, AlertTriangle } from "lucide-react";

import VinylMaterialPicker from "./VinylMaterialPicker";
import VinylMachinePicker from "./VinylMachinePicker";
import VinylPartsTable from "./VinylPartsTable";
import VinylRollVisualizer from "./VinylRollVisualizer";
import VinylPresetBar from "./VinylPresetBar";
import VinylStockWarning from "./VinylStockWarning";
import VinylAlternativeCompare from "./VinylAlternativeCompare";
import VinylWorkflowTemplatesDialog from "./VinylWorkflowTemplatesDialog";
import VinylWorkflowCardHeader, { COLOR_SWATCHES } from "./VinylWorkflowCardHeader";
import VinylCuttingExtrasCard from "./VinylCuttingExtrasCard";
import VinylWorkflowPersonnel from "./VinylWorkflowPersonnel";
import VinylRollWidthRecommender from "./VinylRollWidthRecommender";
import { calcVinylWorkflow, hasIssueFor } from "./vinylPricingAvailability";
import { applyPresetToWorkflow } from "./vinylWorkflowPresets";
import {
  computePerPartCosts, computeWorkflowMetrics, computeStockUsage,
} from "./vinylCostHelpers";
import { loadVinylLaborRoles, MACHINE_AUTO_ROLES, suggestedHoursForRole } from "./vinylLaborRoles";

const num = (v) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

export default function VinylWorkflowCard({
  workflow, index, vinyls, machines,
  onChange, onRemove, onDuplicate, onMovePartToWorkflow,
  installEnvironment = "exterior",
  defaultOpen = true,
  pricing: pricingProp, // optional shared { calc, issues, held, resolved }
}) {
  const [open, setOpen] = useState(defaultOpen);
  const [templatesOpen, setTemplatesOpen] = useState(false);
  const [templatesMode, setTemplatesMode] = useState("apply");
  const [recommendOnly, setRecommendOnly] = useState(false);
  const [showCompare, setShowCompare] = useState(false);
  const [roleOptions, setRoleOptions] = useState([]);

  // Respond to parent expand/collapse-all toggle
  useEffect(() => { setOpen(defaultOpen); }, [defaultOpen]);

  // Load vinyl labor roles (rates) from the Labor Inventory once.
  useEffect(() => { loadVinylLaborRoles().then(setRoleOptions).catch((e) => console.error("Vinyl labor roles failed to load:", e)); }, []);

  const set = (patch) => onChange({ ...workflow, ...patch });

  // Pricing-availability wrap: the same calculation the card has always run,
  // now with strict input validation. `pricing.calc` is the held/poisoned
  // result when any consumed input is unavailable; `pricing.issues` carries
  // the structured diagnostics. The page may share one computation across
  // every workflow via the `pricing` prop — otherwise the card computes its
  // own so it stays self-contained.
  const pricing = useMemo(
    () => pricingProp ?? calcVinylWorkflow({ workflow, vinyls, machines, index }),
    [pricingProp, workflow, vinyls, machines, index],
  );
  const calc = pricing.calc;
  const pricingIssues = pricing.issues || [];
  const held = !!pricing.held;

  const { printer, cutter, laminator, vinyl, laminate, transferTape } = pricing.resolved;
  const operatorRate = printer?.operator_hourly_rate ?? cutter?.operator_hourly_rate ?? laminator?.operator_hourly_rate ?? 45;

  // Drag-and-drop: a per-item manual x override that the calculator doesn't know about
  // but we apply on the placed shelves directly for visual rendering. Stored in a
  // workflow.items[].manual_layout = { x } map.
  const calcWithManualPositions = useMemo(() => {
    if (!workflow.manual_positions) return calc;
    const shelves = calc.shelves.map((sh, sIdx) => ({
      ...sh,
      items: sh.items.map((it, iIdx) => {
        const key = `${sIdx}-${iIdx}`;
        const override = workflow.manual_positions[key];
        return override !== undefined ? { ...it, x: override } : it;
      }),
    }));
    return { ...calc, shelves };
  }, [calc, workflow.manual_positions]);

  const handleItemMove = ({ shelfIdx, itemIdx, x }) => {
    const key = `${shelfIdx}-${itemIdx}`;
    set({
      manual_positions: { ...(workflow.manual_positions || {}), [key]: x },
    });
  };

  // Per-part cost rollup — Feature #19. Held calcs keep the parts but the
  // costs are unavailable — don't paint $0 allocations on real rows.
  const perPartCosts = useMemo(
    () => (held ? {} : computePerPartCosts(calc, workflow.items || [])),
    [held, calc, workflow.items],
  );
  // Yield / cost metrics — Feature #20, #21
  const metrics    = useMemo(() => computeWorkflowMetrics(calc), [calc]);
  // Stock usage — Feature #6, #37
  const stockUsage = useMemo(() => computeStockUsage(calc, vinyl), [calc, vinyl]);

  // Surface calc back up so the project rollup can sum across workflows.
  // _hasIssues now also covers pricing-availability issues — the tab badge
  // and the save guard both read it.
  useEffect(() => {
    const hasIssues = pricingIssues.length > 0 || calc.partsUnplaced > 0 || !workflow.vinyl_id;
    if (workflow._calc?.totalCost !== calc.totalCost
     || workflow._calc?.materialCost !== calc.materialCost
     || workflow._hasIssues !== hasIssues) {
      onChange({ ...workflow, _calc: calc, _hasIssues: hasIssues });
    }
  }, [calc.totalCost, calc.materialCost, calc.machineCost, calc.laborCost, calc.partsUnplaced, workflow.vinyl_id, pricingIssues.length]);

  // Auto-select operator roles when machines are applied. Adds any missing role
  // for the active machines and auto-fills its hours from the calculator. Runs
  // after roles are loaded and recomputes hours as the calc changes.
  useEffect(() => {
    if (roleOptions.length === 0) return;
    const wanted = new Set();
    if (workflow.apply_print && workflow.printer_id)      MACHINE_AUTO_ROLES.printer.forEach(r => wanted.add(r));
    if (workflow.apply_cut && workflow.cutter_id)         MACHINE_AUTO_ROLES.cutter.forEach(r => wanted.add(r));
    if (workflow.apply_laminate && workflow.laminator_id) MACHINE_AUTO_ROLES.laminator.forEach(r => wanted.add(r));
    if (wanted.size === 0) return;

    const current = workflow.personnel || [];
    let changed = false;
    const next = [...current];
    wanted.forEach((role) => {
      const opt = roleOptions.find(r => r.role === role);
      if (!opt) return;
      const existing = next.find(p => p.role === role);
      const hrs = suggestedHoursForRole(role, calc);
      if (!existing) {
        next.push({ role, hourly_rate: opt.hourly_rate, hours: hrs, total_cost: opt.hourly_rate * hrs, _auto: true });
        changed = true;
      } else if (existing._auto && Math.abs(num(existing.hours) - hrs) > 0.001) {
        // Keep auto-added rows in sync with the calculator until the user edits.
        existing.hours = hrs;
        existing.total_cost = num(existing.hourly_rate) * hrs;
        changed = true;
      }
    });
    if (changed) set({ personnel: next });
  }, [
    roleOptions, workflow.apply_print, workflow.apply_cut, workflow.apply_laminate,
    workflow.printer_id, workflow.cutter_id, workflow.laminator_id,
    calc.printMinutes, calc.cutMinutes, calc.laminateMinutes, calc.weedingMinutes, calc.installMinutes,
  ]);

  const colorTag = workflow.color_tag || COLOR_SWATCHES[index % COLOR_SWATCHES.length];

  return (
    <Card
      className="bg-white border border-slate-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden"
      style={{ borderLeft: `4px solid ${colorTag}` }}
    >
      <VinylWorkflowCardHeader
        workflow={workflow}
        index={index}
        vinyl={vinyl}
        calc={calc}
        metrics={metrics}
        colorTag={colorTag}
        open={open}
        onToggleOpen={() => setOpen(!open)}
        onChange={set}
        onSaveTemplate={() => { setTemplatesMode("save"); setTemplatesOpen(true); }}
        onDuplicate={onDuplicate}
        onRemove={onRemove}
      />

      {open && (
        <CardContent className="space-y-4 pt-2 border-t border-slate-100">
          {/* Pricing-availability diagnostics — calculation rows stay visible;
              tainted totals show "Not saved" instead of a laundered $0. */}
          {pricingIssues.length > 0 && (
            <div
              role="status"
              id={`vinyl-wf-${index}-issues`}
              className="flex items-start gap-2 text-xs text-amber-900 bg-amber-50 border border-amber-200 rounded px-3 py-2"
            >
              <AlertTriangle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0 text-amber-600" />
              <div>
                <div className="font-semibold">Pricing unavailable — {pricingIssues.length} value{pricingIssues.length === 1 ? "" : "s"} need attention</div>
                <ul className="mt-1 space-y-0.5 list-disc list-inside">
                  {pricingIssues.slice(0, 6).map((it, i) => <li key={i}>{it.message}</li>)}
                  {pricingIssues.length > 6 && <li>…and {pricingIssues.length - 6} more</li>}
                </ul>
              </div>
            </div>
          )}

          {/* Preset bar — Feature #5 */}
          <VinylPresetBar
            activePresetKey={workflow.preset_key}
            onApply={(preset) => set({ ...applyPresetToWorkflow(preset) })}
          />

          <VinylMaterialPicker
            vinyls={vinyls}
            vinylId={workflow.vinyl_id}
            laminateId={workflow.laminate_id}
            applyLaminate={!!workflow.apply_laminate}
            presetKey={workflow.preset_key}
            installEnvironment={installEnvironment}
            recommendOnly={recommendOnly}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            onChange={({ vinylId, laminateId, applyLaminate, recommendOnly: ro }) => {
              if (ro !== undefined) setRecommendOnly(ro);
              if (vinylId !== undefined || laminateId !== undefined || applyLaminate !== undefined) {
                set({
                  vinyl_id: vinylId,
                  laminate_id: laminateId || "",
                  apply_laminate: !!applyLaminate,
                });
              }
            }}
          />

          {/* Stock check — Feature #6 & #37 */}
          {stockUsage && <VinylStockWarning stockUsage={stockUsage} vinyl={vinyl} />}

          {/* Compare to other vinyls — Feature #22 */}
          {vinyl && calc.vinylCost > 0 && (
            <div>
              <button type="button" onClick={() => setShowCompare(s => !s)} className="text-[11px] underline text-blue-600">
                {showCompare ? "Hide" : "Show"} cost comparison vs other vinyls
              </button>
              {showCompare && (
                <div className="mt-2">
                  <VinylAlternativeCompare calc={calc} currentVinyl={vinyl} vinyls={vinyls} />
                </div>
              )}
            </div>
          )}

          {/* Roll-width recommender (#10) */}
          <VinylRollWidthRecommender
            workflow={workflow}
            vinyl={vinyl}
            vinyls={vinyls}
            printer={printer}
            cutter={cutter}
            laminator={laminator}
            laminate={laminate}
            transferTape={transferTape}
            operatorRate={operatorRate}
            currentCalc={calc}
            onPick={(id) => set({ vinyl_id: id })}
          />

          <VinylMachinePicker
            machines={machines}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            value={{
              printer_id:   workflow.printer_id,
              cutter_id:    workflow.cutter_id,
              laminator_id: workflow.laminator_id,
              applyPrint:    !!workflow.apply_print,
              applyCut:      !!workflow.apply_cut,
              applyLaminate: !!workflow.apply_laminate,
              printQuality:  workflow.print_quality || printer?.default_print_quality || "high_quality",
            }}
            onChange={(v) => {
              const patch = {};
              if (v.printer_id   !== undefined) patch.printer_id   = v.printer_id;
              if (v.cutter_id    !== undefined) patch.cutter_id    = v.cutter_id;
              if (v.laminator_id !== undefined) patch.laminator_id = v.laminator_id;
              if (v.applyPrint    !== undefined) patch.apply_print    = v.applyPrint;
              if (v.applyCut      !== undefined) patch.apply_cut      = v.applyCut;
              if (v.applyLaminate !== undefined) patch.apply_laminate = v.applyLaminate;
              if (v.printQuality  !== undefined) patch.print_quality  = v.printQuality;
              set(patch);
            }}
          />

          {/* Workflow-level cost knobs: spoilage buffer + setup fee floor */}
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Workflow Cost Controls</CardTitle>
            </CardHeader>
            <CardContent className="grid md:grid-cols-2 gap-4 text-xs">
              <div>
                <label className="text-[10px] uppercase tracking-wider text-slate-500">Spoilage / Reprint Buffer (%)</label>
                <Input
                  type="number" step="1" min="0"
                  value={workflow.spoilage_buffer_percent ?? ""}
                  placeholder="0"
                  onChange={(e) => set({ spoilage_buffer_percent: e.target.value })}
                  aria-invalid={hasIssueFor(pricingIssues, "spoilage_buffer_percent") || undefined}
                  aria-describedby={hasIssueFor(pricingIssues, "spoilage_buffer_percent") ? `vinyl-wf-${index}-issues` : undefined}
                  className="h-8 tabular-nums"
                />
                <p className="text-[10px] text-slate-500 mt-1">Adds N% extra qty to every part before nesting.</p>
              </div>
              <div>
                <label className="text-[10px] uppercase tracking-wider text-slate-500">Setup-Fee Floor ($)</label>
                <Input
                  type="number" step="1" min="0"
                  value={workflow.setup_fee_floor ?? ""}
                  placeholder="0"
                  onChange={(e) => set({ setup_fee_floor: e.target.value })}
                  aria-invalid={hasIssueFor(pricingIssues, "setup_fee_floor") || undefined}
                  aria-describedby={hasIssueFor(pricingIssues, "setup_fee_floor") ? `vinyl-wf-${index}-issues` : undefined}
                  className="h-8 tabular-nums"
                />
                <p className="text-[10px] text-slate-500 mt-1">
                  {(calc.setupFeeApplied ?? 0) > 0
                    ? <span className="text-amber-700 font-medium">Floor adding ${calc.setupFeeApplied.toFixed(2)} to this workflow.</span>
                    : "Workflow minimum charge."}
                </p>
              </div>
            </CardContent>
          </Card>

          {/* Cutting-only extras: transfer tape + weeding difficulty + install labor */}
          {workflow.apply_cut && (
            <VinylCuttingExtrasCard
              vinyls={vinyls}
              transferTapeId={workflow.transfer_tape_id}
              applyTransferTape={!!workflow.apply_transfer_tape}
              weedingDifficulty={workflow.weeding_difficulty}
              weedingMinutesPerPartOverride={workflow.weeding_minutes_per_part_override}
              installMinutesPerPart={workflow.install_minutes_per_part}
              partsPlaced={calc.partsPlaced ?? 0}
              issues={pricingIssues}
              issuesId={`vinyl-wf-${index}-issues`}
              onChange={(p) => {
                const patch = {};
                if (p.transferTapeId   !== undefined) patch.transfer_tape_id   = p.transferTapeId;
                if (p.applyTransferTape !== undefined) patch.apply_transfer_tape = p.applyTransferTape;
                if (p.weedingDifficulty !== undefined) patch.weeding_difficulty = p.weedingDifficulty;
                if (p.weedingMinutesPerPartOverride !== undefined) patch.weeding_minutes_per_part_override = p.weedingMinutesPerPartOverride;
                if (p.installMinutesPerPart !== undefined) patch.install_minutes_per_part = p.installMinutesPerPart;
                set(patch);
              }}
            />
          )}

          {/* Per-personnel labor rates */}
          <VinylWorkflowPersonnel
            personnel={workflow.personnel || []}
            roleOptions={roleOptions}
            onChange={(personnel) => set({ personnel })}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            suggestedHours={held ? 0 : (calc.machineRunMinutes + calc.weedingMinutes + calc.installMinutes) / 60}
          />

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Parts in this workflow</CardTitle>
            </CardHeader>
            <CardContent>
              <VinylPartsTable
                items={workflow.items || []}
                onChange={(items) => set({ items, manual_positions: {} })}
                perPartCosts={perPartCosts}
                issues={pricingIssues}
                issuesId={`vinyl-wf-${index}-issues`}
                usableWidth={calc.usableWidth}
                defaultBleed={workflow.apply_cut ? 0 : 0.125}
                onMoveToWorkflow={onMovePartToWorkflow ? (partIdx) => onMovePartToWorkflow(partIdx) : null}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between flex-wrap gap-2">
                <CardTitle className="text-sm">Roll Layout</CardTitle>
                <div className="flex items-center gap-2 text-xs">
                  <Sliders className="w-3.5 h-3.5 text-slate-400" />
                  <span className="text-slate-500">Gutter H</span>
                  <Input
                    type="number" step="0.0625"
                    placeholder={String(calc.gutterH)}
                    value={workflow.gutter_h_override ?? ""}
                    onChange={(e) => set({ gutter_h_override: e.target.value })}
                    aria-invalid={hasIssueFor(pricingIssues, "gutter_h_override") || undefined}
                    aria-describedby={hasIssueFor(pricingIssues, "gutter_h_override") ? `vinyl-wf-${index}-issues` : undefined}
                    className="h-7 w-16 text-xs tabular-nums"
                  />
                  <span className="text-slate-500">V</span>
                  <Input
                    type="number" step="0.0625"
                    placeholder={String(calc.gutterV)}
                    value={workflow.gutter_v_override ?? ""}
                    onChange={(e) => set({ gutter_v_override: e.target.value })}
                    aria-invalid={hasIssueFor(pricingIssues, "gutter_v_override") || undefined}
                    aria-describedby={hasIssueFor(pricingIssues, "gutter_v_override") ? `vinyl-wf-${index}-issues` : undefined}
                    className="h-7 w-16 text-xs tabular-nums"
                  />
                  {(workflow.gutter_h_override || workflow.gutter_v_override || workflow.manual_positions) && (
                    <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => set({ gutter_h_override: "", gutter_v_override: "", manual_positions: {} })}>
                      Reset
                    </Button>
                  )}
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <VinylRollVisualizer
                calc={calcWithManualPositions}
                showRegistrationMarks={workflow.apply_print && workflow.apply_cut}
                onItemMove={handleItemMove}
              />
            </CardContent>
          </Card>
        </CardContent>
      )}

      <VinylWorkflowTemplatesDialog
        open={templatesOpen}
        onClose={() => setTemplatesOpen(false)}
        mode={templatesMode}
        currentWorkflow={workflow}
        onApply={(patch) => set(patch)}
      />
    </Card>
  );
}

// Header for one VinylWorkflowCard.
// Clean two-row layout:
//   Row 1: chevron + color dot + editable name + total cost (big, right-aligned)
//   Row 2: status badges (parts, vinyl, yield, unplaced) + actions (template / duplicate / delete)
// Color tag picker lives in a popover so it doesn't clutter the body.

import { useState, useRef, useEffect } from "react";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  ChevronDown, ChevronRight, Trash2, Copy, Bookmark,
  AlertTriangle, Pencil, Check, X, Palette,
} from "lucide-react";
import VinylWorkflowMetricsBadge from "./VinylWorkflowMetricsBadge";

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

export const COLOR_SWATCHES = [
  "#3b82f6", "#10b981", "#f59e0b", "#ef4444",
  "#8b5cf6", "#ec4899", "#14b8a6", "#0ea5e9",
];

function NameEditor({ value, placeholder, onSave }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value || "");
  const inputRef = useRef(null);

  useEffect(() => { if (editing) inputRef.current?.focus(); }, [editing]);
  useEffect(() => { setDraft(value || ""); }, [value]);

  const commit = () => { onSave(draft.trim()); setEditing(false); };
  const cancel = () => { setDraft(value || ""); setEditing(false); };

  if (!editing) {
    return (
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setEditing(true); }}
        className="group flex items-center gap-1.5 min-w-0 max-w-full text-left rounded px-1.5 py-0.5 hover:bg-slate-100 transition-colors"
        title="Click to rename"
      >
        <CardTitle className="text-base truncate">
          {value || <span className="text-slate-400 font-normal">{placeholder}</span>}
        </CardTitle>
        <Pencil className="w-3 h-3 text-slate-300 group-hover:text-slate-500 flex-shrink-0" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1 min-w-0" onClick={(e) => e.stopPropagation()}>
      <input
        ref={inputRef}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit();
          else if (e.key === "Escape") cancel();
        }}
        onBlur={commit}
        placeholder={placeholder}
        className="h-7 text-base font-semibold px-1.5 rounded border border-blue-400 focus:outline-none focus:ring-2 focus:ring-blue-200 min-w-0 flex-1"
      />
      <Button size="icon" variant="ghost" className="h-6 w-6" onMouseDown={(e) => { e.preventDefault(); commit(); }}>
        <Check className="w-3.5 h-3.5 text-green-600" />
      </Button>
      <Button size="icon" variant="ghost" className="h-6 w-6" onMouseDown={(e) => { e.preventDefault(); cancel(); }}>
        <X className="w-3.5 h-3.5 text-slate-500" />
      </Button>
    </div>
  );
}

function ColorTagPicker({ value, onChange }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative">
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setOpen(o => !o); }}
        className="w-5 h-5 rounded-full ring-2 ring-white shadow border border-slate-200 hover:scale-110 transition-transform flex-shrink-0"
        style={{ background: value }}
        title="Change color tag"
      />
      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div
            className="absolute top-7 left-0 z-50 bg-white border border-slate-200 rounded-lg shadow-lg p-2"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center gap-1 mb-1.5 text-[10px] text-slate-500 font-medium">
              <Palette className="w-3 h-3" /> COLOR TAG
            </div>
            <div className="grid grid-cols-4 gap-1.5">
              {COLOR_SWATCHES.map(c => (
                <button type="button"
                  key={c}
                  onClick={() => { onChange(c); setOpen(false); }}
                  className={`w-6 h-6 rounded-full transition-all ${value === c ? "ring-2 ring-slate-900 ring-offset-1" : "hover:scale-110"}`}
                  style={{ background: c }}
                  aria-label={`Set color ${c}`}
                />
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

