// Apply a preset to a workflow (returns patch only — caller merges).
export const applyPresetToWorkflow = (preset) => ({
  apply_print: preset.apply_print,
  apply_cut: preset.apply_cut,
  apply_laminate: preset.apply_laminate,
  preset_key: preset.key,
});

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

// ---------- strict priced-input resolution (pricing-availability hardening) --
// Finite number or null. Accepts real numbers and trimmed numeric strings;
// rejects "", "abc", Infinity, NaN, hex/octal strings, null, undefined, objects.
// `Number()` alone would accept "0x10" → 16 and launder it silently.
export const paintStrictNumber = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string") {
    const t = v.trim();
    if (t === "") return null;
    if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t)) return null;
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

// A Settings value that was actually recorded — absent rows/blank text fall
// back to the module default by design (see moduleSettingDefaults).
export const paintSettingRecorded = (settings, key) => {
  const v = settings?.[key];
  return v !== undefined && v !== null && !(typeof v === "string" && v.trim() === "");
};

// Strict settings read: a recorded finite value is honored verbatim — an
// explicit 0 stays 0 where the key allows it (the old `num(x,d)||d` revived
// the default and made a deliberate $0 impossible). Absent/blank/malformed or
// out-of-range values resolve the fallback exactly like before; the
// availability layer flags every recorded-but-unusable value separately.
//   positive: true  → value must be > 0 (coverage, ratios that are the paint
//                     itself, waste multiplier, letter perimeter factor)
//   positive: false → value must be >= 0 (rates, multipliers, hours, floors,
//                     costs — an explicit 0 is a legitimate free/zero amount)
export const paintSettingNumber = (settings, key, fallback, { positive = false } = {}) => {
  if (!paintSettingRecorded(settings, key)) return fallback;
  const n = paintStrictNumber(settings[key]);
  if (n === null) return fallback;
  if (positive ? n <= 0 : n < 0) return fallback;
  return n;
};

export const PAINT_THICKNESSES = [
  "1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8", "1",
  "1-1/8", "1-1/4", "1-3/8", "1-1/2", "1-5/8", "1-3/4", "1-7/8", "2",
  "2-1/4", "2-1/2", "2-3/4", "3", "3-1/4", "3-1/2", "3-3/4", "4",
];

export function parseImperialFraction(value) {
  if (typeof value !== "string") return num(value);
  let text = value.trim();
  if (!text) return 0;
  let total = 0;
  const wholeAndFraction = text.split("-");
  if (wholeAndFraction.length === 2) {
    total += num(wholeAndFraction[0]);
    text = wholeAndFraction[1];
  } else {
    text = wholeAndFraction[0];
  }
  const parts = text.split("/");
  if (parts.length === 2) {
    const denominator = num(parts[1]);
    if (denominator) total += num(parts[0]) / denominator;
  } else {
    total += num(text);
  }
  return total;
}

// Strict sibling of parseImperialFraction — same grammar ("a", "a/b",
// "a-b/c"), but malformed text resolves null instead of silently 0 so the
// availability layer can flag it ("-1" laundered to +1 and "1/0" to 0 before).
export function paintThicknessNumber(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string") return null;
  let text = value.trim();
  if (!text) return null;
  let total = 0;
  const wholeAndFraction = text.split("-");
  if (wholeAndFraction.length === 2) {
    const whole = paintStrictNumber(wholeAndFraction[0]);
    if (whole === null) return null;
    total += whole;
    text = wholeAndFraction[1];
  } else if (wholeAndFraction.length > 2) {
    return null;
  } else {
    text = wholeAndFraction[0];
  }
  const parts = text.split("/");
  if (parts.length === 2) {
    const numerator = paintStrictNumber(parts[0]);
    const denominator = paintStrictNumber(parts[1]);
    if (numerator === null || denominator === null || denominator === 0) return null;
    total += numerator / denominator;
  } else if (parts.length === 1) {
    const n = paintStrictNumber(text);
    if (n === null) return null;
    total += n;
  } else {
    return null;
  }
  return Number.isFinite(total) ? total : null;
}

function parseTiers(raw) {
  if (Array.isArray(raw)) return raw;
  try {
    const parsed = JSON.parse(raw || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function laborTierMultiplier(settings, itemType, quantity) {
  const settingKey = itemType === "panel"
    ? "panel_labor_tiers"
    : itemType === "complex_shapes"
      ? "complex_shapes_labor_tiers"
      : itemType === "lettering"
        ? "lettering_labor_tiers"
        : "";
  if (!settingKey) return 1;
  const tiers = parseTiers(settings?.[settingKey]);
  const qty = num(quantity, 1);
  const tier = tiers.find((row) => qty >= num(row.min_quantity) && qty <= num(row.max_quantity));
  return tier ? num(tier.labor_multiplier, 1) : 1;
}

function costPerGallon(cost, unit) {
  const unitFactors = { oz: 128, pint: 8, quart: 4, liter: 3.78541, gallon: 1 };
  const factor = unitFactors[unit];
  return factor ? num(cost) * factor : 0;
}

export function liquidPaintRatePerSqft(settings = {}) {
  const paintCost = costPerGallon(paintSettingNumber(settings, "paint_cost_per_unit", 0), settings.paint_unit);
  const hardenerCost = costPerGallon(paintSettingNumber(settings, "hardener_cost_per_unit", 0), settings.hardener_unit);
  const reducerCost = costPerGallon(paintSettingNumber(settings, "reducer_cost_per_unit", 0), settings.reducer_unit);
  const paintRatio = paintSettingNumber(settings, "paint_mix_ratio", 3, { positive: true });
  const hardenerRatio = paintSettingNumber(settings, "hardener_mix_ratio", 1);
  const reducerRatio = paintSettingNumber(settings, "reducer_mix_ratio", 1);
  const totalRatio = paintRatio + hardenerRatio + reducerRatio;
  const mixCost = totalRatio > 0
    ? (paintCost / totalRatio * paintRatio) + (hardenerCost / totalRatio * hardenerRatio) + (reducerCost / totalRatio * reducerRatio)
    : 0;
  // Coverage defaults to the canonical 350 sq ft/gal here too — the old ||1
  // fallback priced mixCost/1 (≈350x too high) when the setting was unset.
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  return coverage > 0 ? mixCost / coverage : 0;
}

export function autoPaintMaskSqft(item = {}) {
  if (!(num(item.length) > 0 && num(item.width) > 0)) return 0;
  let faceArea = 0;
  if (item.item_type === "lettering") {
    const letterHeight = num(item.width);
    const letterCount = num(item.length);
    faceArea = (letterHeight ** 2 * 0.8 * letterCount) / 144;
  } else {
    faceArea = num(item.length) * num(item.width) / 144;
  }
  return item.paint_sides === "both_sides" ? faceArea * 2 : faceArea;
}

export function normalizePaintingItem(item = {}) {
  // Remote expressed the post-spread normalization as duplicate literal keys
  // (last wins). Post-construction assignment keeps the same semantics, the
  // same key order, and a warning-free bundle.
  const normalized = {
    item_type: "panel",
    description: "",
    thickness: "1/2",
    length: 0,
    width: 0,
    quantity: 1,
    edge_complexity_multiplier: 1,
    paint_sides: "one_side",
    paint_colors: [""],
    letter_size: "normal",
    paint_mask_sqft: 0,
    base_supplies_cost: 0,
    fixed_waste_gallons: 0,
    supplies_cost: 0,
    paint_cost: 0,
    paint_gallons: 0,
    labor_hours: 0,
    labor_cost: 0,
    ...item,
  };
  normalized.paint_colors = Array.isArray(item.paint_colors) ? item.paint_colors : [];
  normalized.paint_sides = item.paint_sides === "none" ? "one_side" : (item.paint_sides || "one_side");
  return normalized;
}

export function calculatePaintingItem(rawItem, settings = {}, liquidRate = 0, projectPaintSuppliesRate = 0) {
  const item = normalizePaintingItem(rawItem);
  const perimFactor = paintSettingNumber(settings, "letter_perimeter_factor", 3.5, { positive: true });
  const thickness = parseImperialFraction(item.thickness);
  let paintableSqFt = 0;

  if (item.item_type === "panel" && num(item.length) > 0 && num(item.width) > 0) {
    const faceArea = num(item.length) * num(item.width) / 144;
    const perimeterInches = 2 * (num(item.length) + num(item.width));
    const edgeArea = thickness > 0 ? perimeterInches * thickness / 144 : 0;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  } else if (item.item_type === "lettering" && num(item.width) > 0 && num(item.length) > 0 && thickness > 0) {
    const letterHeight = num(item.width);
    const letterCount = num(item.length);
    const faceArea = (letterHeight ** 2 * 0.8 * letterCount) / 144;
    const perimeterInches = letterHeight * perimFactor * letterCount;
    const edgeArea = perimeterInches * thickness / 144;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  } else if (item.item_type === "complex_shapes" && num(item.length) > 0 && num(item.width) > 0 && thickness > 0) {
    const faceArea = num(item.length) * num(item.width) / 144;
    const perimeterInches = 2 * (num(item.length) + num(item.width));
    const edgeArea = perimeterInches * thickness * num(item.edge_complexity_multiplier, 1) / 144;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  }

  const paintMaskMaterialRate = paintSettingNumber(settings, "paint_mask_rate_per_sqft", 0.75);
  const paintMaskMachineRate = paintSettingNumber(settings, "paint_mask_machine_cutting_rate_per_sqft", 0.10);
  // Preserve SignEstimate Pro behavior exactly: item cost math uses the stored
  // color-array length. Blank entries are only removed when the project is saved.
  const numColors = (item.paint_colors || []).length;
  let paintMaskCost = 0;
  if (numColors > 1 && num(item.paint_mask_sqft) > 0) {
    paintMaskCost = num(item.paint_mask_sqft) * (paintMaskMaterialRate + paintMaskMachineRate) * (numColors - 1);
  }

  let liquidPaintCost = 0;
  let paintApplicationSuppliesCost = 0;
  let paintGallons = 0;
  if (numColors > 0) {
    const wasteMultiplier = paintSettingNumber(settings, "paint_waste_multiplier", 1.25, { positive: true });
    const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
    paintApplicationSuppliesCost = paintableSqFt * num(projectPaintSuppliesRate) * numColors;
    if (liquidRate > 0) liquidPaintCost = paintableSqFt * liquidRate * wasteMultiplier * numColors;
    paintGallons = paintableSqFt * wasteMultiplier * numColors / coverage;
  }

  const itemFixedWasteGallons = num(item.fixed_waste_gallons);
  paintGallons += itemFixedWasteGallons;
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  liquidPaintCost += itemFixedWasteGallons * liquidRate * coverage;
  const liquidPaintAndSuppliesCost = paintApplicationSuppliesCost + liquidPaintCost + num(item.base_supplies_cost);

  // Positive-required: the mask-labor terms below divide by this rate, so an
  // explicit 0 can never mean "free labor" here — it resolves the default and
  // the availability layer flags it.
  const laborRate = paintSettingNumber(settings, "default_labor_rate", 60, { positive: true });
  const baseHoursPerSqFt = paintSettingNumber(settings, "base_labor_hours_per_sqft", 0.05);
  const complexityMap = {
    extra_small: "complex",
    small: "complex",
    normal: "moderate",
    medium: "moderate",
    large: "simple",
    extra_large: "simple",
  };
  const itemComplexity = item.item_type === "lettering" ? complexityMap[item.letter_size] || "moderate" : "moderate";
  const complexityMultipliers = {
    simple: paintSettingNumber(settings, "simple_complexity_multiplier", 0.7),
    moderate: paintSettingNumber(settings, "moderate_complexity_multiplier", 1),
    complex: paintSettingNumber(settings, "complex_complexity_multiplier", 1.5),
  };
  const paintMultipliers = {
    one_side: paintSettingNumber(settings, "one_side_paint_multiplier", 0.8),
    both_sides: paintSettingNumber(settings, "both_sides_paint_multiplier", 1),
  };
  const additionalColorMultiplier = paintSettingNumber(settings, "additional_color_multiplier", 0.3);

  let baseHours = paintableSqFt * baseHoursPerSqFt * (complexityMultipliers[itemComplexity] || 1) * (paintMultipliers[item.paint_sides] || 1);
  if (numColors > 1) baseHours *= 1 + (numColors - 1) * additionalColorMultiplier;

  const maskApplicationLaborRate = paintSettingNumber(settings, "paint_mask_application_labor_rate_per_sqft", 0.25);
  const maskCuttingLaborRate = paintSettingNumber(settings, "paint_mask_cutting_labor_rate_per_sqft", 0.15);
  if (numColors > 1 && num(item.paint_mask_sqft) > 0) {
    baseHours += (num(item.paint_mask_sqft) * maskApplicationLaborRate * (numColors - 1) / laborRate)
      + (num(item.paint_mask_sqft) * maskCuttingLaborRate * (numColors - 1) / laborRate);
  }

  const qty = item.item_type === "lettering" ? 1 : Math.max(num(item.quantity, 1), 1);
  const discountedLaborHours = baseHours * laborTierMultiplier(settings, item.item_type, qty);
  const laborCost = discountedLaborHours * laborRate * qty;

  return {
    ...item,
    quantity: qty,
    supplies_cost: paintMaskCost * qty,
    paint_cost: liquidPaintAndSuppliesCost * qty,
    paint_gallons: paintGallons * qty,
    labor_hours: discountedLaborHours * qty,
    labor_cost: laborCost,
    paintable_sqft: paintableSqFt,
  };
}

export function calculatePaintingProject(project = {}, settings = {}) {
  const liquidRate = liquidPaintRatePerSqft(settings);
  const projectSuppliesRate = paintSettingNumber(
    project,
    "paint_supplies_per_sqft",
    paintSettingNumber(settings, "default_paint_supplies_per_sqft", 1.25)
  );
  const items = (project.items || []).map((item) => calculatePaintingItem(item, settings, liquidRate, projectSuppliesRate));

  const totalPaintMask = items.reduce((sum, item) => sum + num(item.supplies_cost), 0);
  let totalLiquidPaintAndSupplies = items.reduce((sum, item) => sum + num(item.paint_cost), 0);
  const totalItemLaborCost = items.reduce((sum, item) => sum + num(item.labor_cost), 0);
  let totalPaintGallons = items.reduce((sum, item) => sum + num(item.paint_gallons), 0);

  const globalFixedWasteGallons = paintSettingNumber(settings, "fixed_paint_waste_gallons", 0);
  totalPaintGallons += globalFixedWasteGallons;
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  totalLiquidPaintAndSupplies += globalFixedWasteGallons * liquidRate * coverage;

  const itemFixedWaste = items.reduce((sum, item) => sum + num(item.fixed_waste_gallons), 0);
  const numberOfMixes = Math.ceil(totalPaintGallons);
  const mixingHours = numberOfMixes * paintSettingNumber(settings, "paint_mixing_labor_hours", 0.25);
  const setupHours = paintSettingNumber(settings, "setup_time_labor_hours", 0.5);

  const uniqueColors = new Set();
  items.forEach((item) => (item.paint_colors || []).forEach((color) => {
    const normalized = String(color || "").trim().toLowerCase();
    if (normalized) uniqueColors.add(normalized);
  }));
  const uniqueColorCount = uniqueColors.size;
  const totalColorChangeHours = uniqueColorCount > 1
    ? (uniqueColorCount - 1) * paintSettingNumber(settings, "color_change_setup_hours", 0.25)
    : 0;
  const totalPaintGunCleaningHours = uniqueColorCount > 0
    ? uniqueColorCount * paintSettingNumber(settings, "paint_gun_cleaning_hours", 0.15)
    : 0;
  const laborRate = paintSettingNumber(settings, "default_labor_rate", 60, { positive: true });
  const fixedLaborCost = (mixingHours + setupHours + totalColorChangeHours + totalPaintGunCleaningHours) * laborRate;
  let totalLabor = totalItemLaborCost + fixedLaborCost;
  const totalLaborHours = items.reduce((sum, item) => sum + num(item.labor_hours), 0)
    + mixingHours + setupHours + totalColorChangeHours + totalPaintGunCleaningHours;

  const minLaborHours = paintSettingNumber(settings, "min_labor_hours", 0);
  const minPaintCost = paintSettingNumber(settings, "min_paint_cost", 0);
  if (totalLaborHours > 0 && totalLaborHours < minLaborHours) totalLabor = minLaborHours * laborRate;
  if (totalLiquidPaintAndSupplies > 0 && totalLiquidPaintAndSupplies < minPaintCost) totalLiquidPaintAndSupplies = minPaintCost;

  const totalCost = totalPaintMask + totalLiquidPaintAndSupplies + totalLabor;
  return {
    items,
    liquidPaintRate: liquidRate,
    totals: {
      total_paint_mask_cost: totalPaintMask,
      total_liquid_paint_and_supplies_cost: totalLiquidPaintAndSupplies,
      total_labor_cost: totalLabor,
      total_labor_hours: totalLaborHours,
      total_paint_gallons: totalPaintGallons,
      number_of_mixes: numberOfMixes,
      mixing_hours: mixingHours,
      setup_hours: setupHours,
      unique_color_count: uniqueColorCount,
      color_change_hours: totalColorChangeHours,
      gun_cleaning_hours: totalPaintGunCleaningHours,
      fixed_waste_gallons: globalFixedWasteGallons + itemFixedWaste,
      total_cost: totalCost,
    },
  };
}

// Painting pricing-availability layer.
//
// Wraps calculatePaintingProject with strict finite-number input validation so
// a missing, malformed, or unusable pricing input can no longer silently
// become $0, a hidden default, or a dropped item edge. Mirrors the landed
// Foundation/Vinyl hardening convention:
//   - strict parsers (paintStrictNumber / paintSettingNumber / paintThicknessNumber,
//     owned by paintCalc so the calculator and the scanner resolve identically)
//   - structured issue records { kind, index, itemIndex, field, code, message, hold }
//   - Painting has no catalog entities — the shared Settings rows are the
//     priced surface, so settings issues are kind "paint_catalog" and hold the
//     whole project calc; authored item/project-field issues hold the affected
//     item's derived numbers and every aggregate those numbers feed.
//   - explicit 0 stays valid where the calculator treats it as a real
//     free/zero amount (rates, multipliers, hours, floors, costs); 0 is
//     invalid where the math divides or needs a real magnitude (coverage, the
//     paint mix ratio, the waste multiplier, the labor rate divisor, the
//     letter perimeter factor).
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as PaintingEstimator has always passed them.
//
// Valid inputs take the exact same code path as before: the calc object the
// page receives for a clean project is bit-identical to today's result (plus
// __held / pricingUnavailable / issues metadata flags).

import {
  calculatePaintingProject,
  paintSettingNumber,
  paintSettingRecorded,
  paintStrictNumber,
  paintThicknessNumber,
} from "./paintCalc";

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- settings scan ----------
// Every Settings row the calculator prices from. [key, human, positive]
// positive: true  → recorded value must be > 0
// positive: false → recorded value must be finite and >= 0
const PRICED_SETTINGS = [
  ["default_labor_rate", "default labor rate ($/hr)", true],
  ["min_labor_hours", "minimum labor hours floor", false],
  ["min_paint_cost", "minimum paint cost floor", false],
  ["default_paint_supplies_per_sqft", "default paint supplies per sq ft", false],
  ["paint_cost_per_unit", "paint cost per unit", false],
  ["hardener_cost_per_unit", "hardener cost per unit", false],
  ["reducer_cost_per_unit", "reducer cost per unit", false],
  ["paint_mix_ratio", "paint mix ratio", true],
  ["hardener_mix_ratio", "hardener mix ratio", false],
  ["reducer_mix_ratio", "reducer mix ratio", false],
  ["mixed_paint_coverage_sqft_per_gallon", "mixed paint coverage (sq ft/gallon)", true],
  ["paint_waste_multiplier", "paint waste multiplier", true],
  ["fixed_paint_waste_gallons", "fixed paint waste (gallons)", false],
  ["paint_mask_rate_per_sqft", "paint mask material rate per sq ft", false],
  ["paint_mask_machine_cutting_rate_per_sqft", "paint mask machine cutting rate per sq ft", false],
  ["paint_mask_application_labor_rate_per_sqft", "paint mask application labor rate per sq ft", false],
  ["paint_mask_cutting_labor_rate_per_sqft", "paint mask cutting labor rate per sq ft", false],
  ["base_labor_hours_per_sqft", "base labor hours per sq ft", false],
  ["setup_time_labor_hours", "setup time (hours)", false],
  ["paint_mixing_labor_hours", "paint mixing labor hours per mix", false],
  ["color_change_setup_hours", "color change setup hours", false],
  ["paint_gun_cleaning_hours", "paint gun cleaning hours", false],
  ["one_side_paint_multiplier", "one-side paint multiplier", false],
  ["both_sides_paint_multiplier", "both-sides paint multiplier", false],
  ["additional_color_multiplier", "additional color multiplier", false],
  ["simple_complexity_multiplier", "simple complexity multiplier", false],
  ["moderate_complexity_multiplier", "moderate complexity multiplier", false],
  ["complex_complexity_multiplier", "complex complexity multiplier", false],
  ["letter_perimeter_factor", "letter perimeter factor", true],
];

const PAINT_UNITS = ["oz", "pint", "quart", "liter", "gallon"];
const TIER_SETTINGS = [
  ["panel_labor_tiers", "panel labor tiers"],
  ["complex_shapes_labor_tiers", "complex shape labor tiers"],
  ["lettering_labor_tiers", "lettering labor tiers"],
];

// Settings rows the calc prices from. Only recorded values can be broken —
// an absent row falls back to the documented module default by design, so it
// is never an issue. Every settings issue holds the whole project calc.
export function paintSettingIssues(settings = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint_catalog", { field, code, message, hold: "project" }));

  for (const [key, human, positive] of PRICED_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const n = paintStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, "paint_setting_unavailable",
        `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in Painting Settings — the stored value cannot price this estimate`);
    }
  }

  // Liquid unit selectors — a recorded-but-unsupported unit resolves 0 in
  // costPerGallon (silently free); a missing unit next to a priced component
  // does the same.
  for (const [costKey, unitKey, human] of [
    ["paint_cost_per_unit", "paint_unit", "paint"],
    ["hardener_cost_per_unit", "hardener_unit", "hardener"],
    ["reducer_cost_per_unit", "reducer_unit", "reducer"],
  ]) {
    const unitRecorded = paintSettingRecorded(settings, unitKey);
    const unitValid = PAINT_UNITS.includes(settings?.[unitKey]);
    if (unitRecorded && !unitValid) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: select a supported ${human} unit (oz / pint / quart / liter / gallon) in Painting Settings`);
    } else if (!unitValid && (paintStrictNumber(settings?.[costKey]) ?? 0) > 0) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: set a ${human} unit — a recorded ${costKey} prices as $0 without one`);
    }
  }

  // Labor tier tables are JSON arrays of {min_quantity, max_quantity,
  // labor_multiplier}. Malformed JSON silently disables the whole table;
  // malformed row fields silently dead-window the tier or reprice it.
  for (const [key, human] of TIER_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const raw = settings[key];
    let tiers = raw;
    if (!Array.isArray(tiers)) {
      try {
        const parsed = JSON.parse(raw || "[]");
        tiers = Array.isArray(parsed) ? parsed : null;
      } catch {
        tiers = null;
      }
    }
    if (tiers === null) {
      add(key, "paint_labor_tiers_unavailable",
        `Setting ${key}: the ${human} table is not a valid JSON array — repair it in Painting Settings or quantity discounts price as 1x`);
      continue;
    }
    tiers.forEach((row, rowIdx) => {
      const where = `Setting ${key} row ${rowIdx + 1}`;
      for (const [field, human2] of [["min_quantity", "minimum quantity"], ["max_quantity", "maximum quantity"]]) {
        if (row?.[field] !== undefined && row?.[field] !== null
          && (paintStrictNumber(row[field]) === null || paintStrictNumber(row[field]) < 0)) {
          add(key, "paint_labor_tier_row_unavailable",
            `${where}: record a finite, nonnegative ${human2} — the stored value dead-windows this tier`);
        }
      }
      if (row?.labor_multiplier !== undefined && row?.labor_multiplier !== null
        && (paintStrictNumber(row.labor_multiplier) === null || paintStrictNumber(row.labor_multiplier) < 0)) {
        add(key, "paint_labor_tier_row_unavailable",
          `${where}: record a finite, nonnegative labor multiplier — the stored value cannot price this tier`);
      }
    });
  }

  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each paint item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
const LETTER_SIZES = ["extra_small", "small", "normal", "medium", "large", "extra_large"];
const PRESENT = (v) => v !== undefined && v !== null;
// For this module a cleared stored value is malformed input, not an absent
// one: paintCalc's num("") launders to 0 / a clamp to 1 silently.
const nonnegField = (v) => paintStrictNumber(v) !== null && paintStrictNumber(v) >= 0;

export function paintItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("paint", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — every geometry branch keys on it; anything else prices a
  // silent $0 item.
  if (PRESENT(rawItem?.item_type) && !["panel", "lettering", "complex_shapes"].includes(rawItem.item_type)) {
    add("item_type", "paint_item_type_unavailable",
      "select Panel, Lettering, or Complex Shape — the stored type prices as $0 silently");
  }
  const effectiveType = rawItem?.item_type || "panel";

  // thickness — the strict imperial parse: malformed text used to vanish into
  // 0 (edge area silently dropped; "-1" even laundered to +1). Panel math has
  // an explicit edge-less branch so a real 0 is tolerated there; lettering
  // and complex shapes price nothing at all without a positive thickness.
  if (rawItem?.thickness !== undefined) {
    const t = paintThicknessNumber(rawItem.thickness);
    if (t === null || t < 0) {
      add("thickness", "paint_thickness_unavailable",
        "record a usable thickness (inches, e.g. 1/2 or 1-1/4) — the stored value silently drops edge pricing");
    } else if (t === 0 && effectiveType !== "panel") {
      add("thickness", "paint_thickness_unavailable",
        "record a positive thickness — lettering and complex shapes price nothing at 0\"");
    }
  }

  // length / width — every branch gates > 0; blank, zero, negative or
  // malformed dimensions silently collapse the item's paint and labor.
  for (const field of ["length", "width"]) {
    const n = paintStrictNumber(rawItem?.[field]);
    if (n === null || n <= 0) {
      add(field, "paint_dimension_unavailable",
        `record a positive, finite ${field === "length" ? (effectiveType === "lettering" ? "letter count" : "length") : (effectiveType === "lettering" ? "letter height" : "width")} (inches) — a blank or zero dimension prices the item as $0 silently`);
    }
  }

  // quantity — lettering forces 1 by design; other types clamp <1 to 1 in the
  // math, so a recorded 0/blank/malformed value silently repriced as one.
  if (effectiveType !== "lettering" && PRESENT(rawItem?.quantity)) {
    const q = paintStrictNumber(rawItem.quantity);
    if (q === null || q < 1) {
      add("quantity", "paint_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value prices as 1 silently");
    }
  }

  // paint_sides — the stored value chooses the multiplier branch; "none" is a
  // tolerated legacy alias for one_side.
  if (PRESENT(rawItem?.paint_sides) && rawItem.paint_sides !== ""
    && !["one_side", "both_sides", "none"].includes(rawItem.paint_sides)) {
    add("paint_sides", "paint_sides_unavailable",
      "choose One side or Both sides — the stored value silently prices as one side");
  }

  // edge complexity — complex-shape edge multiplier; negative values priced
  // negative edge area, malformed text repriced as 1x, blank as 0 edges.
  if (effectiveType === "complex_shapes" && PRESENT(rawItem?.edge_complexity_multiplier)
    && !nonnegField(rawItem.edge_complexity_multiplier)) {
    add("edge_complexity_multiplier", "paint_edge_complexity_unavailable",
      "record a finite, nonnegative edge complexity multiplier — the stored value cannot price edges");
  }

  // paint mask sq ft — consumed when more than one color is selected; blank
  // or malformed text silently priced as no mask.
  if (PRESENT(rawItem?.paint_mask_sqft) && !nonnegField(rawItem.paint_mask_sqft)) {
    add("paint_mask_sqft", "paint_mask_sqft_unavailable",
      "record a finite, nonnegative paint mask area (sq ft) — the stored value drops mask pricing");
  }

  // fixed waste gallons / base supplies — recorded junk silently became 0.
  for (const [field, human] of [["fixed_waste_gallons", "fixed waste (gallons)"], ["base_supplies_cost", "base supplies cost ($)"]]) {
    if (PRESENT(rawItem?.[field]) && !nonnegField(rawItem[field])) {
      add(field, field === "fixed_waste_gallons" ? "paint_fixed_waste_unavailable" : "paint_base_supplies_unavailable",
        `record a finite, nonnegative ${human} — the stored value silently became $0`);
    }
  }

  // letter_size — drives the complexity class for lettering only.
  if (effectiveType === "lettering" && PRESENT(rawItem?.letter_size) && rawItem.letter_size !== ""
    && !LETTER_SIZES.includes(rawItem.letter_size)) {
    add("letter_size", "paint_letter_size_unavailable",
      "the stored letter size is unsupported — it silently prices as moderate complexity");
  }

  // paint_colors — the math reads the array length verbatim (ported); a
  // non-array value normalized to [] silently bills no paint.
  if (PRESENT(rawItem?.paint_colors) && !Array.isArray(rawItem.paint_colors)) {
    add("paint_colors", "paint_colors_unavailable",
      "the stored color list is malformed — it silently bills $0 paint; re-add the colors");
  }

  return issues;
}

// ---------- project-level scan ----------
export function paintProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint", { field, code, message, hold: "project" }));

  // items must be an array — the calc maps it verbatim.
  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "paint_items_unavailable",
      "the stored paint items are malformed — the project cannot be repriced");
  }

  // paint_supplies_per_sqft — blank/null laundered to $0 under num(); a
  // malformed string silently became the settings default. Explicit 0 stays a
  // legitimate free supplies rate.
  if (project?.paint_supplies_per_sqft !== undefined
    && (paintStrictNumber(project.paint_supplies_per_sqft) === null
      || paintStrictNumber(project.paint_supplies_per_sqft) < 0)) {
    add("paint_supplies_per_sqft", "paint_supplies_rate_unavailable",
      "record a finite, nonnegative supplies rate per sq ft — a blank or malformed value silently repriced supplies");
  }

  return issues;
}

// ---------- calc wrapper ----------
// Returns { calc, issues, held }. The calc keeps the real result shape; when
// held, every derived number a flagged input could have tainted is null —
// saved acknowledged totals on the record are the display fallback, never an
// invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["supplies_cost", "paint_cost", "paint_gallons", "labor_hours", "labor_cost", "paintable_sqft"];

export function calcPaintingProject(project = {}, settings = {}) {
  const issues = [
    ...paintSettingIssues(settings),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => paintItemIssues(item, index))),
    ...paintProjectInputIssues(project),
  ];

  // A non-array items value is itself a project-level hold; hand the calc an
  // empty list so it still returns a real result shape (the input object is
  // never mutated — totals are nulled below regardless).
  const calcable = Array.isArray(project?.items) ? project : { ...project, items: [] };
  const calc = calculatePaintingProject(calcable, settings);
  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held };
  }

  const out = { ...calc, totals: { ...calc.totals } };
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  // Held items keep their raw row but lose every derived number — the totals
  // sum those numbers so every aggregate is untrustworthy too.
  out.items = calc.items.map((item, index) => {
    if (!hasProjectHold && !itemHolds.has(index)) return item;
    const heldItem = { ...item };
    for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
    return heldItem;
  });
  for (const field of Object.keys(out.totals)) out.totals[field] = null;
  if (hasProjectHold) out.liquidPaintRate = null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held };
}

// ---------- UI helpers ----------
// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasPaintCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields: "" stays "" so the input
// does not fight the user mid-typing; parseable text becomes a number;
// anything else stays raw so validation can flag it instead of laundering it
// into 0 (paintCalc's num("") silently read as 0 before).
export const paintDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

// Painting sell-price engine wire (F-23g) — module-side glue.
//
// The shared wire (base44/shared/paintPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "painting" — when no paint line carries pricing-engine config
// the resolution is a passthrough and the module sell price is returned
// verbatim (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolvePaintSellPricing,
  paintConfigScan,
  paintPricingContextOf,
} from "../../../../base44/shared/paintPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying paint lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       paint Project-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (total_paint_mask_cost
 *                                    + total_liquid_paint_and_supplies_cost
 *                                    + total_labor_cost)
 * @param {number} [opts.internalCost] module internal cost (same sum)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolvePaintSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = paintPricingContextOf(record, caller);
    return resolvePaintSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a paint source record.
 * Returns null when no paint line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a..F-23f channel/vinyl/brick/cnc/laser/metal
 * wires).
 */
export function paintEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a paint source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function paintEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any paint line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function paintHasEnginePricing(record) {
  try {
    return paintConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

import { useEffect, useRef, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Cpu, Loader2 } from "lucide-react";
import ReactMarkdown from "react-markdown";
import {
  prepareFoundationAiReview,
  foundationAiReviewPatch,
  FOUNDATION_AI_REVIEW_POLICY,
} from "./foundationAiReview";

export default function AiEngineeringAssistant({ project, onResult }) {
  const [running, setRunning] = useState(false);
  const [error, setError] = useState("");
  const mountedRef = useRef(true);
  const busyRef = useRef(false);
  const tokenRef = useRef(0);
  const latestRef = useRef({ key: null, onResult });
  let inputError = "";
  let prepared = null;
  try {
    prepared = prepareFoundationAiReview(project);
  } catch (e) {
    inputError = e?.message || "The foundation inputs cannot be reviewed.";
  }
  latestRef.current = { key: prepared?.key ?? null, onResult };

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      tokenRef.current += 1;
      busyRef.current = false;
    };
  }, []);

  const run = async () => {
    if (busyRef.current || !prepared || typeof latestRef.current.onResult !== "function") return;
    busyRef.current = true;
    const token = ++tokenRef.current;
    const capturedKey = prepared.key;
    const request = prepared.request;
    setRunning(true);
    setError("");
    try {
      const res = await base44.integrations.Core.InvokeLLM(request);
      if (!mountedRef.current || token !== tokenRef.current) return;
      if (latestRef.current.key !== capturedKey) {
        setError("The design changed while this review was running. Run a fresh review.");
        return;
      }
      const patch = foundationAiReviewPatch(res, { sourceKey: capturedKey, generatedAt: new Date().toISOString() });
      const accepted = latestRef.current.onResult(patch);
      if (accepted === false) setError("The review could not be attached. No review changes were applied.");
    } catch (e) {
      if (!mountedRef.current || token !== tokenRef.current) return;
      setError(e.message || "The preliminary review could not run.");
    } finally {
      if (mountedRef.current && token === tokenRef.current) {
        busyRef.current = false;
        setRunning(false);
      }
    }
  };

  const recommendation = typeof project?.ai_engineering_recommendation === "string" ? project.ai_engineering_recommendation : "";
  const meta = project?.ai_engineering_data;
  const samePolicy = meta?.policy_version === FOUNDATION_AI_REVIEW_POLICY && typeof meta?.source_key === "string" && !!meta.source_key;
  const stale = samePolicy && (!prepared || meta.source_key !== prepared.key);
  const label = stale
    ? "Design changed since this note. Run a fresh review."
    : samePolicy && meta?.source_key
      ? "Preliminary review"
      : "Historical / unverified AI note";

  return (
    <div className="bg-violet-50 border border-violet-200 rounded-sm p-3 mb-3">
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div className="flex items-start gap-2 min-w-0">
          <Cpu className="w-4 h-4 text-violet-600 mt-0.5" aria-hidden="true" />
          <div className="min-w-0">
            <h3 className="text-[13px] font-bold text-violet-900">AI Preliminary Review</h3>
            <p className="text-[11px] text-violet-700">
              Identify missing inputs and questions for qualified engineering review; not structural calculations or approval.
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={run}
          disabled={running || !prepared || typeof onResult !== "function"}
          className="h-[30px] px-3 flex items-center gap-1.5 rounded-sm bg-violet-600 text-white text-[12px] font-semibold hover:bg-violet-700 disabled:opacity-60 flex-shrink-0"
        >
          {running ? <Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> : <Cpu className="w-3.5 h-3.5" aria-hidden="true" />}
          {running ? "Reviewing…" : "Review Foundation Inputs"}
        </button>
      </div>

      {(inputError || error) && <div role="alert" className="mt-2 text-[11px] text-red-600">{inputError || error}</div>}

      {recommendation && (
        <div className="mt-3 bg-white border border-violet-200 rounded-sm p-3 text-[12px] text-gray-700 prose prose-sm max-w-none">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-violet-500 mb-1">{label}</p>
          <ReactMarkdown>{recommendation}</ReactMarkdown>
        </div>
      )}
    </div>
  );
}

import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";

const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
const cy = (v) => (Number.isFinite(v) ? `${v.toFixed(2)} CY` : "Not saved");

export default function ConcreteDeliveryPanel({ project, delivery, onChange }) {
  const admixtures = project.project_concrete_admixtures || [];
  const unavailable = delivery?.pricingUnavailable === true;
  const mixes = delivery?.availableMixes || [];
  const admix = delivery?.availableAdmixes || [];
  const savedMixId = project.project_concrete_type;
  const mixMissing = savedMixId && !mixes.some((m) => m.id === savedMixId);
  const trucks = delivery?.trucksList || [];

  const toggleAdmix = (id) =>
    onChange({
      project_concrete_admixtures: admixtures.includes(id)
        ? admixtures.filter((a) => a !== id)
        : [...admixtures, id],
    });

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      {unavailable && (
        <p className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">
          Saved amounts (not current pricing)
        </p>
      )}
      <div className="flex items-center justify-between mb-3">
        <h3 className="font-semibold text-gray-900 text-sm">Ready-Mix Concrete Order</h3>
        <div className="text-right">
          <div className="font-bold text-gray-900">{amt(delivery?.concreteTotal)}</div>
          <div className="text-[11px] text-gray-400">
            {cy(delivery?.roundedYards)} · {amt(delivery?.ratePerYard)}/CY
          </div>
        </div>
      </div>

      <label className="text-xs text-gray-500 block">
        Mix strength
        <select
          value={savedMixId || "4000_ae"}
          disabled={unavailable}
          onChange={(e) => onChange({ project_concrete_type: e.target.value })}
          className="flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm shadow-sm disabled:opacity-60"
        >
          {mixMissing && <option value={savedMixId} disabled>Catalog mix unavailable ({savedMixId})</option>}
          {mixes.map((m) => (
            <option key={m.id} value={m.id}>
              {m.name} — {hasFoundationCostSnapshot(m.price) ? `${money(m.price)}/CY` : "price unavailable"}
            </option>
          ))}
        </select>
      </label>
      {!mixMissing && (
        <p className="text-[11px] text-gray-400 mt-1">
          {mixes.find((m) => m.id === (savedMixId || "4000_ae"))?.desc}
        </p>
      )}

      <div className="mt-3 pt-3 border-t border-gray-100">
        <div className="text-xs font-medium text-gray-700 mb-2">Admixtures</div>
        <div className="space-y-2">
          {admixtures
            .filter((id) => !admix.some((a) => a.id === id))
            .map((id) => (
              <div key={id} className="text-xs text-amber-700">Catalog admixture unavailable ({id})</div>
            ))}
          {admix.map((a) => (
            <label key={a.id} className={`flex gap-2 items-start text-xs ${unavailable ? "text-gray-400" : "text-gray-600"}`}>
              <input
                type="checkbox"
                className="mt-0.5"
                disabled={unavailable}
                checked={admixtures.includes(a.id)}
                onChange={() => toggleAdmix(a.id)}
              />
              <span>
                <span className="font-medium text-gray-800">{a.name}</span> — {hasFoundationCostSnapshot(a.price) ? `${money(a.price)}/CY` : "price unavailable"}
                <span className="block text-[11px] text-gray-400">{a.desc}</span>
              </span>
            </label>
          ))}
        </div>
      </div>

      {trucks.length > 0 && (
        <div className="mt-3 pt-3 border-t border-gray-100 space-y-1">
          {trucks.map((t, i) => (
            <div key={i} className="flex justify-between text-xs text-gray-600">
              <span>
                Truck {i + 1} — {cy(t.roundedYards)}
                {Number.isFinite(t.smallOrderFee) && t.smallOrderFee > 0 && ` (small load ${money(t.smallOrderFee)})`}
                {Number.isFinite(t.fuelFee) && t.fuelFee > 0 && ` + fuel ${money(t.fuelFee)}`}
              </span>
              <span className="font-medium text-gray-800">{amt(t.cost)}</span>
            </div>
          ))}
          {(delivery?.additionalStopsCost ?? 0) > 0 && (
            <div className="flex justify-between text-xs text-gray-600">
              <span>Additional sign locations / stops</span>
              <span className="font-medium text-gray-800">{amt(delivery.additionalStopsCost)}</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { Maximize2, RotateCcw, Eye, EyeOff, Box } from "lucide-react";

const IN = 1 / 12; // inches -> feet units

function buildScene(scene, project, solid, showGround) {
  const group = new THREE.Group();

  const concreteMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x9ca3af, roughness: 0.9 })
    : new THREE.MeshBasicMaterial({ color: 0x374151, wireframe: true });
  const poleMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x4b5563, metalness: 0.4, roughness: 0.5 })
    : new THREE.MeshBasicMaterial({ color: 0x1f2937, wireframe: true });

  let cursorX = 0;
  const items = project.items || [];
  items.forEach((item) => {
    const qty = Math.max(1, Number(item.quantity) || 1);
    const depth = (Number(item.depth_inches) || 0) * IN;
    for (let i = 0; i < qty; i++) {
      let mesh;
      let footprint;
      if (item.foundation_type === "pillar") {
        const r = ((Number(item.diameter) || 0) / 2) * IN;
        footprint = r * 2;
        mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, depth, 24), concreteMat);
      } else {
        const l = (Number(item.length_inches) || 0) * IN;
        const w = (Number(item.width_inches) || 0) * IN;
        footprint = Math.max(l, w);
        mesh = new THREE.Mesh(new THREE.BoxGeometry(l, depth, w), concreteMat);
      }
      const offset = (Number(item.grade_offset_inches) || 0) * IN;
      mesh.position.set(cursorX + footprint / 2, -depth / 2 + offset, 0);
      mesh.rotation.y = ((Number(item.rotation_degrees) || 0) * Math.PI) / 180;
      group.add(mesh);

      if (item.selected_pole_id || item.pole_total_height_inches) {
        const h = (Number(item.pole_total_height_inches) || 96) * IN;
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, h, 16), poleMat);
        pole.position.set(mesh.position.x, offset + h / 2, 0);
        group.add(pole);
      }

      cursorX += footprint + 2;
    }
  });

  (project.poles || []).forEach((p) => {
    const h = (Number(p.height_inches) || 96) * IN;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, h, 16), poleMat);
    pole.position.set(
      (Number(p.x_inches) || 0) * IN,
      (Number(p.y_offset_inches) || 0) * IN + h / 2,
      (Number(p.z_inches) || 0) * IN
    );
    group.add(pole);
  });

  if (showGround) {
    const grid = new THREE.GridHelper(60, 60, 0xd1d5db, 0xe5e7eb);
    grid.position.y = 0.01;
    group.add(grid);
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshStandardMaterial({ color: 0xf3f4f6, roughness: 1 })
    );
    ground.rotation.x = -Math.PI / 2;
    group.add(ground);
  }

  // center the model horizontally
  const box = new THREE.Box3().setFromObject(group);
  const center = box.getCenter(new THREE.Vector3());
  group.position.x -= center.x;
  group.position.z -= center.z;

  scene.add(group);
  return group;
}

export default function Foundation3DPreview({ project }) {
  const mountRef = useRef(null);
  const stateRef = useRef({});
  const [solid, setSolid] = useState(true);
  const [showGround, setShowGround] = useState(true);
  const [visible, setVisible] = useState(true);
  const [zoom, setZoom] = useState(100);

  useEffect(() => {
    if (!visible || !mountRef.current) return;
    const mount = mountRef.current;
    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf9fafb);
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setSize(width, height);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xffffff, 0x9ca3af, 1.1));
    const dir = new THREE.DirectionalLight(0xffffff, 0.7);
    dir.position.set(20, 30, 20);
    scene.add(dir);

    const st = stateRef.current;
    st.theta = st.theta ?? Math.PI / 4;
    st.phi = st.phi ?? Math.PI / 3.2;
    st.radius = st.radius ?? 30;
    st.target = st.target || new THREE.Vector3(0, 0, 0);

    const applyCamera = () => {
      const r = st.radius;
      camera.position.set(
        st.target.x + r * Math.sin(st.phi) * Math.cos(st.theta),
        st.target.y + r * Math.cos(st.phi),
        st.target.z + r * Math.sin(st.phi) * Math.sin(st.theta)
      );
      camera.lookAt(st.target);
    };

    buildScene(scene, project, solid, showGround);
    applyCamera();

    let frame;
    const render = () => {
      renderer.render(scene, camera);
      frame = requestAnimationFrame(render);
    };
    render();

    // --- controls ---
    let dragging = null;
    let last = { x: 0, y: 0 };
    const onDown = (e) => {
      dragging = e.button === 2 ? "pan" : "orbit";
      last = { x: e.clientX, y: e.clientY };
      e.preventDefault();
    };
    const onMove = (e) => {
      if (!dragging) return;
      const dx = e.clientX - last.x;
      const dy = e.clientY - last.y;
      last = { x: e.clientX, y: e.clientY };
      if (dragging === "orbit") {
        st.theta += dx * 0.008;
        st.phi = Math.min(Math.PI / 2.02, Math.max(0.15, st.phi - dy * 0.006));
      } else {
        const panScale = st.radius * 0.0015;
        st.target.x -= dx * panScale * Math.cos(st.theta + Math.PI / 2);
        st.target.z -= dx * panScale * Math.sin(st.theta + Math.PI / 2);
        st.target.y += dy * panScale;
      }
      applyCamera();
    };
    const onUp = () => (dragging = null);
    const onWheel = (e) => {
      e.preventDefault();
      st.radius = Math.min(200, Math.max(3, st.radius * (1 + e.deltaY * 0.001)));
      setZoom(Math.round((30 / st.radius) * 100));
      applyCamera();
    };
    const onContext = (e) => e.preventDefault();

    const el = renderer.domElement;
    el.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("contextmenu", onContext);

    const onResize = () => {
      const w = mount.clientWidth;
      const h = mount.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    stateRef.current.setView = (view) => {
      if (view === "front") { st.theta = -Math.PI / 2; st.phi = Math.PI / 2.05; }
      if (view === "side") { st.theta = 0; st.phi = Math.PI / 2.05; }
      if (view === "top") { st.theta = -Math.PI / 2; st.phi = 0.16; }
      if (view === "reset") {
        st.theta = Math.PI / 4;
        st.phi = Math.PI / 3.2;
        st.radius = 30;
        st.target.set(0, 0, 0);
        setZoom(100);
      }
      applyCamera();
    };

    return () => {
      cancelAnimationFrame(frame);
      el.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      el.removeEventListener("wheel", onWheel);
      el.removeEventListener("contextmenu", onContext);
      window.removeEventListener("resize", onResize);
      renderer.dispose();
      if (el.parentNode === mount) mount.removeChild(el);
    };
  }, [project, solid, showGround, visible]);

  const setView = (v) => stateRef.current.setView?.(v);

  const ToolBtn = ({ children, onClick, active }) => (
    <button
      type="button"
      onClick={onClick}
      className={`h-[24px] px-2 rounded-sm border text-[11px] font-medium flex items-center gap-1 ${
        active ? "bg-blue-600 border-blue-600 text-white" : "bg-white border-gray-300 text-gray-700"
      }`}
    >
      {children}
    </button>
  );

  return (
    <div className="bg-white border border-gray-200 rounded-sm p-2">
      <div className="flex items-center justify-between mb-2">
        <div>
          <span className="text-[12px] font-bold text-gray-800">3D Preview</span>
          <span className="text-[11px] text-gray-400 ml-2">Updates live as you edit</span>
        </div>
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          className="text-[11px] font-medium text-gray-600 hover:text-red-600 flex items-center gap-1"
        >
          {visible ? <EyeOff className="w-3.5 h-3.5" aria-hidden="true" /> : <Eye className="w-3.5 h-3.5" aria-hidden="true" />}
          {visible ? "Hide 3D View" : "Show 3D View"}
        </button>
      </div>

      {visible && (
        <>
          <div className="flex items-center gap-1 flex-wrap mb-2">
            <ToolBtn onClick={() => setView("front")}>Front</ToolBtn>
            <ToolBtn onClick={() => setView("side")}>Side</ToolBtn>
            <ToolBtn onClick={() => setView("top")}>Top</ToolBtn>
            <ToolBtn onClick={() => setView("reset")}>
              <RotateCcw className="w-3 h-3" aria-hidden="true" /> Reset
            </ToolBtn>
            <span className="text-[11px] text-gray-500 px-1">{zoom}%</span>
            <ToolBtn onClick={() => setShowGround((v) => !v)} active={!showGround}>
              {showGround ? "Hide Ground" : "Show Ground"}
            </ToolBtn>
            <ToolBtn onClick={() => setSolid((v) => !v)} active={solid}>
              <Box className="w-3 h-3" aria-hidden="true" /> {solid ? "Solid Mode" : "Wireframe"}
            </ToolBtn>
            <ToolBtn onClick={() => mountRef.current?.requestFullscreen?.()}>
              <Maximize2 className="w-3 h-3" aria-hidden="true" /> Full Screen
            </ToolBtn>
          </div>

          <div ref={mountRef} className="w-full h-[420px] rounded-sm overflow-hidden bg-gray-50" />

          <div className="flex items-center justify-between text-[10px] text-gray-500 mt-1 px-1">
            <span>Left Click + Drag: Orbit/Rotate</span>
            <span>Right Click + Drag: Pan/Move</span>
            <span>Scroll Wheel: Zoom in/out</span>
          </div>
        </>
      )}
    </div>
  );
}

import { useMemo } from "react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallBomRows } from "./wallCalculator";

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const qty = (n, unit) => `${num(n).toLocaleString(undefined, { maximumFractionDigits: 2 })} ${unit}`;
const EMPTY_ITEMS = [];
const EMPTY_POLES = [];
const EMPTY_WALLS = [];
const EMPTY_TOTALS = {};
const EMPTY_INVENTORY = [];

export default function FoundationBOM({
  items = EMPTY_ITEMS,
  poles = EMPTY_POLES,
  walls = EMPTY_WALLS,
  delivery,
  totals = EMPTY_TOTALS,
  inventory = EMPTY_INVENTORY,
  itemPricing = EMPTY_ITEMS,
  polePricing = EMPTY_ITEMS,
  wallPricing = EMPTY_ITEMS,
  pricingUnavailable = false,
}) {
  const rows = useMemo(() => {
    const out = [];
    // rawQty is the real numeric quantity; displayQty is the formatted label.
    // A row with a positive quantity OR a known cost stays listed (free rows
    // included) — the formatted string is never parsed for the drop test.
    const add = (material, displayQty, cost, rawQty = num(displayQty)) => {
      if (num(rawQty) <= 0 && !hasFoundationCostSnapshot(cost)) return;
      out.push({ material, quantity: displayQty, cost });
    };
    const nameOf = (id) => inventory.find((i) => i.id === id)?.material_name || "Material";
    const resolved = items.filter((_, i) => itemPricing[i]?.available !== false);
    const blocked = items.filter((_, i) => itemPricing[i]?.available === false);

    if (delivery?.pricingUnavailable) {
      out.push({
        material: "Concrete delivery/order (saved)",
        quantity: Number.isFinite(delivery.roundedYards) ? qty(delivery.roundedYards, "CY") : "Not saved",
        cost: hasFoundationCostSnapshot(delivery.concreteTotal) ? delivery.concreteTotal : "Not saved",
        saved: true,
      });
    } else if (num(delivery?.roundedYards) > 0) {
      add("Ready-mix concrete (delivered)", qty(delivery.roundedYards, "CY"), delivery.concreteTotal, delivery.roundedYards);
    }
    const bags = resolved.reduce((s, i) => s + num(i.concrete_bags), 0);
    const baggedCost = resolved.reduce((s, i) => s + num(i.concrete_cost), 0);
    if (bags > 0 || baggedCost > 0) add("Bagged concrete", qty(bags, "bags"), baggedCost, bags);

    const rebarFt = resolved.reduce((s, i) => s + num(i.rebar_feet), 0);
    const rebarLbs = resolved.reduce((s, i) => s + num(i.rebar_weight_lbs), 0);
    const rebarCost = resolved.reduce((s, i) => s + num(i.rebar_cost), 0);
    if (rebarFt > 0) {
      add(`Rebar (${qty(rebarLbs, "lbs")})`, qty(rebarFt, "LF"), rebarCost, rebarFt);
    }

    const formingQty = resolved.reduce((s, i) => s + num(i.forming_qty), 0);
    const formingCost = resolved.reduce((s, i) => s + num(i.forming_cost), 0);
    if (formingQty > 0) add("Forming material", qty(formingQty, "units"), formingCost, formingQty);

    blocked.forEach((i) => {
      const label = `Foundation ${i.component_id ?? "?"} (saved)`;
      {
        out.push({
          material: `${label} — concrete`,
          quantity: Number.isFinite(i.concrete_bags) ? qty(i.concrete_bags, "bags") : "Not saved",
          cost: hasFoundationCostSnapshot(i.concrete_cost) ? i.concrete_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_rebar) {
        out.push({
          material: `${label} — rebar`,
          quantity: Number.isFinite(i.rebar_feet) ? qty(i.rebar_feet, "LF") : "Not saved",
          cost: hasFoundationCostSnapshot(i.rebar_cost) ? i.rebar_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_forming) {
        out.push({
          material: `${label} — forming`,
          quantity: Number.isFinite(i.forming_qty) ? qty(i.forming_qty, "units") : "Not saved",
          cost: hasFoundationCostSnapshot(i.forming_cost) ? i.forming_cost : "Not saved",
          saved: true,
        });
      }
    });

    const poleGroups = {};
    poles.forEach((p, index) => {
      // Held poles list their acknowledged amounts separately, never dropped.
      if (polePricing[index]?.available === false) return;
      if (!p.pole_id) return;
      poleGroups[p.pole_id] = poleGroups[p.pole_id] || { ft: 0, cost: 0 };
      poleGroups[p.pole_id].ft += (num(p.height_inches) + num(p.y_offset_inches)) / 12;
      poleGroups[p.pole_id].cost += num(p.pole_cost);
    });
    Object.entries(poleGroups).forEach(([id, g]) => add(nameOf(id), qty(g.ft, "LF"), g.cost, g.ft));

    const polePainting = poles.reduce((s, p, index) =>
      polePricing[index]?.available === false ? s : s + num(p.pole_painting_cost), 0);
    if (polePainting > 0) {
      add("Pole painting", "—", polePainting);
    }

    const savedPoleFt = (p) => {
      const h = Number(p.height_inches), d = Number(p.y_offset_inches);
      return Number.isFinite(h) && h > 0 && Number.isFinite(d) && d >= 0 ? (h + d) / 12 : null;
    };
    poles.forEach((p, index) => {
      if (polePricing[index]?.available !== false) return;
      const label = `Pole ${index + 1} (saved)`;
      const ft = savedPoleFt(p);
      out.push({
        material: `${label} — pole`,
        quantity: Number.isFinite(ft) ? qty(ft, "LF") : "Not saved",
        cost: hasFoundationCostSnapshot(p.pole_cost) ? p.pole_cost : "Not saved",
        saved: true,
      });
      if (p.include_pole_painting || hasFoundationCostSnapshot(p.pole_painting_cost)) {
        out.push({
          material: `${label} — painting`,
          quantity: "—",
          cost: hasFoundationCostSnapshot(p.pole_painting_cost) ? p.pole_painting_cost : "Not saved",
          saved: true,
        });
      }
    });

    out.push(...foundationWallBomRows(walls, inventory, wallPricing));

    (totals.wall_caps_by_material || []).forEach((g) => add(g.name || "Wall cap", qty(g.qty, "pcs"), g.cost, g.qty));

    return out;
  }, [items, poles, walls, delivery, totals, inventory, itemPricing, polePricing, wallPricing]);

  const materialTotal = rows.every(r => hasFoundationCostSnapshot(r.cost)) ? rows.reduce((sum, row) => sum + row.cost, 0) : null;

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      <h3 className="font-semibold text-gray-900 mb-3">Bill of Materials</h3>
      {pricingUnavailable && (
        <div className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1">
          <p className="text-[11px] font-semibold text-amber-800">Pricing unavailable — saved quantities may be outdated.</p>
          {itemPricing.filter(p => p && p.available === false)
            .concat(polePricing.filter(p => p && p.available === false))
            .flatMap((p, k) =>
            (p.issues || []).map((i, j) => <p key={`${k}-${j}`} className="text-[10px] text-amber-700">{i.message}</p>)
          )}
        </div>
      )}
      {rows.length === 0 ? (
        <p className="text-sm text-gray-500">No materials yet — add a foundation to build the list.</p>
      ) : (
        <>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 border-b border-gray-200">
                <th className="py-1.5">Material</th>
                <th className="py-1.5">Quantity</th>
                <th className="py-1.5 text-right">Cost</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={i} className="border-b border-gray-100 last:border-0">
                  <td className="py-1.5 pr-3 text-gray-800">{r.material}</td>
                  <td className="py-1.5 pr-3 whitespace-nowrap text-gray-600">{r.quantity}</td>
                  <td className="py-1.5 pl-3 whitespace-nowrap text-right text-gray-900">{hasFoundationCostSnapshot(r.cost) ? money(r.cost) : "Not saved"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="flex justify-between pt-3 mt-1 border-t border-gray-200 font-bold text-gray-900">
            <span>Listed cost subtotal</span>
            <span>{pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : hasFoundationCostSnapshot(materialTotal) ? money(materialTotal) : "Not saved"}</span>
          </div>
        </>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Trash2, Wrench } from 'lucide-react';
import { money, calcEquipmentPricing, equipmentCostTotal } from './foundationCalc';
import { hasFoundationCostSnapshot } from './foundationCatalogIntegrity';
import { setFoundationEquipmentCount } from './foundationEquipmentBindings';

const fin = (v) => Number.isFinite(v);
const intQty = (v) => fin(v) && Number.isInteger(v) && v >= 0;
// Blank-preserving draft coercion (same rule as the wall/pole panels): a blank
// draft stays blank, a numeric draft becomes a number, and a malformed draft
// is stored verbatim so the pricing diagnostics can flag it — never coerced.
const equipmentInputValue = (value) => value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

function OverrideChip({ label, value, onClear, moneyVal = false, invalid = false }) {
  if (value === undefined || value === null) return null;
  return (
    <span className={`inline-flex items-center gap-1 rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${invalid ? 'bg-red-100 text-red-800 border border-red-300' : 'bg-amber-100 text-amber-800'}`}>
      {label}: {moneyVal && typeof value === 'number' ? money(value) : String(value)}
      <button type="button" aria-label={`Clear ${label}`} onClick={onClear} className={invalid ? 'text-red-900 hover:underline' : 'text-amber-900 hover:underline'}>Clear</button>
    </span>
  );
}

function EquipmentCard({ entry, detail, index, inventory, onUpdate, onRemove, showMiscAttachments }) {
  const [err, setErr] = useState('');
  useEffect(() => { setErr(''); }, [entry]);
  const eq = detail.equipment; // may be undefined when missing
  const issues = detail.issues || [];
  const broken = issues.length > 0;
  const fieldIssue = (field) => issues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `equipment-${index}-pricing` : undefined);
  const update = (next) => onUpdate(index, next);
  const setQty = (kind, id, quantity) => {
    try {
      const next = setFoundationEquipmentCount(entry, { kind, id, quantity });
      setErr('');
      update(next);
    } catch (e) { setErr(e.message || 'Quantity change rejected.'); }
  };
  const changeQty = (kind, id, raw) => {
    // Valid input reaches the shared draft immediately, including keyboard saves.
    if (raw === '') return;
    const n = Number(raw);
    if (!intQty(n)) { setErr('Quantity must be a whole number 0 or greater.'); return; }
    setQty(kind, id, n);
  };

  const eqOptions = inventory.filter(i => i.material_type === 'excavation_equipment');
  const compatibleAtts = inventory.filter(a =>
    a.material_type === 'attachment'
    && (showMiscAttachments || !a.is_miscellaneous_attachment)
    && (eq?.compatible_attachment_ids || []).includes(a.id));
  const activeParents = detail.attachmentRows.filter(r => r.quantity > 0 && r.inventory);
  const compatibleSubs = inventory.filter(s =>
    s.material_type === 'sub_attachment'
    && (showMiscAttachments || !s.is_miscellaneous_attachment)
    && activeParents.some(r => (eq?.compatible_attachment_ids || []).includes(r.id)
      && (r.inventory.compatible_sub_attachment_ids || []).includes(s.id)));
  const selectedAttIds = new Set(detail.attachmentMode === 'normalized'
    ? detail.attachmentRows.map(r => r.id)
    : detail.attachmentRows.filter(r => r.quantity !== 0).map(r => r.id));
  const selectedSubIds = new Set(detail.subAttachmentRows.filter(r => r.quantity !== 0).map(r => r.id));

  // legacy_ids: group occurrence counts per lead recipe; normalized keeps each raw row.
  const attView = detail.attachmentMode === 'legacy_ids'
    ? [...new Set(detail.attachmentRows.map(r => r.id))].map(id => ({
        id,
        quantity: detail.attachmentRows.filter(r => r.id === id).length,
        inventory: detail.attachmentRows.find(r => r.id === id)?.inventory,
        row: detail.attachmentRows.find(r => r.id === id),
        group: detail.attachmentRows.filter(r => r.id === id).length > 1,
      }))
    : detail.attachmentRows.map(row => ({ id: row.id, quantity: row.quantity, inventory: row.inventory, row, group: false }));
  const dupNormIds = detail.attachmentMode === 'normalized'
    ? new Set(detail.attachmentRows.map(r => r.id).filter((id) => detail.attachmentRows.filter(r => r.id === id).length > 1))
    : new Set();

  const periodOptions = ['day', 'week', 'month'].filter(p => eq ? fin(eq[`cost_per_${p}`]) : true);
  const savedPeriod = detail.rentalPeriod;
  if (savedPeriod && !periodOptions.includes(savedPeriod)) periodOptions.push(savedPeriod);
  const customQtyActive = entry.custom_qty !== undefined && entry.custom_qty !== null;

  const cardTotal = !broken
    ? money(detail.totalCost)
    : hasFoundationCostSnapshot(detail.totalCost) ? money(detail.totalCost) : 'Not saved';
  const lineAmt = (v) => (broken ? 'Unavailable' : money(v));

  const attRow = (a, key) => {
    const inv = a.inventory;
    const missing = !inv;
    const dupNorm = detail.attachmentMode === 'normalized' && dupNormIds.has(a.id);
    const disabledQty = dupNorm;
    return (
      <div key={key} className={`flex items-center justify-between gap-2 p-2 rounded-lg border text-xs ${a.quantity > 0 ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${a.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {dupNorm && <span className="text-amber-700 font-semibold">Duplicate rows — quantity editing disabled. </span>}
            {detail.attachmentMode === 'normalized' && a.row.sourceRecord?.qty === 0 && <span>qty 0 priced as 1. </span>}
            {a.group && <span>legacy duplicate ids ×{a.quantity} — catalog per-unit rate only. </span>}
            {!missing && inv && !a.group && hasFoundationCostSnapshot(a.row.cost) && <span>{money(a.row.cost)}</span>}
            {!missing && a.group && fin(inv?.cost_per_day) && <span>rate {money(inv.cost_per_day)}/day</span>}
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {dupNorm ? (
            <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => setQty('attachment', a.id, 0)}>Remove all duplicates</Button>
          ) : (
            <input
              type="number" min="0" disabled={disabledQty} aria-label={`Attachment qty ${inv?.material_name || a.id}`}
              className="h-7 w-14 rounded-md border border-input px-1 text-xs disabled:opacity-40"
              value={a.quantity}
              onChange={(e) => changeQty('attachment', a.id, e.target.value)}
            />
          )}
        </div>
      </div>
    );
  };

  const subRow = (s, key) => {
    const inv = s.inventory;
    const missing = !inv;
    const parentLinked = activeParents.some(r => (r.inventory.compatible_sub_attachment_ids || []).includes(s.id));
    return (
      <div key={key} className="flex items-center justify-between gap-2 p-2 rounded-lg border text-xs bg-slate-50 border-slate-200">
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${s.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {!missing && !parentLinked && <span className="text-amber-700 font-semibold">No selected parent attachment links this item. </span>}
            {!missing && hasFoundationCostSnapshot(s.cost) && <span>{money(s.cost)}</span>}
          </div>
        </div>
        <input
          type="number" min="0" aria-label={`Sub attachment qty ${inv?.material_name || s.id}`}
          className="h-7 w-14 rounded-md border border-input px-1 text-xs"
          value={s.quantity}
          onChange={(e) => changeQty('sub_attachment', s.id, e.target.value)}
        />
      </div>
    );
  };

  return (
    <Card data-equipment-index={index} className="border border-indigo-200 shadow-sm overflow-hidden mb-4">
      <CardHeader className="py-3 px-4 bg-indigo-50/60 border-b border-indigo-100">
        <div className="flex items-start justify-between">
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center gap-2 flex-wrap">
              <CardTitle className="text-sm font-semibold">{eq?.material_name || `Equipment ${index + 1}`}</CardTitle>
              {eq?.equipment_type && <Badge variant="outline" className="text-xs">{eq.equipment_type}</Badge>}
              {eq?.rental_company && <span className="text-xs text-slate-500">{eq.rental_company}</span>}
              {broken && <Badge variant="secondary" className="text-xs text-amber-800">Saved amounts (not current pricing)</Badge>}
              <Badge variant="secondary" className="text-xs">Total: {cardTotal}</Badge>
            </div>
            {eq?.notes && <p className="text-xs text-slate-500 leading-relaxed max-w-3xl">{eq.notes}</p>}
          </div>
          <div className="flex gap-1">
            <Button size="sm" variant="ghost" className="text-red-500" aria-label={`Remove equipment ${index + 1}`} onClick={onRemove}>
              <Trash2 className="w-3 h-3" aria-hidden="true" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="px-4 pb-4 space-y-4">
        {broken && (
          <ul role="status" id={`equipment-${index}-pricing`} className="list-disc pl-5 text-[11px] text-amber-800">
            {issues.map((i, k) => <li key={k}>{i.message}</li>)}
          </ul>
        )}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <Label className="text-xs">Equipment</Label>
            <Select
              value={entry.equipment_id || ''}
              onValueChange={(v) => update({ ...entry, equipment_id: v })}
            >
              <SelectTrigger className="h-8"><SelectValue placeholder="Select equipment…" /></SelectTrigger>
              <SelectContent>
                {entry.equipment_id && !eqOptions.some(o => o.id === entry.equipment_id) && (
                  <SelectItem value={entry.equipment_id} disabled>{`Catalog equipment unavailable (${entry.equipment_id})`}</SelectItem>
                )}
                {eqOptions.map(o => <SelectItem key={o.id} value={o.id}>{o.material_name}</SelectItem>)}
              </SelectContent>
            </Select>
            {eq && (eq.compatible_attachment_ids?.length || eq.compatible_sub_attachment_ids?.length) === 0 ? null : null}
            {broken && <p className="text-[10px] text-amber-700 mt-0.5">Reassigning preserves selected attachments/overrides — review compatibility.</p>}
          </div>
          <div>
            <Label className="text-xs">Rental Period</Label>
            <Select value={detail.rentalPeriod} onValueChange={(v) => update({ ...entry, rental_period: v })}>
              <SelectTrigger className="h-8"><SelectValue /></SelectTrigger>
              <SelectContent>
                {periodOptions.map(p => (
                  <SelectItem key={p} value={p}>
                    {p === 'day' ? `Daily (${fin(eq?.cost_per_day) ? money(eq.cost_per_day) : '?'}/day)`
                      : p === 'week' ? `Weekly (${fin(eq?.cost_per_week) ? money(eq.cost_per_week) : '?'}/wk)`
                      : p === 'month' ? `Monthly (${fin(eq?.cost_per_month) ? money(eq.cost_per_month) : '?'}/mo)`
                      : `Review (${savedPeriod})`}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs">Duration {customQtyActive && <span className="text-amber-700">(custom qty override active — editing duration does not clear it)</span>}</Label>
            <input
              type="number" aria-label="Rental duration" min={1} step="any"
              className="flex h-8 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm"
              value={entry.rental_duration ?? ""}
              placeholder="1"
              aria-invalid={fieldIssue("rental_duration") || undefined}
              aria-describedby={describedBy("rental_duration")}
              onChange={(e) => update({ ...entry, rental_duration: equipmentInputValue(e.target.value) })}
            />
          </div>
          <div className="flex items-end pb-1">
            <div className="flex items-center gap-2">
              <Checkbox
                checked={entry.include_delivery || false}
                onCheckedChange={(v) => update({ ...entry, include_delivery: v })}
                id={`delivery-${entry._id || index}`}
              />
              <Label htmlFor={`delivery-${entry._id || index}`} className="text-xs cursor-pointer">
                Include Delivery {fin(eq?.pickup_delivery_cost) ? `(${money(eq.pickup_delivery_cost)})` : ''}
              </Label>
            </div>
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          <OverrideChip label="Custom rate" value={entry.custom_rate} moneyVal invalid={fieldIssue('custom_rate')} onClear={() => update({ ...entry, custom_rate: null })} />
          <OverrideChip label="Custom qty" value={entry.custom_qty} invalid={fieldIssue('custom_qty')} onClear={() => update({ ...entry, custom_qty: null })} />
          <OverrideChip label={`Custom delivery${entry.include_delivery ? '' : ' (inactive — delivery excluded)'}`} value={entry.custom_delivery_charge} moneyVal invalid={fieldIssue('custom_delivery_charge')} onClear={() => update({ ...entry, custom_delivery_charge: null })} />
        </div>
        {err && <p role="alert" className="text-[11px] text-red-700">{err}</p>}
        <div className="grid grid-cols-3 gap-2 text-xs text-slate-600">
          <div>Base: <span className="font-semibold text-slate-900">{lineAmt(detail.baseCost)}</span></div>
          <div>Delivery: <span className="font-semibold text-slate-900">{lineAmt(detail.deliveryCost)}</span></div>
          <div>Total: <span className="font-semibold text-slate-900">{cardTotal}</span></div>
        </div>

        <div>
          <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">
            <Wrench className="w-3 h-3 inline mr-1" aria-hidden="true" /> Attachments
          </Label>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {attView.filter(a => detail.attachmentMode === 'normalized' || a.quantity !== 0).map((a, k) => attRow(a, k))}
          </div>
          {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).length > 0 && eq && (
            <div className="mt-2">
              <Select value="" onValueChange={(v) => v && setQty('attachment', v, 1)}>
                <SelectTrigger className="h-8"><SelectValue placeholder="Add attachment…" /></SelectTrigger>
                <SelectContent>
                  {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).map(a => (
                    <SelectItem key={a.id} value={a.id}>{a.material_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
          {attView.some(a => a.inventory && !(eq?.compatible_attachment_ids || []).includes(a.id)) && (
            <p className="text-[10px] text-amber-700 mt-1">Selected item incompatible with this parent — review.</p>
          )}
        </div>

        {detail.subAttachmentRows.filter(s => s.quantity !== 0).length > 0 && (
          <div>
            <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">Sub-attachments</Label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {detail.subAttachmentRows.filter(s => s.quantity !== 0).map((s, k) => subRow(s, k))}
            </div>
          </div>
        )}
        {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).length > 0 && eq && (
          <div>
            <Select value="" onValueChange={(v) => v && setQty('sub_attachment', v, 1)}>
              <SelectTrigger className="h-8"><SelectValue placeholder="Add sub-attachment…" /></SelectTrigger>
              <SelectContent>
                {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).map(s => (
                  <SelectItem key={s.id} value={s.id}>{s.material_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default function EquipmentTab({ foundationItems = [], inventory = [], selectedEquipmentList = [], onUpdate, markDirty }) {
  const [showAllEquipment, setShowAllEquipment] = useState(false);
  const [showMiscAttachments, setShowMiscAttachments] = useState(false);

  const pricingRows = calcEquipmentPricing(selectedEquipmentList, inventory);
  const total = equipmentCostTotal(pricingRows.map(r => r.pricedEntry));
  const incomplete = pricingRows.some(r => r.issues.length);

  const sortByOrder = (rows) => [...rows].sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0));
  const excavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && !i.is_non_excavation_equipment));
  const nonExcavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && i.is_non_excavation_equipment));
  const types = new Set((foundationItems || []).map(f => f.foundation_type));
  const hasPillar = types.has('pillar');
  const hasSpread = types.has('spread_foot');
  const filteredExcavation = showAllEquipment || (!hasPillar && !hasSpread) ? excavation
    : excavation.filter(e => (hasPillar && e.is_pillar_excavation) || (hasSpread && e.is_spread_foot_excavation));
  const filteredNonExcavation = nonExcavation;

  const addEquipment = (eqId) => {
    if (!eqId || eqId === '_none') return;
    const eqItem = inventory.find(i => i.id === eqId);
    const newEntry = {
      _id: `eq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      equipment_id: eqId,
      rental_period: 'day',
      rental_duration: 1,
      include_delivery: (eqItem?.pickup_delivery_cost || 0) > 0,
      attachment_counts: {},
      sub_attachment_counts: {},
    };
    onUpdate([...selectedEquipmentList, newEntry]);
    markDirty();
  };

  const removeEquipment = (idx) => {
    const eq = inventory.find(i => i.id === selectedEquipmentList[idx]?.equipment_id);
    if (!window.confirm(`Remove ${eq?.material_name || 'this equipment'}?`)) return;
    onUpdate(selectedEquipmentList.filter((_, i) => i !== idx));
    markDirty();
  };

  const updateEntry = (idx, updated) => {
    const arr = [...selectedEquipmentList];
    arr[idx] = updated;
    onUpdate(arr);
    markDirty();
  };

  const addSelect = (label, rows, placeholder) => (
    <div className="flex-1 min-w-[260px]">
      <Label className="text-xs font-semibold text-indigo-900 uppercase tracking-wide">{label}</Label>
      <Select value="" onValueChange={addEquipment}>
        <SelectTrigger className="h-9 mt-1"><SelectValue placeholder={placeholder} /></SelectTrigger>
        <SelectContent>
          {rows.length === 0 ? <SelectItem value="_none" disabled>No equipment available</SelectItem>
            : rows.map(eq => <SelectItem key={eq.id} value={eq.id}>{eq.material_name}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );

  return (
    <div className="space-y-4">
      <Card className="border-indigo-200 bg-indigo-50/50 shadow-sm mb-4">
        <CardContent className="py-3 px-4">
          <div className="flex items-center gap-6 mb-4 pb-4 border-b border-indigo-100">
            <div className="flex items-center gap-2">
              <Checkbox id="showAllEq" checked={showAllEquipment} onCheckedChange={setShowAllEquipment} />
              <Label htmlFor="showAllEq" className="text-sm cursor-pointer text-indigo-900 font-medium">Show all equipment</Label>
            </div>
            <div className="flex items-center gap-2">
              <Checkbox id="showMiscAtt" checked={showMiscAttachments} onCheckedChange={setShowMiscAttachments} />
              <Label htmlFor="showMiscAtt" className="text-sm cursor-pointer text-indigo-900 font-medium">Show Miscellaneous Attachments</Label>
            </div>
          </div>
          <div className="flex flex-wrap items-end gap-4">
            {addSelect('Add Excavation Equipment', filteredExcavation, 'Select excavation equipment to add…')}
            {addSelect('Add Non-Excavation Equipment', filteredNonExcavation, 'Select non-excavation equipment to add…')}
          </div>
        </CardContent>
      </Card>

      {incomplete && (
        <div role="alert" className="rounded border border-amber-300 bg-amber-50 px-3 py-2 text-[13px] text-amber-800 font-semibold">
          Pricing unavailable: selected materials or rental items need attention. Saved/known amounts only.
        </div>
      )}

      {selectedEquipmentList.length === 0 && (
        <Card className="border-dashed">
          <CardContent className="py-10 text-center text-slate-400">
            <Wrench className="w-8 h-8 mx-auto mb-2" aria-hidden="true" />
            <p className="font-medium">No equipment added yet</p>
            <p className="text-sm mt-1">Select equipment from the dropdown above.</p>
          </CardContent>
        </Card>
      )}

      {selectedEquipmentList.map((entry, idx) => (
        <EquipmentCard
          key={entry.component_id || entry._id || idx}
          entry={entry}
          detail={pricingRows[idx]}
          index={idx}
          inventory={inventory}
          onUpdate={updateEntry}
          onRemove={() => removeEquipment(idx)}
          showMiscAttachments={showMiscAttachments}
        />
      ))}

      {selectedEquipmentList.length > 0 && (
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="py-3 px-4 flex items-center justify-between">
            <span className="font-medium text-amber-800">Total Equipment Cost</span>
            <span className="text-lg font-bold text-amber-700">{incomplete ? 'Pricing unavailable' : money(total)}</span>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { Input } from "@/components/ui/input";
import { Trash2, Box, Copy } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";

const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
const num2 = (v) => (Number.isFinite(v) ? v.toFixed(2) : "Not saved");

const Field = ({ label, ...props }) => (
  <label className="text-xs text-gray-500">
    {label}
    <Input {...props} />
  </label>
);

const Check = ({ label, checked, onChange }) => (
  <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
    <input type="checkbox" checked={!!checked} onChange={(e) => onChange(e.target.checked)} />
    {label}
  </label>
);

const Picker = ({ label, value, onChange, options, placeholder }) => {
  const missing = value && !options.some((o) => o.id === value);
  return (
    <label className="text-xs text-gray-500">
      {label}
      <select
        value={value || ""}
        onChange={(e) => onChange(e.target.value)}
        className="flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm shadow-sm"
      >
        <option value="">{placeholder}</option>
        {missing && (
          <option value={value} disabled>
            Catalog item unavailable ({value})
          </option>
        )}
        {options.map((o) => (
          <option key={o.id} value={o.id}>
            {o.material_name}
          </option>
        ))}
      </select>
    </label>
  );
};

export default function FoundationItemCard({ item, index, catalog, onChange, onRemove, onDuplicate, pricing }) {
  const set = (patch) => onChange(index, patch);
  const numSet = (key) => (e) => set({ [key]: parseFloat(e.target.value) || 0 });
  // Blank clears the override (null); a malformed draft is preserved verbatim so
  // the item validation reports it instead of a NaN leaking into saved costs.
  const nullSet = (key) => (e) => set({
    [key]: e.target.value === "" ? null
      : Number.isFinite(Number(e.target.value)) ? Number(e.target.value) : e.target.value,
  });
  const isPillar = item.foundation_type === "pillar";
  const unavailable = pricing?.available === false;
  const concreteRow = (catalog.concrete || []).find((c) => c.id === item.selected_concrete_id);
  const overrideLabel = !concreteRow
    ? "Concrete cost override (unknown unit)"
    : concreteRow.material_type === "bagged_concrete"
      ? "Concrete $/bag override"
      : "Concrete $/CY override";

  return (
    <div className="bg-white rounded-sm border border-gray-200 border-l-4 border-l-amber-500 p-4">
      {unavailable && (
        <div className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1" id={`foundation-${index}-pricing`}>
          <p className="text-[11px] font-semibold text-amber-800">Saved amounts (not current pricing)</p>
          <p className="text-[10px] text-amber-700">Saved quantities may not reflect the current design.</p>
          {(pricing.issues || []).map((i, k) => (
            <p key={k} className="text-[10px] text-amber-700">{i.message}</p>
          ))}
        </div>
      )}
