          ) : (
            <>
              <Field
                label="Rebar size"
                value={item.rebar_size ?? ""}
                onChange={(e) => set({ rebar_size: e.target.value })}
              />
              <Field
                label="Spacing length (in)"
                type="number"
                value={item.rebar_spacing_length ?? 12}
                onChange={numSet("rebar_spacing_length")}
              />
              <Field
                label="Spacing width (in)"
                type="number"
                value={item.rebar_spacing_width ?? 12}
                onChange={numSet("rebar_spacing_width")}
              />
              <Field label="Layers" type="number" value={item.rebar_layers ?? 1} onChange={numSet("rebar_layers")} />
            </>
          )}
          <div className="col-span-2 sm:col-span-4 text-xs text-gray-500">
            {Number.isFinite(item.rebar_feet) ? item.rebar_feet.toFixed(1) : "Not saved"} ft ·{" "}
            {Number.isFinite(item.rebar_weight_lbs) ? item.rebar_weight_lbs.toFixed(0) : "Not saved"} lbs ·{" "}
            {amt(item.rebar_cost)}
          </div>
        </div>
      )}

      {/* Excavation summary */}
      <div className="mt-3 rounded-sm border border-amber-200 bg-amber-50 px-3 py-2">
        <div className="text-[10px] font-bold uppercase tracking-wide text-amber-700">Excavation</div>
        <div className="text-[11px] text-amber-900">
          Volume: ~{Number.isFinite(item.excavation_volume_cy) ? item.excavation_volume_cy.toFixed(2) : "Not saved"} CY · Cost: {amt(item.excavation_cost)}
        </div>
      </div>

      {/* Cost breakdown */}
      <div className="mt-3 rounded-sm border border-gray-200 bg-slate-50 p-2">
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
          {[
            ["Rebar", item.rebar_cost],
            ["Forming", item.forming_cost],
            ["Pouring", item.pouring_cost],
            ["Finishing", item.finishing_cost],
            ["Excavation", item.excavation_cost],
          ].map(([label, value]) => (
            <div key={label} className="px-1">
              <div className="text-gray-400">{label}</div>
              <div className="font-semibold text-gray-800">{amt(value)}</div>
            </div>
          ))}
        </div>
        <div className="mt-2 text-center text-[11px] italic text-amber-700">
          Concrete material &amp; truck costs are aggregated for the entire project.
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Move, ZoomIn, ZoomOut } from "lucide-react";
import {
  FOUNDATION_LAYOUT_WIDTH_INCHES,
  FOUNDATION_LAYOUT_DEPTH_INCHES,
  layoutPointInches,
  foundationLayoutFootprint,
  layoutPositionInches,
  layoutItemKey,
  layoutItemFingerprint,
} from "./foundationLayoutModel";

export default function FoundationLayoutCanvas({ items = [], poles = [], onMoveItem }) {
  const boxRef = useRef(null);
  const [zoom, setZoom] = useState(1);
  const dragRef = useRef(null);
  const [preview, setPreview] = useState(null); // {key,x,z} transient only
  const editable = typeof onMoveItem === "function";

  const pctW = (inches) => `${(inches / FOUNDATION_LAYOUT_WIDTH_INCHES) * 100}%`;
  const pctD = (inches) => `${(inches / FOUNDATION_LAYOUT_DEPTH_INCHES) * 100}%`;

  const findCurrentIndex = (d) => {
    if (d.identityKind === "index") {
      // id-less legacy fallback: index identity only, cancel if array changed
      return items.length === d.count ? d.legacyIndex : -1;
    }
    return items.findIndex((it, i) => layoutItemKey(it, i) === d.key);
  };

  const mountedRef = useRef(true);
  useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; dragRef.current = null; }; }, []);

  const cancelDrag = (e) => {
    if (e?.pointerId !== undefined && dragRef.current && e.pointerId !== dragRef.current.pointerId) return;
    dragRef.current = null;
    setPreview(null);
  };

  const onPointerDown = (e, item, index) => {
    if (!mountedRef.current || !editable || e.button !== 0) return;
    if (e.isPrimary === false || dragRef.current) return; // secondary touch must not replace an active gesture
    const fp = foundationLayoutFootprint(item);
    const pos = layoutPositionInches(item);
    if (!fp || !pos.valid) return;
    const rect = boxRef.current?.getBoundingClientRect();
    const point = layoutPointInches(e.clientX, e.clientY, rect);
    if (!point) return;
    const key = layoutItemKey(item, index);
    const [kind] = key.split(":");
    dragRef.current = {
      pointerId: e.pointerId,
      key,
      identityKind: kind,
      legacyIndex: index,
      count: items.length,
      corner: { x: pos.x_inches, z: pos.z_inches },
      grab: { dx: point.x_inches - pos.x_inches, dz: point.z_inches - pos.z_inches },
      fingerprint: layoutItemFingerprint(item),
      moved: false,
    };
    try { boxRef.current.setPointerCapture(e.pointerId); }
    catch { cancelDrag(); return; }
    setPreview({ key, x: pos.x_inches, z: pos.z_inches });
  };

  const onPointerMove = (e) => {
    const d = dragRef.current;
    if (!d || e.pointerId !== d.pointerId) return;
    const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
    if (!point) return;
    d.moved = true;
    d.last = { x: point.x_inches - d.grab.dx, z: point.z_inches - d.grab.dz };
    setPreview({ key: d.key, x: d.last.x, z: d.last.z });
  };

  const commitDrag = (e) => {
    const d = dragRef.current;
    if (!d || e.pointerId !== d.pointerId) return;
    dragRef.current = null; // clear before release/callback — one commit per gesture
    try { boxRef.current?.releasePointerCapture(e.pointerId); } catch { }
    setPreview(null);
    if (!mountedRef.current) return;
    // final corner from the release point itself, not the last move preview
    const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
    if (!point) return;
    const raw = { x: point.x_inches - d.grab.dx, z: point.z_inches - d.grab.dz };
    if (raw.x === d.corner.x && raw.z === d.corner.z) return; // unchanged incl. fractional legacy corners
    const roundX = Math.round(raw.x), roundZ = Math.round(raw.z);
    if (roundX === d.corner.x && roundZ === d.corner.z) return; // sub-inch wiggle rounded to same corner
    const index = findCurrentIndex(d);
    if (index < 0) return; // deleted during gesture
    const live = items[index];
    if (layoutItemFingerprint(live) !== d.fingerprint) return; // authoritative change mid-drag
    if (typeof onMoveItem !== "function") return;
    onMoveItem(index, { x_inches: roundX, z_inches: roundZ });
  };

  const onKeyDown = (e, item, index) => {
    if (!mountedRef.current || !editable) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const step = e.shiftKey ? 12 : 1;
    const dirs = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
    const dir = dirs[e.key];
    if (!dir) return;
    const fp = foundationLayoutFootprint(item);
    const pos = layoutPositionInches(item);
    if (!fp || !pos.valid) return;
    e.preventDefault();
    onMoveItem(index, { x_inches: pos.x_inches + dir[0], z_inches: pos.z_inches + dir[1] });
  };

  const invalidNotes = items.map((item, index) => ({ item, index }))
    .filter(({ item }) => !foundationLayoutFootprint(item) || !layoutPositionInches(item).valid);

  return (
    <div className="bg-white rounded-sm border border-gray-200 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
        <div>
          <h3 className="text-[13px] font-bold text-gray-900">Layout Canvas</h3>
          <p className="text-[11px] text-gray-400">
            {editable ? "Drag a foundation, or focus it and use arrow keys (Shift for larger steps)." : "Foundation positions (read-only)."}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap text-[11px] text-gray-600">
          <span className="flex items-center gap-1">
            <Move className="w-3 h-3" aria-hidden="true" /> Move Foundation
          </span>
          <span className="text-gray-400">40ft × 26ft 8in</span>
          <button
            type="button"
            onClick={() => setZoom((z) => Math.max(0.5, +(z - 0.25).toFixed(2)))}
            aria-label="Zoom layout out"
            className="w-6 h-6 flex items-center justify-center rounded-sm border border-gray-300 hover:bg-gray-50"
          >
            <ZoomOut className="w-3 h-3" aria-hidden="true" />
          </button>
          <span className="w-10 text-center">{Math.round(zoom * 100)}%</span>
          <button
            type="button"
            onClick={() => setZoom((z) => Math.min(2, +(z + 0.25).toFixed(2)))}
            aria-label="Zoom layout in"
            className="w-6 h-6 flex items-center justify-center rounded-sm border border-gray-300 hover:bg-gray-50"
          >
            <ZoomIn className="w-3 h-3" aria-hidden="true" />
          </button>
        </div>
      </div>

      <div className="overflow-auto rounded-sm border border-gray-300 bg-gray-50">
        <div
          ref={boxRef}
          onPointerMove={onPointerMove}
          onPointerUp={commitDrag}
          onPointerCancel={cancelDrag}
          onLostPointerCapture={(e) => cancelDrag(e)}
          className="relative aspect-[3/2] select-none"
          style={{
            width: `${zoom * 100}%`,
            backgroundImage:
              "linear-gradient(to right, rgba(0,0,0,0.06) 1px, transparent 1px), linear-gradient(to bottom, rgba(0,0,0,0.06) 1px, transparent 1px)",
            backgroundSize: "8.333% 12.5%",
          }}
        >
          {items.map((item, index) => {
            const fp = foundationLayoutFootprint(item);
            const pos = layoutPositionInches(item);
            if (!fp || !pos.valid) return null;
            const key = layoutItemKey(item, index);
            const shown = preview && preview.key === key ? { x_inches: preview.x, z_inches: preview.z } : pos;
            return (
              <div
                key={key}
                role={editable ? "button" : undefined}
                tabIndex={editable ? 0 : undefined}
                aria-label={editable ? `Move Foundation ${index + 1}` : undefined}
                onPointerDown={editable ? (e) => onPointerDown(e, item, index) : undefined}
                onKeyDown={editable ? (e) => onKeyDown(e, item, index) : undefined}
                className={`absolute flex items-center justify-center border-2 border-dashed border-amber-500 bg-amber-100/70 text-[10px] font-semibold text-amber-800 ${
                  editable ? "cursor-move" : ""
                } ${item.foundation_type === "pillar" ? "rounded-full" : "rounded-sm"}`}
                style={{
                  left: pctW(shown.x_inches),
                  top: pctD(shown.z_inches),
                  width: pctW(fp.width),
                  height: pctD(fp.depth),
                  transform: `rotate(${item.rotation_degrees || 0}deg)`,
                  touchAction: editable ? "none" : undefined,
                }}
                title={`Foundation ${index + 1}`}
              >
                Foundation {index + 1}
              </div>
            );
          })}

          {preview && (
            <div className="absolute left-1 top-1 z-10 rounded-sm bg-amber-50/90 px-1.5 py-0.5 text-[10px] font-semibold text-amber-800" style={{ pointerEvents: "none" }}>
              Move preview - release to apply
            </div>
          )}

          {poles.map((pole, index) => (
            <div
              key={layoutItemKey(pole, index)}
              className="absolute w-2.5 h-2.5 rounded-full bg-slate-700 border border-white"
              style={{
                left: pctW(pole.x_inches || 0),
                top: pctD(pole.z_inches || 0),
                transform: "translate(-50%,-50%)",
                pointerEvents: "none",
              }}
              title={`Pole ${index + 1}`}
            />
          ))}
        </div>
      </div>

      {invalidNotes.map(({ index }) => (
        <p key={index} className="mt-1 text-[11px] text-amber-700">
          Foundation {index + 1} needs valid dimensions/coordinates before placement.
        </p>
      ))}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";

const heightInput = (value) => value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

export default function FoundationPolesPanel({ poles = [], options = [], items = [], onChange, polePricing = [] }) {
  const patchPole = (index, changes) =>
    onChange(poles.map((p, i) => (i === index ? { ...p, ...changes } : p)));

  const removePole = (index) => {
    if (!window.confirm(`Remove Pole ${index + 1}? Cabinets mounted on it are retained for review.`)) return;
    onChange(poles.filter((_, i) => i !== index));
  };

  const addPole = () =>
    onChange([
      ...poles,
      { pole_id: options[0]?.id || "", height_inches: 120, y_offset_inches: 42, include_pole_painting: false },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Poles</h2>
          <p className="text-xs text-gray-500">
            Priced on total length — height above grade plus depth in the ground.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addPole} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Pole
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Pole catalog unavailable — existing rows remain editable; new poles cannot be added.
        </div>
      )}
      {poles.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No poles on this section.
        </div>
      ) : (
        poles.map((pole, index) => {
          const issues = polePricing[index]?.issues || [];
          const pricingUnavailable = polePricing[index]?.available === false;
          const fieldIssue = (field) => issues.some((i) => i.field === field);
          const describedBy = issues.length ? `pole-${index}-pricing` : undefined;
          return (
            <div key={pole.component_id || index} className="bg-white rounded-xl border border-gray-200 p-3">
              <div className="grid grid-cols-2 md:grid-cols-5 gap-2 items-end">
                <label className="text-xs text-gray-500 md:col-span-2">
                  Pole
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.pole_id || ""}
                    aria-label="Pole material"
                    aria-invalid={fieldIssue("pole_id") || undefined}
                    aria-describedby={fieldIssue("pole_id") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_id: e.target.value })}
                  >
                    <option value="">Select pole…</option>
                    {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                      <option value={pole.pole_id} disabled>{`Catalog pole unavailable (${pole.pole_id})`}</option>
                    )}
                    {options.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.material_name}
                      </option>
                    ))}
                  </select>
                  {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                    <span className="block text-[10px] text-amber-700 mt-1">Catalog pole unavailable; current pricing needs review.</span>
                  )}
                </label>
                <label className="text-xs text-gray-500">
                  Height above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.height_inches ?? ""}
                    aria-label={`Pole ${index + 1} height above grade (inches)`}
                    aria-invalid={fieldIssue("height_inches") || undefined}
                    aria-describedby={fieldIssue("height_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { height_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Depth in ground (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.y_offset_inches ?? ""}
                    aria-label={`Pole ${index + 1} depth in ground (inches)`}
                    aria-invalid={fieldIssue("y_offset_inches") || undefined}
                    aria-describedby={fieldIssue("y_offset_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { y_offset_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Foundation
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.foundation_component_id ?? ""}
                    aria-label="Pole foundation"
                    onChange={(e) => {
                      const id = e.target.value;
                      const i = items.findIndex((it) => it.component_id === id);
                      patchPole(index, {
                        foundation_component_id: id,
                        foundation_idx: id === "" || i < 0 ? undefined : i,
                      });
                    }}
                  >
                    <option value="">Unassigned</option>
                    {pole.foundation_component_id && !items.some((it) => it.component_id === pole.foundation_component_id) && (
                      <option value={pole.foundation_component_id} disabled>{`Missing foundation (${String(pole.foundation_component_id).slice(0, 18)}…)`}</option>
                    )}
                    {items.map((it, i) => (
                      <option key={it.component_id || i} value={it.component_id || ""}>
                        {it.description || `Foundation ${i + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
              </div>

              <div className="flex items-center justify-between mt-2">
                <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={!!pole.include_pole_painting}
                    aria-invalid={issues.some((i) => i.code === "pole_paint_setting_unavailable") || undefined}
                    aria-describedby={issues.some((i) => i.code === "pole_paint_setting_unavailable") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { include_pole_painting: e.target.checked })}
                  />
                  Paint pole
                </label>
                <div className="flex items-center gap-3 text-xs text-gray-600">
                  <span>Pole {hasFoundationCostSnapshot(pole.pole_cost) ? money(pole.pole_cost) : "Not saved"}</span>
                  <span>Paint {hasFoundationCostSnapshot(pole.pole_painting_cost) ? money(pole.pole_painting_cost) : "Not saved"}</span>
                  <span className="font-bold text-gray-900 text-sm">{hasFoundationCostSnapshot(pole.total_cost) ? money(pole.total_cost) : "Not saved"}</span>
                  {pricingUnavailable && <span className="col-span-full text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                  <Button variant="ghost" size="icon" onClick={() => removePole(index)}>
                    <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                  </Button>
                </div>
              </div>
              {issues.length > 0 && (
                <div role="status" className="mt-2 text-[10px] text-amber-700 space-y-0.5" id={`pole-${index}-pricing`}>
                  {issues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
                </div>
              )}
            </div>
          );
        })
      )}
    </div>
  );
}

