export const calcItemCost = (item, inventory = [], settings = {}) => {
  // Explicit-0-respecting setting pick (same semantics as pole/wallSettingValue):
  // a recorded 0 rate is legitimate; absent/blank keeps the ported default.
  const getSetting = (key, def) => parseFloat(settings[key] === 0 ? 0 : settings[key] || def);

  const selectedConcrete = inventory.find(c => c.id === item.selected_concrete_id);
  const conc_cost = item.custom_concrete_cost_per_cy !== null && item.custom_concrete_cost_per_cy !== undefined
    ? item.custom_concrete_cost_per_cy
    : (selectedConcrete?.cost_per_unit || 0);

  // Find the selected rebar from inventory (matching the #size)
  const selectedRebar = inventory.find(r => r.material_type === 'rebar' && r.rebar_size === item.rebar_size);
  const pillarSelectedRebar = inventory.find(r => r.material_type === 'rebar' && r.rebar_size === (item.pillar_rebar_size || '#4'));
  const activeRebar = item.foundation_type === 'spread_foot' ? selectedRebar : pillarSelectedRebar;

  const rebar_cost = item.custom_rebar_cost_per_ft !== null && item.custom_rebar_cost_per_ft !== undefined
    ? item.custom_rebar_cost_per_ft
    : (activeRebar?.cost_per_unit || 0);

  const main_labor_rate = getSetting('foundation_main_labor_rate', 60);
  const rebar_time_cross_section = getSetting('foundation_rebar_time_cross_section', 0.05);
  const rebar_time_linear_ft = getSetting('foundation_rebar_time_linear_ft', 0.02);

  const forming_cost_per_sqft = getSetting('foundation_forming_cost_per_sqft', 2.50);
  const pouring_cost_per_cy = getSetting('foundation_pouring_cost_per_cy', 15);
  const finishing_cost_per_sqft = getSetting('foundation_finishing_cost_per_sqft', 1.25);

  const forming_mult = item.foundation_type === 'spread_foot'
    ? getSetting('foundation_forming_materials_spread_foot', 0.5)
    : getSetting('foundation_forming_materials_pillar', 0.75);

  let baseVolumeCY = 0;
  const lenIn = parseFloat(item.length_inches) || 0;
  const widIn = parseFloat(item.width_inches) || 0;
  const depIn = parseFloat(item.depth_inches) || 0;
  const diaIn = parseFloat(item.diameter) || 0;

  if (item.foundation_type === 'spread_foot') {
    baseVolumeCY = ((lenIn / 12) * (widIn / 12) * (depIn / 12)) / 27;
  } else {
    const r = (diaIn / 2) / 12;
    baseVolumeCY = (Math.PI * r * r * (depIn / 12)) / 27;
  }
  baseVolumeCY = baseVolumeCY * (item.quantity || 1);

  const volumeCY = item.custom_concrete_qty !== null && item.custom_concrete_qty !== undefined ? item.custom_concrete_qty : baseVolumeCY;

  let concreteCost = 0;
  let baseBags = null;
  let concreteBags = null;

  if (selectedConcrete?.material_type === 'bagged_concrete') {
    baseBags = Math.ceil(baseVolumeCY * 45); // ~45 80lb bags per CY
    concreteBags = item.custom_concrete_qty !== null && item.custom_concrete_qty !== undefined ? item.custom_concrete_qty : baseBags;
    concreteCost = concreteBags * conc_cost;
  }

  let rebarCost = 0;
  let baseRebarFt = 0;
  let totalIntersections = 0;

  if (item.include_rebar && item.foundation_type === 'spread_foot') {
    const nBarsL = Math.floor(widIn / (parseFloat(item.rebar_spacing_width) || 12)) + 1;
    const nBarsW = Math.floor(lenIn / (parseFloat(item.rebar_spacing_length) || 12)) + 1;
    const layers = parseInt(item.rebar_layers) || 1;
    const horizontalFt = (nBarsL * (lenIn / 12) + nBarsW * (widIn / 12)) * layers;

    const numIntersections = nBarsL * nBarsW * layers;
    const verticalLengthFt = Math.max(0, depIn - 6) / 12;
    const verticalFt = numIntersections * verticalLengthFt;

    baseRebarFt = (horizontalFt + verticalFt) * (parseInt(item.quantity) || 1);
    totalIntersections = numIntersections * (parseInt(item.quantity) || 1);
  } else if (item.include_rebar && item.foundation_type === 'pillar') {
    const hoopDia = parseFloat(item.pillar_rebar_hoop_diameter) || Math.max(0, diaIn - 4);
    const safeHoopDia = Math.min(hoopDia, Math.max(0, diaIn - 4));
    const layers = parseInt(item.pillar_rebar_layers) || 1;
    const verticalCount = parseInt(item.pillar_vertical_rebar_count) || 4;

    const hoopLengthFt = (Math.PI * safeHoopDia) / 12;
    const totalHoopFt = hoopLengthFt * layers;

    const verticalLengthFt = Math.max(0, depIn - 6) / 12;
    const totalVerticalFt = verticalCount * verticalLengthFt;

    baseRebarFt = (totalHoopFt + totalVerticalFt) * (parseInt(item.quantity) || 1);
    totalIntersections = (layers * verticalCount) * (parseInt(item.quantity) || 1);
  }

  const rebarFt = item.custom_rebar_qty !== null && item.custom_rebar_qty !== undefined ? item.custom_rebar_qty : baseRebarFt;
  if (item.include_rebar) {
    const materialCost = rebarFt * rebar_cost;
    const totalTimeHours = (totalIntersections * rebar_time_cross_section) + (rebarFt * rebar_time_linear_ft);
    const laborCost = totalTimeHours * main_labor_rate;
    rebarCost = materialCost + laborCost;
  }

  let formingCost = 0;
  let baseFormingQty = 0;
  const selectedForming = inventory.find(i => i.id === item.selected_forming_id);
  const forming_rate = item.custom_forming_rate !== null && item.custom_forming_rate !== undefined ? item.custom_forming_rate : (selectedForming?.cost_per_unit || 0);

  if (item.include_forming) {
    const perim = item.foundation_type === 'spread_foot'
      ? 2 * (lenIn + widIn) / 12
      : Math.PI * diaIn / 12;
    const formingAreaSqFt = perim * (depIn / 12);

    // Calculate pcs based on perimeter — standard 16ft lengths
    baseFormingQty = Math.ceil(perim / 16) * (parseInt(item.quantity) || 1);
    const formingQty = item.custom_forming_qty !== null && item.custom_forming_qty !== undefined ? item.custom_forming_qty : baseFormingQty;

    const formingMaterialCost = formingQty * forming_rate;

    // Keep old labor calculation logic
    const laborCost = formingAreaSqFt * (parseInt(item.quantity) || 1) * forming_cost_per_sqft;
    formingCost = laborCost + formingMaterialCost + (concreteCost * forming_mult);
  }

  let finishingCost = 0;
  let baseFinishingHours = 0;
  const finishing_rate = item.custom_finishing_rate !== null && item.custom_finishing_rate !== undefined ? item.custom_finishing_rate : main_labor_rate;

  if (item.include_finishing) {
    const topArea = item.foundation_type === 'spread_foot'
      ? (lenIn * widIn) / 144
      : Math.PI * ((diaIn / 2 / 12) ** 2);

    // back out hours from sqft cost formula
    const defaultFinishingCost = topArea * (parseInt(item.quantity) || 1) * finishing_cost_per_sqft;
    baseFinishingHours = defaultFinishingCost / main_labor_rate;
    const finishingHours = item.custom_finishing_hours !== null && item.custom_finishing_hours !== undefined ? item.custom_finishing_hours : baseFinishingHours;

    finishingCost = finishingHours * finishing_rate;
  }

  const pouringCost = volumeCY * pouring_cost_per_cy;

  let excavationCost = 0;
  let baseExcavationHours = 0;
  const excVol = volumeCY * 1.25;
  if (item.excavation_method === 'hand_dig' || !item.excavation_method) {
    const timePerCy = getSetting('foundation_hand_dig_time_per_cy', 2.0);
    baseExcavationHours = excVol * timePerCy;
  } else {
    const timePerCy = getSetting('foundation_equipment_excavation_time_per_cy', 0.5);
    baseExcavationHours = excVol * timePerCy;
  }

  const excavationHours = item.custom_excavation_hours !== null && item.custom_excavation_hours !== undefined ? item.custom_excavation_hours : baseExcavationHours;
  const excavation_rate = item.custom_excavation_rate !== null && item.custom_excavation_rate !== undefined ? item.custom_excavation_rate : main_labor_rate;

  excavationCost = excavationHours * excavation_rate;

  return {
    concreteCost,
    concreteBags,
    volumeCY,
    baseVolumeCY,
    baseBags,
    rebarCost,
    rebarFt,
    baseRebarFt,
    formingCost,
    formingQty: item.custom_forming_qty !== null && item.custom_forming_qty !== undefined ? item.custom_forming_qty : baseFormingQty,
    baseFormingQty,
    finishingCost,
    finishingHours: item.custom_finishing_hours !== null && item.custom_finishing_hours !== undefined ? item.custom_finishing_hours : baseFinishingHours,
    baseFinishingHours,
    pouringCost,
    excavationCost,
    excavationHours,
    baseExcavationHours,
    concreteRate: conc_cost,
    rebarRate: rebar_cost,
    formingRate: forming_rate,
    finishingRate: finishing_rate,
    excavationRate: excavation_rate,
    selectedConcreteName: selectedConcrete?.material_name || '',
    selectedRebarName: activeRebar?.material_name || '',
    selectedFormingName: selectedForming?.material_name || '',
    total: concreteCost + rebarCost + formingCost + finishingCost + pouringCost + excavationCost,
  };
};

/**
 * Project-level concrete delivery math: 9-yard trucks, quarter-yard rounding,
 * small-load fee bracket + fuel surcharge per truck, plus $100 per new sign location stop.
 * (The $100 per-location stop charge is an authored constant of the ported
 * formula — it has no catalog/settings source and always resolves.)
 *
 * When yards actually ship, every consumed supplier-catalog price must be a
 * recorded finite, nonnegative number — an explicit 0 is a legitimate free
 * price, but the ported `??` guesses laundered unpriced suppliers into
 * plausible-looking retail amounts. Consumption mirrors the ported math
 * exactly: a mix/admixture the project did not select and a small-load bracket
 * no truck falls into are never checked.
 */
export const calcConcreteDelivery = (project, items = [], inventory = []) => {
  const concreteServiceItems = items.filter((item) => {
    const inv = inventory.find(i => i.id === item.selected_concrete_id);
    return !inv || inv.material_type === 'concrete_service';
  });
  const totalConcreteYards = concreteServiceItems.reduce((sum, item) => sum + calcItemCost(item, inventory, project.settings || {}).volumeCY, 0);
  const roundedYards = Math.ceil(totalConcreteYards * 4) / 4;

  const firstConcreteItem = concreteServiceItems.find(i => inventory.find(inv => inv.id === i.selected_concrete_id)?.material_type === 'concrete_service');
  const firstConcreteInv = firstConcreteItem ? inventory.find(inv => inv.id === firstConcreteItem.selected_concrete_id) : null;

  const availableMixes = getConcreteMixes(firstConcreteInv);
  const availableAdmixes = getConcreteAdmixtures(firstConcreteInv);

  const issues = [];
  const add = (field, code, message) => issues.push({
    kind: "concrete_delivery", index: null, componentId: null, field,
    inventoryId: firstConcreteInv?.id ?? null, code,
    message: `Concrete delivery: ${message}.`,
  });

  const mix = availableMixes.find(m => m.id === project.project_concrete_type) || availableMixes.find(m => m.id === '4000_ae');

  if (roundedYards > 0) {
    if (firstConcreteInv === null) {
      add("selected_concrete_id", "supplier_unavailable",
        "no ready-mix concrete supplier is assigned — select a supplier with catalog prices before repricing");
    } else {
      if (project.project_concrete_type && !availableMixes.some(m => m.id === project.project_concrete_type)) {
        add("project_concrete_type", "supplier_price_unavailable",
          "the saved mix selection is not in the supplier catalog — pick a listed mix before repricing");
      }
      if (!mix || supplierPriceNumber(mix.price) === null) {
        add(mix?.field || "mix_price", "supplier_price_unavailable",
          `record a finite, nonnegative ${mix?.name || "selected mix"} price on the concrete supplier before repricing`);
      }
      for (const admixId of project.project_concrete_admixtures || []) {
        const admix = availableAdmixes.find(x => x.id === admixId);
        if (!admix) {
          add("project_concrete_admixtures", "supplier_price_unavailable",
            "the saved admixture selection is not in the supplier catalog — pick a listed admixture before repricing");
        } else if (supplierPriceNumber(admix.price) === null) {
          add(admix.field || "admix_price", "supplier_price_unavailable",
            `record a finite, nonnegative ${admix.name} price on the concrete supplier before repricing`);
        }
      }
      if (supplierPriceNumber(firstConcreteInv.fuel_surcharge) === null) {
        add("fuel_surcharge", "supplier_price_unavailable",
          "record a finite, nonnegative fuel surcharge on the concrete supplier before repricing");
      }
      let scanYards = roundedYards;
      while (scanYards > 0) {
        const truckYards = Math.min(scanYards, 9);
        scanYards -= truckYards;
        const roundedTruckYards = Math.ceil(truckYards * 4) / 4;
        if (getSmallLoadFee(roundedTruckYards, firstConcreteInv) === null) {
          add("small_load_fee", "supplier_price_unavailable",
            `record a finite, nonnegative small-load fee for the ${roundedTruckYards} CY truck bracket on the concrete supplier before repricing`);
          break; // one issue covers every unpriced bracket this delivery consumes
        }
      }
    }
  }

  if (issues.length) {
    return {
      pricingUnavailable: true, issues, concreteTotal: null, roundedYards,
      ratePerYard: null, trucksList: [], additionalStopsCost: null,
      availableMixes, availableAdmixes,
    };
  }

  const mixPrice = mix ? mix.price : 201;

  const admixPrice = (project.project_concrete_admixtures || []).reduce((sum, admixId) => {
    const a = availableAdmixes.find(x => x.id === admixId);
    return sum + (a ? a.price : 0);
  }, 0);

  const ratePerYard = mixPrice + admixPrice;

  let concreteTotal = 0;
  let remainingYards = roundedYards;
  const trucksList = [];
  const fuelSurcharge = getFuelSurcharge(firstConcreteInv);

  while (remainingYards > 0) {
    const truckYards = Math.min(remainingYards, 9);
    remainingYards -= truckYards;

    // Round up to next quarter yard for cost calculation
    const roundedTruckYards = Math.ceil(truckYards * 4) / 4;

    const smallOrderFee = getSmallLoadFee(roundedTruckYards, firstConcreteInv);
    const fuelFee = fuelSurcharge;

    const truckCost = (roundedTruckYards * ratePerYard) + smallOrderFee + fuelFee;
    trucksList.push({ yards: truckYards, roundedYards: roundedTruckYards, cost: truckCost, smallOrderFee, fuelFee });
    concreteTotal += truckCost;
  }

  const newSignLocationsCount = items.filter(i => i.is_new_sign_location).length;
  const additionalStopsCost = newSignLocationsCount * 100;
  concreteTotal += additionalStopsCost;

  return { issues, concreteTotal, roundedYards, ratePerYard, trucksList, additionalStopsCost, availableMixes, availableAdmixes };
};

// Pole + pole-painting math — ported VERBATIM from SignEstimate Pro
// (NewFoundationEstimate.jsx: polesTotal / calcPolePaintingCost /
//  getPolePaintingSizeMultiplier). Poles are PROJECT-level, not per foundation item.
//
// Availability hardening: a missing price, malformed dimension, or invalid
// painting setting is not a free pole — the row is held with its acknowledged
// snapshot amounts and reported instead of silently repricing to $0.

const assignedId = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

// Explicit-0-respecting setting pick (same semantics as wallSettingValue).
const poleSettingValue = (value, fallback) => value === 0 ? 0 : value || fallback;

const setting = (settings, key, def) => parseFloat(poleSettingValue(settings?.[key], def));

// Catalog/customer price basis: finite, nonnegative — an explicit 0 is a valid free price.
const polePriceNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
};

// Positive finite dimension in inches/feet (height above grade, stock length, pole width).
const poleDimensionNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
};

// Depth in ground may legitimately be zero (surface-mounted pole); negatives are not lengths.
const poleOffsetNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
};

// Missing/blank settings fall back to the module default; present values must be
// finite nonnegative numbers (explicit 0 honored — a genuinely free rate).
const poleSettingNumber = (value, fallback) => polePriceNumber(poleSettingValue(value, fallback));
const polePositiveSettingNumber = (value, fallback) => poleDimensionNumber(poleSettingValue(value, fallback));

const POLE_PAINT_SETTING_DEFAULTS = {
  pole_paint_cost_per_lf: 3.5,
  pole_paint_labor_per_lf: 2.5,
  pole_paint_size_multiplier_12in: 2.0,
  pole_paint_size_multiplier_10in: 1.75,
  pole_paint_size_multiplier_8in: 1.5,
  pole_paint_size_multiplier_6in: 1.25,
  pole_paint_size_multiplier_4in: 1.0,
};

const polePaintMultiplierKey = (widthInches) => {
  const w = widthInches === null ? 6 : widthInches;
  if (w >= 12) return "pole_paint_size_multiplier_12in";
  if (w >= 10) return "pole_paint_size_multiplier_10in";
  if (w >= 8) return "pole_paint_size_multiplier_8in";
  if (w >= 6) return "pole_paint_size_multiplier_6in";
  return "pole_paint_size_multiplier_4in";
};

const getPolePaintingSizeMultiplier = (inv, settings) => {
  const w = inv?.pole_width_inches || 6;
  if (w >= 12) return setting(settings, "pole_paint_size_multiplier_12in", 2.0);
  if (w >= 10) return setting(settings, "pole_paint_size_multiplier_10in", 1.75);
  if (w >= 8) return setting(settings, "pole_paint_size_multiplier_8in", 1.5);
  if (w >= 6) return setting(settings, "pole_paint_size_multiplier_6in", 1.25);
  return setting(settings, "pole_paint_size_multiplier_4in", 1.0);
};

export const calcPolePaintingCost = (p, inv, settings) => {
  if (!p.include_pole_painting || !inv) return 0;
  // Total pole length = height above ground + depth in ground.
  const heightFt = ((p.height_inches || 0) + (p.y_offset_inches || 0)) / 12;
  const paintCostPerLf = setting(settings, "pole_paint_cost_per_lf", 3.5);
  const paintLaborPerLf = setting(settings, "pole_paint_labor_per_lf", 2.5);
  const sizeMult = getPolePaintingSizeMultiplier(inv, settings);
  return heightFt * (paintCostPerLf + paintLaborPerLf) * sizeMult;
};

// Resolves the catalog row and every value the pricing formulas read, on a
// normalized calculation copy — authored rows and settings are never mutated.
function polePricing(pole, inventory = [], index = 0, settings = {}) {
  const issues = [];
  const id = pole?.pole_id;
  const add = (field, code, message) => issues.push({
    kind: "pole", index, componentId: pole?.component_id ?? pole?.id ?? null,
    field, inventoryId: assignedId(id) ? id : null, code,
    message: `Pole ${index + 1}: ${message}.`,
  });
  let inv = null;
  if (!assignedId(id)) {
    add("pole_id", "catalog_item_unassigned", "select a catalog material");
  } else {
    const matches = inventory.filter((row) => row?.id === id);
    if (!matches.length) {
      add("pole_id", "catalog_item_unavailable", "selected catalog material is unavailable");
    } else if (matches.length !== 1) {
      add("pole_id", "catalog_item_ambiguous", "selected catalog material is ambiguous");
    } else if (matches[0].material_type !== "pole") {
      add("pole_id", "catalog_item_type_mismatch", "selected catalog material is not a pole");
    } else {
      inv = matches[0];
    }
  }
  const heightInches = poleDimensionNumber(pole?.height_inches);
  if (heightInches === null) {
    add("height_inches", "pole_height_unavailable",
      "record a positive, finite height above grade in inches before repricing");
  }
  const depthInches = poleOffsetNumber(pole?.y_offset_inches);
  if (depthInches === null) {
    add("y_offset_inches", "pole_depth_unavailable",
      "record a finite, nonnegative depth in ground in inches before repricing");
  }
  let rate = null;
  let stockLengthInches = null;
  let widthInches = null;
  const paint = { costPerLf: null, laborPerLf: null, sizeMultiplier: null };
  if (inv) {
    const override = pole?.custom_cost_per_unit;
    const hasOverride = override !== undefined && override !== null;
    const stockMode = inv.pole_pricing_mode === "stock_price";
    rate = polePriceNumber(hasOverride ? override : (stockMode ? inv.pole_stock_price : inv.cost_per_unit));
    if (rate === null) {
      add(hasOverride ? "custom_cost_per_unit" : stockMode ? "pole_stock_price" : "cost_per_unit",
        "pole_price_unavailable", "record a finite, nonnegative pole price before repricing");
    }
    if (stockMode) {
      const stockLengthFt = polePositiveSettingNumber(inv.pole_stock_length_ft, 20);
      if (stockLengthFt === null) {
        add("pole_stock_length_ft", "pole_stock_length_unavailable",
          "the selected catalog stock length must be a recorded finite positive number");
      } else {
        stockLengthInches = stockLengthFt * 12;
      }
    }
    if (pole?.include_pole_painting) {
      widthInches = polePositiveSettingNumber(inv.pole_width_inches, 6);
      if (widthInches === null) {
        add("pole_width_inches", "pole_width_unavailable",
          "the selected catalog pole width must be a recorded finite positive number");
      }
      const paintSetting = (key, label) => {
        const value = poleSettingNumber(settings?.[key], POLE_PAINT_SETTING_DEFAULTS[key]);
        if (value === null) {
          add(key, "pole_paint_setting_unavailable",
            `record a finite, nonnegative ${label} before repricing`);
        }
        return value;
      };
      paint.costPerLf = paintSetting("pole_paint_cost_per_lf", "pole paint cost per LF");
      paint.laborPerLf = paintSetting("pole_paint_labor_per_lf", "pole paint labor per LF");
      paint.sizeMultiplier = paintSetting(polePaintMultiplierKey(widthInches), "pole paint size multiplier");
    }
  }
  return { issues, inv, heightInches, depthInches, rate, stockLengthInches, widthInches, paint };
}

export function foundationPolePricingIssues(pole, inventory = [], index = 0, settings = {}) {
  return polePricing(pole, inventory, index, settings).issues;
}

export function foundationPoleCatalogIssues(poles = [], inventory = [], settings = {}) {
  return (poles || []).flatMap((pole, index) => foundationPolePricingIssues(pole, inventory, index, settings));
}

export function calcPoles(poles = [], inventory = [], settings = {}, options = {}) {
  const explicitSnapshot = options != null && Object.prototype.hasOwnProperty.call(options, "savedPoles");
  const savedPoles = Array.isArray(options?.savedPoles) ? options.savedPoles : [];
  const counts = rows => {
    const out = new Map();
    for (const row of rows) {
      const id = row?.component_id;
      if (assignedId(id)) out.set(id, (out.get(id) || 0) + 1);
    }
    return out;
  };
  const currentCounts = counts(poles), savedCounts = counts(savedPoles);
  const savedById = new Map(savedPoles.filter((row) => assignedId(row?.component_id))
    .map((row) => [row.component_id, row]));
  // Preserve the last saved amounts, not a fabricated free pole. The project
  // availability gate prevents these historical values becoming a new quote.
  const held = pole => {
    const id = pole?.component_id;
    const acknowledged = explicitSnapshot
      ? assignedId(id) && currentCounts.get(id) === 1 && savedCounts.get(id) === 1
        ? savedById.get(id) : null
      : pole;
    const result = { ...pole };
    if (explicitSnapshot) {
      for (const field of ["pole_name", "pole_cost", "pole_painting_cost", "total_cost"]) {
        if (acknowledged && Object.prototype.hasOwnProperty.call(acknowledged, field)) result[field] = acknowledged[field];
        else delete result[field];
      }
    }
    return result;
  };
  const results = (poles || []).map((pole, index) => polePricing(pole, inventory, index, settings));
  return {
    poles: results.map((check, index) => {
      const pole = poles[index];
      if (check.issues.length) return held(pole);
      const { inv, heightInches, depthInches, rate, stockLengthInches, widthInches, paint } = check;
      const totalPoleInches = heightInches + depthInches;
      let poleCost;
      if (inv.pole_pricing_mode === "stock_price") {
        const pieces = Math.ceil(totalPoleInches / stockLengthInches);
        poleCost = pieces * rate;
      } else {
        poleCost = (totalPoleInches / 12) * rate;
      }
      // The guarded path reuses the ported painting math on the normalized
      // calculation copy, so valid inputs price identically to the original.
      const paintingCost = pole?.include_pole_painting
        ? calcPolePaintingCost(
            { include_pole_painting: true, height_inches: heightInches, y_offset_inches: depthInches },
            { ...inv, pole_width_inches: widthInches },
            {
              pole_paint_cost_per_lf: paint.costPerLf,
              pole_paint_labor_per_lf: paint.laborPerLf,
              [polePaintMultiplierKey(widthInches)]: paint.sizeMultiplier,
            })
        : 0;
      return {
        ...pole,
        pole_name: inv.material_name || "",
        pole_cost: poleCost,
        pole_painting_cost: paintingCost,
        total_cost: poleCost + paintingCost,
      };
    }),
    polePricing: results.map((check) => ({ available: check.issues.length === 0, issues: check.issues })),
  };
}

// Ported verbatim from SignEstimate Pro (src/utils/wallCalculator.js).
// Do not re-derive this math — outer wall + optional internal (fill) wall
// brick counts, mortar bags, labor and totals.
//
// Residual-input hardening: a malformed mortar gap, override quantity/rate, or
// wall labor setting is not a free or negative wall — the row is held with its
// acknowledged snapshot amounts and reported instead of silently repricing to
// $0 or producing negative/NaN quantities.

const wallSettingValue = (value, fallback) => value === 0 ? 0 : value || fallback;

export function calcWallCosts({ wall, wallShape, wallMaterial, internalMaterial, includeInternalWall, wallHeightInches, internalWallHeightInches, mortarGapInches, internalMortarGapInches, settings }) {
  if (!wallShape || !wallMaterial || !wallShape.segments) return null;

  const isConcrete = wallMaterial.wall_material_subtype === 'concrete';
  const unitL = wallMaterial.wall_unit_length_inches || 8;
  const unitW = wallMaterial.wall_unit_width_inches || 4;
  const unitH = wallMaterial.wall_unit_height_inches || 2.25;
  const mortar = isConcrete ? 0 : mortarGapInches;
  const courseH = unitH + mortar;
  const numCourses = wallHeightInches / courseH;
  const brickPitch = unitL + (isConcrete ? 0 : mortar);

  const totalLinearInches = wallShape.segments.reduce((s, seg) => s + seg.length, 0);

  const numCoursesRounded = Math.ceil(numCourses);
  let totalBricks = 0;
  wallShape.segments.forEach(seg => {
    const bricksThisCourse = Math.ceil(seg.length / brickPitch);
    totalBricks += bricksThisCourse * numCoursesRounded;
  });

  const finalBricks = wallMaterial.custom_outer_material_qty !== undefined && wallMaterial.custom_outer_material_qty !== null ? wallMaterial.custom_outer_material_qty : totalBricks;
  const materialCost = finalBricks * (wallMaterial.custom_cost_per_unit !== undefined && wallMaterial.custom_cost_per_unit !== null ? wallMaterial.custom_cost_per_unit : (wallMaterial.cost_per_unit || 0));

  const surfaceAreaSqFtSingleSide = (totalLinearInches * wallHeightInches) / 144;

  let mortarCost = 0;
  let mortarBags = 0;
  if (!isConcrete) {
    const surfaceAreaSqFtMortar = surfaceAreaSqFtSingleSide * 2;
    mortarBags = Math.ceil(surfaceAreaSqFtMortar / 30);
    const finalMortarBags = wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags;
    const mortarCostPerBag = parseFloat(wallSettingValue(settings?.wall_mortar_cost_per_bag, 10));
    const finalMortarRate = wallMaterial.custom_outer_mortar_rate !== undefined && wallMaterial.custom_outer_mortar_rate !== null ? wallMaterial.custom_outer_mortar_rate : mortarCostPerBag;
    mortarCost = finalMortarBags * finalMortarRate;
  }

  const laborRatePerSqFt = wallMaterial.custom_outer_labor_rate !== undefined && wallMaterial.custom_outer_labor_rate !== null ? wallMaterial.custom_outer_labor_rate : parseFloat(wallSettingValue(settings?.wall_labor_rate, 45));
  const minCharge = parseFloat(wallSettingValue(settings?.wall_minimum_charge, 150));

  let laborCost = surfaceAreaSqFtSingleSide * laborRatePerSqFt;
  if (laborCost < minCharge) {
    laborCost = minCharge;
  }

  const laborHours = finalBricks / (parseFloat(wallSettingValue(settings?.wall_labor_bricks_per_hour, 50)));

  // --- Internal Wall Calculation ---
  let internalTotalBricks = 0;
  let internalMaterialCost = 0;
  let internalMortarCost = 0;
  let internalLaborCost = 0;
  let internalLaborHours = 0;
  let internalTotalLinearInches = 0;

  if (includeInternalWall && internalMaterial) {
    const intIsConcrete = internalMaterial.wall_material_subtype === 'concrete';
    const intUnitL = internalMaterial.wall_unit_length_inches || 8;
    const intUnitW = internalMaterial.wall_unit_width_inches || 4;
    const intUnitH = internalMaterial.wall_unit_height_inches || 2.25;
    const intMortar = intIsConcrete ? 0 : (internalMortarGapInches ?? 0.375);
    const intCourseH = intUnitH + intMortar;
    const intNumCourses = Math.ceil(internalWallHeightInches / intCourseH);
    const intBrickPitch = intUnitL + intMortar;

    const isClosed = wallShape.closed !== false;
    const lengthReduction = isClosed ? (unitW + intUnitW) : 0;

    wallShape.segments.forEach(seg => {
      const innerSegLength = Math.max(0, seg.length - lengthReduction);
      internalTotalLinearInches += innerSegLength;

      const bricksThisCourse = Math.ceil(innerSegLength / intBrickPitch);
      internalTotalBricks += bricksThisCourse * intNumCourses;
    });

    const finalInternalBricks = wall.custom_internal_material_qty !== undefined && wall.custom_internal_material_qty !== null ? wall.custom_internal_material_qty : internalTotalBricks;
    internalMaterialCost = finalInternalBricks * (wall.custom_internal_material_cost_per_unit !== undefined && wall.custom_internal_material_cost_per_unit !== null ? wall.custom_internal_material_cost_per_unit : (internalMaterial.cost_per_unit || 0));

    const intSurfaceAreaSqFtSingleSide = (internalTotalLinearInches * internalWallHeightInches) / 144;

    let internalMortarBags = 0;
    if (!intIsConcrete) {
      const intSurfaceAreaSqFtMortar = intSurfaceAreaSqFtSingleSide * 2;
      internalMortarBags = Math.ceil(intSurfaceAreaSqFtMortar / 30);
      const finalInternalMortarBags = wall.custom_internal_mortar_qty !== undefined && wall.custom_internal_mortar_qty !== null ? wall.custom_internal_mortar_qty : internalMortarBags;
      const internalMortarCostPerBag = parseFloat(wallSettingValue(settings?.wall_mortar_cost_per_bag, 10));
      const finalInternalMortarRate = wall.custom_internal_mortar_rate !== undefined && wall.custom_internal_mortar_rate !== null ? wall.custom_internal_mortar_rate : internalMortarCostPerBag;
      internalMortarCost = finalInternalMortarBags * finalInternalMortarRate;
    }

    const internalLaborRatePerSqFt = wall.custom_internal_labor_rate !== undefined && wall.custom_internal_labor_rate !== null ? wall.custom_internal_labor_rate : parseFloat(wallSettingValue(settings?.wall_labor_rate, 45));
    internalLaborCost = intSurfaceAreaSqFtSingleSide * internalLaborRatePerSqFt;
    internalLaborHours = finalInternalBricks / (parseFloat(wallSettingValue(settings?.wall_labor_bricks_per_hour, 50)));
  }

  return {
    totalBricks,
    finalBricks,
    materialCost,
    mortarBags,
    finalMortarBags: !isConcrete ? (wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags) : 0,
    mortarCost,
    laborHours,
    laborRatePerSqFt,
    laborCost,
    totalCost: materialCost + mortarCost + laborCost + internalMaterialCost + internalMortarCost + internalLaborCost,
    totalLinearInches,
    numCourses,
    internalTotalBricks,
    internalMaterialCost,
    internalMortarBags: includeInternalWall && internalMaterial && internalMaterial.wall_material_subtype !== 'concrete' ? Math.ceil(((internalTotalLinearInches * internalWallHeightInches) / 144) * 2 / 30) : 0,
    internalMortarCost,
    internalLaborCost,
    internalLaborHours
  };
}

const assignedId = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

function wallPriceNumber(value) {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

function wallDimensionNumber(value) {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
}

// Missing/blank settings fall back to the module default; present values must be
// finite nonnegative numbers (explicit 0 honored — a genuinely free rate).
const wallSettingNumber = (value, fallback) => wallPriceNumber(wallSettingValue(value, fallback));
// Rates that are meaningless at zero (production speed) must be finite positive.
const wallPositiveSettingNumber = (value, fallback) => wallDimensionNumber(wallSettingValue(value, fallback));

// Blank/absent mortar gaps keep the ported 3/8" default; a recorded gap must be
// finite nonnegative — explicit 0 is a legitimate stack-bond joint.
const WALL_MORTAR_GAP_DEFAULT = 0.375;
const wallMortarGapNumber = (value) => value === undefined || value === null || value === ""
  ? WALL_MORTAR_GAP_DEFAULT : wallPriceNumber(value);

const wallRecord = value => !!value && typeof value === "object" && !Array.isArray(value);
const wallPoint = point => wallRecord(point)
  && typeof point.x === "number" && Number.isFinite(point.x)
  && typeof point.z === "number" && Number.isFinite(point.z);

export function foundationWallSegments(points, closed = false) {
  if (!Array.isArray(points) || !points.every(wallPoint) || typeof closed !== "boolean") return null;
  const segments = [];
  const add = (a, b) => segments.push({ length: Math.hypot(b.x - a.x, b.z - a.z) });
  for (let i = 0; i < points.length - 1; i++) add(points[i], points[i + 1]);
  if (closed && points.length > 2) add(points[points.length - 1], points[0]);
  return segments.every(segment => Number.isFinite(segment.length)) ? segments : null;
}

export function foundationWallOutlineBasis(shape) {
  const result = {
    shape: null, points: [], closed: shape?.closed === true,
    hasRecordedPoints: false, perimeterInches: null, issues: [],
  };
  const add = (code, message) => result.issues.push({ code, message });
  const unavailable = () => add("wall_outline_unavailable", "draw an outline with positive segment lengths before repricing");
  if (!wallRecord(shape)) { unavailable(); return result; }
  result.hasRecordedPoints = shape.points != null
    && (!Array.isArray(shape.points) || shape.points.length > 0);
  const validPoints = Array.isArray(shape.points) && shape.points.every(wallPoint);
  if (validPoints) result.points = shape.points.map(point => ({ ...point }));
  if (result.hasRecordedPoints && !validPoints) {
    add("wall_outline_points_unavailable", "repair the recorded footprint coordinates before repricing");
  }
  if ((shape.closed != null || result.hasRecordedPoints) && typeof shape.closed !== "boolean") {
    add("wall_outline_closure_unavailable", "record whether the outline is open or closed before repricing");
  }
  let segments = null;
  if (!Array.isArray(shape.segments) || !shape.segments.length) {
    unavailable();
  } else {
    const lengths = shape.segments.map(segment => wallRecord(segment) ? wallDimensionNumber(segment.length) : null);
    if (lengths.some(length => length === null)) {
      add("wall_outline_segment_unavailable", "record positive, finite segment lengths in inches before repricing");
    } else {
      segments = shape.segments.map((segment, index) => ({ ...segment, length: lengths[index] }));
      if (!Number.isFinite(lengths.reduce((sum, length) => sum + length, 0))) {
        add("wall_outline_length_unavailable", "record a finite outline perimeter before repricing");
      }
    }
  }
  if (segments && result.hasRecordedPoints && validPoints && typeof shape.closed === "boolean") {
    const expected = foundationWallSegments(result.points, shape.closed);
    const same = result.points.length >= (shape.closed ? 3 : 2)
      && expected && expected.length === segments.length && expected.every((segment, index) => {
        const stored = segments[index].length;
        const tolerance = Number.EPSILON * 8 * Math.max(1, segment.length, stored);
        return segment.length > 0 && Math.abs(segment.length - stored) <= tolerance;
      });
    if (!same) add("wall_outline_geometry_mismatch", "repair footprint points and segment lengths so they describe the same outline before repricing");
  }
  if (!result.issues.length) {
    result.shape = { ...shape, segments };
    if (validPoints) result.shape.points = result.points;
    result.perimeterInches = segments.reduce((sum, segment) => sum + segment.length, 0);
  }
  return result;
}

export function foundationWallRectangle(length, width) {
  const l = wallDimensionNumber(length), w = wallDimensionNumber(width);
  if (l === null || w === null) return null;
  const points = [{ x: 0, z: 0 }, { x: l, z: 0 }, { x: l, z: w }, { x: 0, z: w }];
  return foundationWallOutlineBasis({ points, closed: true, segments: foundationWallSegments(points, true) }).shape;
}

const WALL_SETTING_DEFAULTS = {
  wall_mortar_cost_per_bag: 10,
  wall_labor_rate: 45,
  wall_minimum_charge: 150,
  wall_labor_bricks_per_hour: 50,
};
const WALL_OUTER_OVERRIDE_FIELDS = [
  ["custom_outer_material_qty", "material quantity"],
  ["custom_outer_labor_rate", "labor rate"],
];
const WALL_OUTER_MORTAR_OVERRIDE_FIELDS = [
  ["custom_outer_mortar_qty", "mortar quantity"],
  ["custom_outer_mortar_rate", "mortar rate"],
];
const WALL_INTERNAL_OVERRIDE_FIELDS = [
  ["custom_internal_material_qty", "material quantity"],
  ["custom_internal_labor_rate", "labor rate"],
];
const WALL_INTERNAL_MORTAR_OVERRIDE_FIELDS = [
  ["custom_internal_mortar_qty", "mortar quantity"],
  ["custom_internal_mortar_rate", "mortar rate"],
];

function wallPricing(wall, inventory = [], index = 0, settings = {}) {
  const issues = [];
  const heightInches = wallDimensionNumber(wall?.heightInches);
  const internalWallHeightInches = wall?.includeInternalWall
    ? wallDimensionNumber(wall.internalWallHeightInches ?? wall.heightInches) : null;
  const heightIssue = (field, kind, label, code) => issues.push({
    kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
    field, inventoryId: wall?.[kind === "wall" ? "materialId" : "internalMaterialId"] ?? null, code,
    message: `${label} ${index + 1}: record a positive, finite wall height in inches before repricing.`,
  });
  if (heightInches === null) heightIssue("heightInches", "wall", "Wall", "wall_height_unavailable");
  if (wall?.includeInternalWall && internalWallHeightInches === null) {
    heightIssue("internalWallHeightInches", "internal_wall", "Internal wall", "internal_wall_height_unavailable");
  }
  const outline = foundationWallOutlineBasis(wall?.shape);
  issues.push(...outline.issues.map(issue => ({
    ...issue, kind: "wall", index, componentId: wall?.component_id ?? wall?.id ?? null,
    field: "shape", inventoryId: wall?.materialId ?? null,
    message: `Wall ${index + 1}: ${issue.message}.`,
  })));
  const check = (field, kind, label) => {
    const id = wall?.[field];
    const add = (code, message) => issues.push({
      kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
      field, inventoryId: assignedId(id) ? id : null, code,
      message: `${label} ${index + 1}: ${message}.`,
    });
    if (!assignedId(id)) {
      add("catalog_item_unassigned", "select a catalog material");
      return null;
    }
    const matches = inventory.filter(row => row?.id === id);
    if (!matches.length) {
      add("catalog_item_unavailable", "selected catalog material is unavailable");
      return null;
    }
    if (matches.length !== 1) {
      add("catalog_item_ambiguous", "selected catalog material is ambiguous");
      return null;
    }
    const material = matches[0];
    if (!["brick_stone", "wall_material"].includes(material.material_type)) {
      add("catalog_item_type_mismatch", "selected catalog material is not a wall material");
      return null;
    }
    const override = kind === "wall"
      ? material.custom_cost_per_unit
      : wall.custom_internal_material_cost_per_unit;
    const price = override !== undefined && override !== null ? override : material.cost_per_unit;
    if (wallPriceNumber(price) === null) {
      add("wall_material_price_unavailable", "record a finite, nonnegative material unit price before repricing");
    }
    const normalizedMaterial = { ...material };
    for (const [key, label] of [
      ["wall_unit_length_inches", "unit length"],
      ["wall_unit_width_inches", "unit width"],
      ["wall_unit_height_inches", "unit height"],
    ]) {
      const dimension = wallDimensionNumber(material[key]);
      if (dimension === null) {
        add(key + "_unavailable", `record a positive, finite ${label} in inches before repricing`);
      } else {
        normalizedMaterial[key] = dimension;
      }
    }
    return normalizedMaterial;
  };
  const wallMaterial = check("materialId", "wall", "Wall");
  const internalMaterial = wall?.includeInternalWall
    ? check("internalMaterialId", "internal_wall", "Internal wall")
    : null;

  // Residual-input checks mirror the pole unit: only values the ported math
  // actually consumes are validated, each on a normalized calculation copy —
  // authored rows and settings are never mutated. An explicit 0 override or
  // mortar gap is legitimate; negatives/malformed values hold the wall.
  const add = (kind, field, inventoryId, code, message) => issues.push({
    kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
    field, inventoryId: inventoryId ?? null, code,
    message: `${kind === "internal_wall" ? "Internal wall" : "Wall"} ${index + 1}: ${message}.`,
  });
  const overrideCheck = (source, fields, kind, inventoryId) => {
    for (const [field, label] of fields) {
      const raw = source?.[field];
      if (raw === undefined || raw === null) continue;
      const value = wallPriceNumber(raw);
      if (value === null) {
        add(kind, field, inventoryId, field + "_unavailable",
          `record a finite, nonnegative ${label} override or clear it before repricing`);
      } else {
        source[field] = value;
      }
    }
  };
  const settingCheck = (key, label, positive) => {
    const value = positive
      ? wallPositiveSettingNumber(settings?.[key], WALL_SETTING_DEFAULTS[key])
      : wallSettingNumber(settings?.[key], WALL_SETTING_DEFAULTS[key]);
    if (value === null) {
      add("wall", key, wall?.materialId, "wall_setting_unavailable",
        `record a finite, ${positive ? "positive" : "nonnegative"} ${label} in Estimator Settings before repricing`);
    }
    return value;
  };
  const outerConcrete = wallMaterial?.wall_material_subtype === "concrete";
  const intConcrete = internalMaterial?.wall_material_subtype === "concrete";
  const calcWall = wall?.includeInternalWall && internalMaterial ? { ...wall } : wall;
  let mortarGapInches = WALL_MORTAR_GAP_DEFAULT;
  let internalMortarGapInches = WALL_MORTAR_GAP_DEFAULT;
  if (wallMaterial) {
    overrideCheck(wallMaterial, WALL_OUTER_OVERRIDE_FIELDS, "wall", wall?.materialId);
    settingCheck("wall_labor_rate", "wall labor rate");
    settingCheck("wall_minimum_charge", "wall minimum labor charge");
    settingCheck("wall_labor_bricks_per_hour", "wall production rate", true);
    if (!outerConcrete) {
      mortarGapInches = wallMortarGapNumber(wall?.mortarGapInches);
      if (mortarGapInches === null) {
        add("wall", "mortarGapInches", wall?.materialId, "wall_mortar_gap_unavailable",
          "record a finite, nonnegative mortar gap in inches before repricing");
      }
      overrideCheck(wallMaterial, WALL_OUTER_MORTAR_OVERRIDE_FIELDS, "wall", wall?.materialId);
    }
  }
  if (wall?.includeInternalWall && internalMaterial) {
    overrideCheck(calcWall, WALL_INTERNAL_OVERRIDE_FIELDS, "internal_wall", wall?.internalMaterialId);
    if (!intConcrete) {
      internalMortarGapInches = wallMortarGapNumber(wall?.internalMortarGapInches);
      if (internalMortarGapInches === null) {
        add("internal_wall", "internalMortarGapInches", wall?.internalMaterialId, "internal_wall_mortar_gap_unavailable",
          "record a finite, nonnegative mortar gap in inches before repricing");
      }
      overrideCheck(calcWall, WALL_INTERNAL_MORTAR_OVERRIDE_FIELDS, "internal_wall", wall?.internalMaterialId);
    }
  }
  if ((wallMaterial && !outerConcrete) || (internalMaterial && !intConcrete)) {
    settingCheck("wall_mortar_cost_per_bag", "mortar cost per bag");
  }

  return {
    issues, wallMaterial, internalMaterial, heightInches, internalWallHeightInches,
    wallShape: outline.shape, calcWall, mortarGapInches, internalMortarGapInches,
  };
}

export function foundationWallPricingIssues(wall, inventory = [], index = 0, settings = {}) {
  return wallPricing(wall, inventory, index, settings).issues;
}

export function foundationWallCatalogIssues(walls = [], inventory = [], settings = {}) {
  return walls.flatMap((wall, index) => foundationWallPricingIssues(wall, inventory, index, settings));
}

export function foundationWallBomRows(walls = [], inventory = [], wallPricing) {
  const out = [];
  const known = value => typeof value === "number" && Number.isFinite(value);
  const quantity = value => known(value)
    ? `${value.toLocaleString(undefined, { maximumFractionDigits: 2 })} units` : "Not saved";
  const amount = value => known(value) ? value : "Not saved";
  const used = (qty, cost) => (known(qty) && qty > 0) || (known(cost) && cost !== 0);
  walls.forEach((wall, index) => {
    const costs = wall.calculatedCosts || {};
    const label = wall.name || `Wall ${index + 1}`;
    const saved = Array.isArray(wallPricing) && wallPricing[index]
      ? wallPricing[index].available === false
      : foundationWallPricingIssues(wall, inventory, index).length > 0;
    const nameOf = id => inventory.find(row => row.id === id)?.material_name || "Material";
    const add = (material, qty, cost) => out.push({ material, quantity: qty, cost: amount(cost), saved });
    if (saved || used(costs.totalBricks, costs.materialCost)) {
      add(saved ? `${label} — saved outer material` : `${label} — ${nameOf(wall.materialId)}`,
        quantity(costs.totalBricks), costs.materialCost);
    }
    if (known(costs.mortarCost) && costs.mortarCost !== 0) {
      add(`${label} — ${saved ? "saved mortar" : "mortar"}`, "—", costs.mortarCost);
    }
    const internalUsed = used(costs.internalTotalBricks, costs.internalMaterialCost);
    if ((saved && wall.includeInternalWall) || internalUsed) {
      add(saved ? `${label} — saved internal material` : `${label} — ${nameOf(wall.internalMaterialId)} (internal)`,
        quantity(costs.internalTotalBricks), costs.internalMaterialCost);
    }
    if (known(costs.internalMortarCost) && costs.internalMortarCost !== 0) {
      add(`${label} — ${saved ? "saved internal mortar" : "internal mortar"}`, "—", costs.internalMortarCost);
    }
  });
  return out;
}

// Runs the legacy wall math only when the selected material basis is available.
export function calcWalls(project, inventory, settings = {}, options = {}) {
  const walls = project.walls || [];
  const explicitSnapshot = options != null && Object.prototype.hasOwnProperty.call(options, "savedWalls");
  const savedWalls = Array.isArray(options?.savedWalls) ? options.savedWalls : [];
  const counts = rows => {
    const out = new Map();
    for (const row of rows) {
      const id = row?.component_id;
      if (assignedId(id)) out.set(id, (out.get(id) || 0) + 1);
    }
    return out;
  };
  const currentCounts = counts(walls), savedCounts = counts(savedWalls);
  const savedById = new Map(savedWalls.filter(row => assignedId(row?.component_id))
    .map(row => [row.component_id, row]));
  const held = wall => {
    const id = wall?.component_id;
    const acknowledged = explicitSnapshot
      ? assignedId(id) && currentCounts.get(id) === 1 && savedCounts.get(id) === 1
        ? savedById.get(id) : null
      : wall;
    const costs = acknowledged?.calculatedCosts;
    return {
      ...wall,
      calculatedCosts: costs && typeof costs === "object" && !Array.isArray(costs) ? { ...costs } : {},
    };
  };
  const results = walls.map((wall, index) => wallPricing(wall, inventory, index, settings));
  return {
    walls: results.map((check, index) => {
      const wall = walls[index];
      if (check.issues.length) return held(wall);
      const { wallMaterial, internalMaterial, heightInches, internalWallHeightInches, wallShape,
        calcWall, mortarGapInches, internalMortarGapInches } = check;
      const costs =
        calcWallCosts({
          wall: calcWall ?? wall,
          wallShape,
          wallMaterial,
          internalMaterial,
          includeInternalWall: wall.includeInternalWall,
          wallHeightInches: heightInches,
          internalWallHeightInches,
          mortarGapInches,
          internalMortarGapInches,
          settings,
        }) || {};
      return {
        ...wall,
        calculatedCosts: {
          // ?? keeps an accidental NaN visible instead of laundering it to $0.
          totalBricks: costs.finalBricks ?? 0,
          materialCost: costs.materialCost ?? 0,
          mortarCost: costs.mortarCost ?? 0,
          laborHours: costs.laborHours ?? 0,
          laborCost: costs.laborCost ?? 0,
          totalCost: costs.totalCost ?? 0,
          totalLinearInches: costs.totalLinearInches ?? 0,
          numCourses: costs.numCourses ?? 0,
          internalTotalBricks: costs.internalTotalBricks ?? 0,
          internalMaterialCost: costs.internalMaterialCost ?? 0,
          internalMortarCost: costs.internalMortarCost ?? 0,
          internalLaborCost: costs.internalLaborCost ?? 0,
          internalLaborHours: costs.internalLaborHours ?? 0,
        },
      };
    }),
    wallPricing: results.map((check) => ({ available: check.issues.length === 0, issues: check.issues })),
  };
}

// Wall cap pricing - ported from SignEstimate Pro (WallCapsTab.jsx).
// A cut cap piece is always charged at FULL stock price; cuts do not reduce price.
export const wallCapInputNumber = value => {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string" || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim())) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};
export function wallCapCutLengthValue(cap) {
  if (!cap || typeof cap !== "object" || Array.isArray(cap)) return undefined;
  // Do not replace an explicitly cleared current cut with an old legacy value.
  return Object.prototype.hasOwnProperty.call(cap, "length_inches") ? cap.length_inches : cap.cut_length_inches;
}
const known = value => typeof value === "number" && Number.isFinite(value);
const assigned = id => (typeof id === "string" && id.trim() !== "")
  || (typeof id === "number" && Number.isFinite(id));
const sumKnown = rows => {
  let total = 0;
  for (const row of rows) {
    if (!known(row.cost)) return null;
    total += row.cost;
    if (!Number.isFinite(total)) return null;
  }
  return total;
};

export function calcWallCaps(wallCaps = [], inventory = [], options = {}) {
  const issues = [];
  const explicitSnapshot = Object.prototype.hasOwnProperty.call(options ?? {}, "savedCaps");
  const currentIds = new Map();
  const savedCaps = new Map();
  const componentId = cap => typeof cap?.component_id === "string" && cap.component_id.trim() !== ""
    ? cap.component_id : null;
  if (explicitSnapshot) {
    for (const cap of wallCaps || []) {
      const id = componentId(cap);
      if (id !== null) currentIds.set(id, (currentIds.get(id) || 0) + 1);
    }
    for (const cap of Array.isArray(options.savedCaps) ? options.savedCaps : []) {
      const id = componentId(cap);
      if (id !== null) savedCaps.set(id, savedCaps.has(id) ? null : cap);
    }
  }
  // Edited rows can contain preview prices; they are not acknowledged history.
  const held = cap => {
    const result = { ...cap };
    if (!explicitSnapshot) return result;
    const id = componentId(cap);
    const saved = id !== null && currentIds.get(id) === 1 ? savedCaps.get(id) : null;
    for (const field of ["cost", "cap_name", "stock_length_inches"]) {
      if (saved && Object.prototype.hasOwnProperty.call(saved, field)) result[field] = saved[field];
      else delete result[field];
    }
    return result;
  };
  const caps = (wallCaps || []).map((cap, index) => {
    const id = cap.cap_inventory_id;
    const issue = (field, code, message) => issues.push({
      kind: "wall_cap", index, componentId: cap.component_id ?? cap.id ?? null,
      field, inventoryId: assigned(id) ? id : null, code,
      message: `Wall cap ${index + 1}: ${message}`,
    });
    const matches = assigned(id) ? inventory.filter(row => row?.id === id) : [];
    if (matches.length !== 1) {
      issue("cap_inventory_id", !assigned(id) ? "catalog_item_unassigned"
        : matches.length > 1 ? "catalog_item_ambiguous" : "catalog_item_unavailable",
      !assigned(id) ? "select a catalog material." : matches.length > 1
        ? "the selected catalog ID is ambiguous; refresh the catalog." : "selected catalog material is unavailable.");
      return held(cap);
    }
    const inv = matches[0];
    if (inv.material_type !== "wall_cap") {
      issue("cap_inventory_id", "catalog_item_type_mismatch", "the selected catalog material is not a wall cap.");
      return held(cap);
    }
    const firstIssue = issues.length;
    const rate = wallCapInputNumber(inv.cap_stock_price);
    if (rate === null || rate < 0) {
      issue("cap_stock_price", "wall_cap_stock_price_unavailable",
        "record a finite nonnegative full-stock price; a missing price is not zero. Saved amounts are retained.");
    }
    const stockLength = wallCapInputNumber(inv.cap_stock_length_inches);
    const cutLength = wallCapInputNumber(wallCapCutLengthValue(cap));
    if (stockLength === null || stockLength <= 0) {
      issue("cap_stock_length_inches", "wall_cap_stock_length_unavailable",
        "the selected catalog stock length must be a recorded finite positive number. Saved dimensions are not a current stock specification.");
    }
    if (cutLength === null || cutLength <= 0) {
      issue("length_inches", "wall_cap_cut_length_invalid",
        "enter a finite positive cut length in inches. An empty or invalid cut is not changed to a default size.");
    } else if (stockLength !== null && stockLength > 0 && cutLength > stockLength) {
      issue("length_inches", "wall_cap_cut_exceeds_stock",
        `cut length (${cutLength} in) exceeds the selected stock length (${stockLength} in). Choose longer stock or separate pieces; no extra quantity is assumed.`);
    }
    if (issues.length !== firstIssue) return held(cap);
    return {
      ...cap,
      cap_name: inv.material_name || "",
      stock_length_inches: stockLength,
      cost: rate,
    };
  });

  const groups = new Map();
  for (const cap of caps) {
    if (!assigned(cap.cap_inventory_id)) continue;
    if (!groups.has(cap.cap_inventory_id)) groups.set(cap.cap_inventory_id, []);
    groups.get(cap.cap_inventory_id).push(cap);
  }
  const byInventory = [...groups].map(([id, rows]) => ({
    id, name: rows[0].cap_name, qty: rows.length, cost: sumKnown(rows),
  }));
  const total = sumKnown(caps);
  if (total === null && caps.every(cap => known(cap.cost))) {
    issues.push({
      kind: "wall_cap", index: 0, componentId: caps[0]?.component_id ?? caps[0]?.id ?? null,
      field: "cost", inventoryId: null, code: "wall_cap_cost_total_invalid",
      message: "Wall cap total is outside the supported numeric range; current pricing is unavailable.",
    });
  }
  return { caps, byInventory, total, issues };
}

export function foundationWallCapCatalogIssues(wallCaps = [], inventory = []) {
  return calcWallCaps(wallCaps, inventory).issues;
}

// Pure calculation helpers for Sign Maintenance estimates.
// Mirrors components/channelLetterInstall/installCalculator structurally but
// is driven by the MaintenanceActionRate matrix (sign_type × action × size).

import { sizeAxisFor } from "./constants";
import { computeMonumentRepaint, isMonumentRepaint } from "./repaintCalculator";

const MIN_TO_HR = 1 / 60;

// Map a size id to the MaintenanceActionRate field that stores its minutes.
const SIZE_TO_FIELD = {
  extra_small: "base_minutes_xs",
  small: "base_minutes_s",
  medium: "base_minutes_m",
  large: "base_minutes_l",
  extra_large: "base_minutes_xl",
  extra_extra_large: "base_minutes_xxl",
  cab_small: "base_minutes_cab_s",
  cab_medium: "base_minutes_cab_m",
  cab_large: "base_minutes_cab_l",
  cab_extra_large: "base_minutes_cab_xl",
};

export const emptyServiceItem = () => ({
  description: "",
  sign_type: "flush_channel",
  size: "medium",
  qty: 10,
  installation_height_feet: 12,
  actions: [],   // array of action ids
  materials: [], // array of {inventory_item_id, item_name, quantity, unit_cost, total_cost}
});

// Look up the MaintenanceActionRate row for (sign_type, action) and return base minutes for the chosen size.
const minutesForActionOnSize = (rates, signType, action, size) => {
  const rate = (rates || []).find(r => r.sign_type === signType && r.action === action);
  if (!rate) return 0;
  // Honor the per-sign-type enable toggle. Disabled rate rows contribute 0 minutes.
  if (rate.is_enabled === false) return 0;
  const field = SIZE_TO_FIELD[size];
  if (!field) return parseFloat(rate.base_minutes_flat) || 0;
  return parseFloat(rate[field]) || 0;
};

// Calc one service item: total labor hours + cost for ALL actions performed on it.
export const calcServiceItem = (item, settings, rates, inventory) => {
  const techRate = parseFloat(settings.maintenance_tech_rate) || 65;
  const axis = sizeAxisFor(item.sign_type);
  const qty = parseFloat(item.qty) || 0;

  let totalMinutes = 0;
  (item.actions || []).forEach(actionId => {
    // Monument repaint has its own specialized estimator — skip the rate-matrix
    // contribution for that single action, we add it below.
    if (actionId === "repaint" && isMonumentRepaint(item)) return;
    const perUnit = minutesForActionOnSize(rates, item.sign_type, actionId, item.size);
    // For cabinet axis, qty acts as # cabinets; for letter axis, qty acts as # letters.
    totalMinutes += perUnit * (axis === "cabinet" ? Math.max(qty, 1) : qty);
  });

  let laborHours = totalMinutes * MIN_TO_HR;

  // Specialized contribution: Monument Sign repaint
  let repaintPaintCost = 0;
  const repaint = computeMonumentRepaint(item, settings);
  if (repaint) {
    laborHours += repaint.labor_hours;
    repaintPaintCost = repaint.paint_material_cost;
  }

  const laborCost = laborHours * techRate;

  // Recompute materials based on current item state.
  const materials = (item.materials || []).map(m => {
    const inv = (inventory || []).find(i => i.id === (m.maintenance_rule_id || m.inventory_item_id));
    if (!inv) return { ...m, total_cost: (parseFloat(m.unit_cost) || 0) * (parseFloat(m.quantity) || 0) };
    return materialFromInventory(inv, item, m);
  });
  const materialsCost = materials.reduce((s, m) => s + (parseFloat(m.total_cost) || 0), 0) + repaintPaintCost;

  return {
    ...item,
    materials,
    labor_hours: laborHours,
    labor_cost: laborCost,
    materials_cost: materialsCost,
    repaint_calc: repaint || undefined,
    item_total_cost: laborCost + materialsCost,
  };
};

const usageBasisQuantity = (item, basis) => {
  if (basis === "per_letter") return parseFloat(item.qty) || 0;
  if (basis === "per_cabinet") return Math.max(parseFloat(item.qty) || 0, 1);
  if (basis === "per_linear_foot") return parseFloat(item.linear_feet) || 0;
  if (basis === "per_sqft") return parseFloat(item.face_sqft) || 0;
  return 1;
};

export const materialFromInventory = (inv, item, existing = null) => {
  const linked = !!(inv.inventory_entity && inv.inventory_item_id);
  if (linked) {
    const basis = inv.usage_basis || "per_service_item";
    const multiplier = Math.max(0, parseFloat(inv.usage_multiplier) || 0);
    const rawQuantity = usageBasisQuantity(item, basis) * multiplier;
    const autoQuantity = inv.usage_rounding === "ceil_whole" ? Math.ceil(rawQuantity) : rawQuantity;
    const quantity = existing?.quantity_override ? Math.max(0, parseFloat(existing.quantity) || 0) : autoQuantity;
    const unitCost = Number.isFinite(Number(inv._master_unit_cost))
      ? Number(inv._master_unit_cost)
      : parseFloat(existing?.unit_cost) || 0;
    return {
      ...(existing || {}),
      maintenance_rule_id: inv.id,
      inventory_entity: inv.inventory_entity,
      inventory_item_id: inv.inventory_item_id,
      inventory_item_name: inv.inventory_item_name || inv._display_name || inv.item_name,
      item_name: inv._display_name || inv.inventory_item_name || inv.item_name,
      pricing_mode: inv._master_pricing_mode || existing?.pricing_mode || inv.pricing_mode,
      usage_basis: basis,
      usage_multiplier: multiplier,
      usage_rounding: inv.usage_rounding || "none",
      unit: inv._master_unit || existing?.unit || inv.unit || "unit",
      unit_cost: unitCost,
      auto_quantity: autoQuantity,
      quantity,
      quantity_override: !!existing?.quantity_override,
      link_missing: !!inv._master_missing,
      total_cost: unitCost * quantity,
    };
  }

  const m = {
    ...(existing || {}),
    maintenance_rule_id: inv.id,
    inventory_item_id: inv.id,
    item_name: inv.item_name,
    pricing_mode: inv.pricing_mode,
    unit: inv.unit || inv.pricing_mode || "unit",
    unit_cost: 0, quantity: 0, total_cost: 0,
  };
  const sizeKey = `cost_${item.size}`;
  if (inv.pricing_mode === "per_letter_flat") {
    m.unit_cost = parseFloat(inv.cost_per_letter) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_letter_by_size" || inv.pricing_mode === "per_cabinet_by_size") {
    m.unit_cost = parseFloat(inv[sizeKey]) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_cabinet_flat") {
    m.unit_cost = parseFloat(inv.cost_per_cabinet) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_linear_foot") {
    m.unit_cost = parseFloat(inv.cost_per_foot) || 0;
    m.quantity = parseFloat(item.linear_feet) || 0;
  } else if (inv.pricing_mode === "per_sqft") {
    m.unit_cost = parseFloat(inv.cost_per_sqft) || 0;
    m.quantity = parseFloat(item.face_sqft) || 0;
  } else if (inv.pricing_mode === "per_project_flat") {
    m.unit_cost = parseFloat(inv.cost_flat) || 0;
    m.quantity = 1;
  }
  if (existing?.quantity_override) m.quantity = Math.max(0, parseFloat(existing.quantity) || 0);
  m.quantity_override = !!existing?.quantity_override;
  m.auto_quantity = m.quantity;
  m.total_cost = m.unit_cost * m.quantity;
  return m;
};

// Pull default materials for a service item based on multi-axis tagging.
export const defaultMaterialsForItem = (item, inventory) => {
  return (inventory || [])
    .filter(inv => {
      if (inv.is_active === false || !inv.is_default || inv._master_missing) return false;
      const types = inv.applies_to_item_types || [];
      const sizes = inv.applies_to_sizes || [];
      const actions = inv.applies_to_actions || [];
      if (types.length > 0 && !types.includes(item.sign_type)) return false;
      if (sizes.length > 0 && !sizes.includes(item.size)) return false;
      if (actions.length > 0) {
        const itemActions = item.actions || [];
        // Only attach if at least one of this material's actions is being performed.
        if (!actions.some(a => itemActions.includes(a))) return false;
      }
      return true;
    })
    .map(inv => materialFromInventory(inv, item));
};

// Project rollup
export const calcProjectTotals = (project) => {
  const items = project.items || [];
  const total_materials_cost = items.reduce((s, it) => s + (parseFloat(it.materials_cost) || 0), 0);
  const labor_cost = items.reduce((s, it) => s + (parseFloat(it.labor_cost) || 0), 0);
  const labor_hours = items.reduce((s, it) => s + (parseFloat(it.labor_hours) || 0), 0);

  const total_equipment_cost = (project.selected_equipment || []).reduce((s, e) => s + (parseFloat(e.total_cost) || 0), 0);
  const total_personnel_cost = (project.personnel || []).reduce((s, p) => s + (parseFloat(p.total_cost) || 0), 0);

  const pct = parseFloat(project.supplies_percent_of_materials);
  const suppliesPct = isNaN(pct) ? 10 : pct;
  const extra = parseFloat(project.extra_supplies_cost) || 0;
  const total_supplies_cost = total_materials_cost * (suppliesPct / 100) + extra;

  const total_travel_cost = parseFloat(project.total_travel_cost) || 0;

  const subtotal = labor_cost + total_materials_cost + total_supplies_cost + total_equipment_cost + total_personnel_cost + total_travel_cost;
  const markupPct = parseFloat(project.markup_percent) || 0;
  const markup_amount = subtotal * (markupPct / 100);
  const total_cost = subtotal + markup_amount;

  return {
    labor_hours, labor_cost, total_materials_cost, total_supplies_cost,
    total_equipment_cost, total_personnel_cost, total_travel_cost,
    subtotal, markup_amount, total_cost,
  };
};

// Pure helpers for the Repaint action.
// Given an item's repaint_config + the Settings entity, compute:
//   - paintable square footage (face + retainers/returns based on mode)
//   - feature & condition multipliers
//   - estimated paint quantity (gallons) and paint material cost
//   - prep+paint labor hours (sqft / sqft-per-hour, multiplied by feature & condition)
//
// Returns null when the item is not a monument-sign repaint with a config.

import {
  REPAINT_FEATURES, PAINT_CONDITION_LABELS,
} from "./repaintDefaults";
import { computeDimLetterPaint } from "./dimLetterPaintCalculator";

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// Default fallbacks (mirror REPAINT_DEFAULTS) so calc still works if settings haven't been written yet.
const SETTING_FALLBACKS = {
  maintenance_repaint_coverage_sqft_per_gallon: 350,
  maintenance_repaint_paint_cost_per_gallon: 55,
  maintenance_repaint_primer_coats: 1,
  maintenance_repaint_finish_coats: 2,
  maintenance_repaint_sqft_per_hour: 60,
  maintenance_repaint_feat_dimensional_letters: 1.35,
  maintenance_repaint_feat_painted_letters: 1.25,
  maintenance_repaint_feat_applied_vinyl: 1.15,
  maintenance_repaint_feat_complex_layering: 1.40,
  maintenance_repaint_condition_step_pct: 8,
};

const settingNum = (settings, key) => num(settings?.[key], SETTING_FALLBACKS[key]);

export const isMonumentRepaint = (item) => {
  if (!item) return false;
  if (item.sign_type !== "monument_sign") return false;
  return (item.actions || []).includes("repaint");
};

// Default config seeded onto a service item the first time monument + repaint
// is selected.
export const defaultMonumentRepaintConfig = () => ({
  length_ft: 8,
  height_ft: 4,
  return_depth_in: 6,
  paint_mode: "entire_panel",  // "entire_panel" | "returns_only"
  features: [],                // ids from REPAINT_FEATURES (only used when entire_panel)
  retainer_width_in: 2,        // only used when returns_only
  paint_condition: 3,          // 1-10
  paint_both_sides: true,      // monument typically has 2 painted faces
  // Dimensional-letter painting — only relevant when "dimensional_letters" feature is on
  dim_letter_paint: {
    enabled: false,
    qty: 6,
    avg_height_in: 12,
    thickness_in: 1,
    second_color_mask: "none", // "none" | "paint_mask"
  },
});

// SQFT computation. Length/Height in feet, return_depth in inches.
// Mode "entire_panel"  → face area × (1 or 2 sides) + perimeter band of returns
//                       (perimeter × return_depth converted to ft)
// Mode "returns_only"  → perimeter × retainer_width converted to ft
export const computeRepaintSqft = (cfg) => {
  if (!cfg) return { face_sqft: 0, returns_sqft: 0, total_sqft: 0, perimeter_ft: 0 };
  const L = Math.max(0, num(cfg.length_ft));
  const H = Math.max(0, num(cfg.height_ft));
  const perimeter_ft = 2 * (L + H);
  const sides = cfg.paint_both_sides ? 2 : 1;

  if (cfg.paint_mode === "returns_only") {
    const retainerFt = Math.max(0, num(cfg.retainer_width_in)) / 12;
    const returns_sqft = perimeter_ft * retainerFt;
    return { face_sqft: 0, returns_sqft, total_sqft: returns_sqft, perimeter_ft };
  }

  // entire_panel
  const face_sqft = L * H * sides;
  const returnDepthFt = Math.max(0, num(cfg.return_depth_in)) / 12;
  const returns_sqft = perimeter_ft * returnDepthFt;
  return { face_sqft, returns_sqft, total_sqft: face_sqft + returns_sqft, perimeter_ft };
};

// Feature multiplier — multiplicative across features when paint_mode = entire_panel.
export const featureMultiplier = (cfg, settings) => {
  if (!cfg || cfg.paint_mode !== "entire_panel") return 1;
  const selected = new Set(cfg.features || []);
  let mult = 1;
  REPAINT_FEATURES.forEach(f => {
    if (selected.has(f.id)) mult *= settingNum(settings, f.setting);
  });
  return mult;
};

// Condition multiplier — 1 + step% × (level - 1), clamped at level 1..10.
export const conditionMultiplier = (cfg, settings) => {
  const level = Math.min(10, Math.max(1, Math.round(num(cfg?.paint_condition, 1))));
  const stepPct = settingNum(settings, "maintenance_repaint_condition_step_pct");
  return 1 + (stepPct / 100) * (level - 1);
};

// Master compute. Returns null if item isn't a monument repaint.
export const computeMonumentRepaint = (item, settings) => {
  if (!isMonumentRepaint(item)) return null;
  const cfg = item.repaint_config || defaultMonumentRepaintConfig();
  const { face_sqft, returns_sqft, total_sqft, perimeter_ft } = computeRepaintSqft(cfg);

  const coverage = settingNum(settings, "maintenance_repaint_coverage_sqft_per_gallon") || 350;
  const pricePerGal = settingNum(settings, "maintenance_repaint_paint_cost_per_gallon");
  const primerCoats = Math.max(0, settingNum(settings, "maintenance_repaint_primer_coats"));
  const finishCoats = Math.max(0, settingNum(settings, "maintenance_repaint_finish_coats"));
  const sqftPerHour = settingNum(settings, "maintenance_repaint_sqft_per_hour") || 60;

  const totalCoats = primerCoats + finishCoats;
  const paintedSqft = total_sqft * totalCoats;
  const gallons = paintedSqft / coverage;
  const paintMaterialCost = gallons * pricePerGal;

  const featMult = featureMultiplier(cfg, settings);
  const condMult = conditionMultiplier(cfg, settings);
  let labor_hours = (total_sqft / sqftPerHour) * featMult * condMult;

  // Add Painted Dimensional Letters (Paint Estimator rates) when enabled
  const featureSet = new Set(cfg.features || []);
  const dl = (featureSet.has("dimensional_letters") && cfg.paint_mode === "entire_panel")
    ? computeDimLetterPaint(cfg, settings)
    : null;
  let dimLetterCost = 0;
  if (dl) {
    dimLetterCost = dl.letters_total_added_cost;
    labor_hours += (dl.letters_labor_hours || 0) + (dl.mask_labor_hours || 0);
  }

  return {
    cfg,
    face_sqft, returns_sqft, total_sqft, perimeter_ft,
    coverage, pricePerGal, primerCoats, finishCoats, totalCoats,
    gallons,
    paint_material_cost: paintMaterialCost + dimLetterCost,
    feature_multiplier: featMult,
    condition_multiplier: condMult,
    paint_condition_label: PAINT_CONDITION_LABELS[Math.min(9, Math.max(0, (cfg.paint_condition || 1) - 1))],
    labor_hours,
    dim_letter_paint: dl,
  };
};

// Adds Painted Dimensional Letters on top of the monument repaint calc.
// Pulls rates from the *Paint Estimator* settings (no new settings created).
//
// Inputs from item.repaint_config.dim_letter_paint:
//   { enabled, qty, avg_height_in, thickness_in, second_color_mask }
//
// Output (or null if not enabled):
//   {
//     letters_face_sqft, letters_returns_sqft, letters_total_sqft,
//     letters_gallons, letters_paint_cost,
//     mask_sqft, mask_material_cost, mask_machine_cost,
//     mask_weed_labor_cost, mask_apply_labor_cost,
//     mask_total_cost, mask_labor_hours,
//     letters_labor_hours, letters_total_added_cost,
//   }

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// Mirror paint cost-per-gallon resolution used by PaintSettings.
const UNIT_FACTORS = { oz: 1/128, pint: 1/8, quart: 1/4, liter: 1/3.78541, gallon: 1 };
const costPerGallon = (cost, unit) => {
  const c = num(cost);
  const f = UNIT_FACTORS[unit] || 1;
  if (!f) return 0;
  return c / f;
};

// Liquid mixed paint $ per sqft, derived from PaintSettings mix.
const mixedPaintCostPerSqft = (s) => {
  const paintG = costPerGallon(s.paint_cost_per_unit, s.paint_unit);
  const hardG  = costPerGallon(s.hardener_cost_per_unit, s.hardener_unit);
  const redG   = costPerGallon(s.reducer_cost_per_unit, s.reducer_unit);
  const pR = num(s.paint_mix_ratio), hR = num(s.hardener_mix_ratio), rR = num(s.reducer_mix_ratio);
  const parts = pR + hR + rR;
  if (!parts) return 0;
  const costPerGalMixed = (paintG * pR + hardG * hR + redG * rR) / parts;
  const coverage = num(s.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  return costPerGalMixed / coverage;
};

// Estimate sqft of paintable area on a single dimensional letter:
//   face = h × (h × perimeterFactor / 4)  ≈ approximated using h² for stroke-based letters
// We use the same approximation as the Paint Estimator's letter math:
//   letter face area ≈ h² × 0.55 (typical sans serif), but to stay simple,
//   we expose a knob: face_factor = 0.55 (face vs bounding box).
// Return walls = letter perimeter × thickness.
// Letter perimeter = h × letter_perimeter_factor (from Paint Settings).
export const computeDimLetterPaint = (cfg, settings) => {
  const dl = cfg?.dim_letter_paint;
  if (!dl?.enabled) return null;

  const qty = Math.max(0, num(dl.qty));
  if (qty <= 0) return null;
  const hIn = Math.max(0, num(dl.avg_height_in));
  const tIn = Math.max(0, num(dl.thickness_in));
  if (hIn <= 0) return null;

  const perimFactor = num(settings.letter_perimeter_factor, 3.5) || 3.5;
  const FACE_FACTOR = 0.55; // sans-serif stroke ratio

  // Per-letter areas in square inches
  const facePerLetterIn2 = hIn * hIn * FACE_FACTOR;
  const returnsPerLetterIn2 = (hIn * perimFactor) * tIn;

  // Convert to sqft × qty
  const SQIN_PER_SQFT = 144;
  const letters_face_sqft = (facePerLetterIn2 * qty) / SQIN_PER_SQFT;
  const letters_returns_sqft = (returnsPerLetterIn2 * qty) / SQIN_PER_SQFT;
  const letters_total_sqft = letters_face_sqft + letters_returns_sqft;

  // Paint material cost
  const liquid$PerSqft = mixedPaintCostPerSqft(settings);
  const wasteMult = num(settings.paint_waste_multiplier, 1.25) || 1.25;
  const letters_paint_cost = letters_total_sqft * liquid$PerSqft * wasteMult;
  const coverage = num(settings.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  const letters_gallons = (letters_total_sqft * wasteMult) / coverage;

  // Labor: use Paint Settings base hours/sqft + small-letter prep multiplier when applicable
  const basePerSqft = num(settings.base_labor_hours_per_sqft, 0.05);
  let prepMult = num(settings.lettering_normal_prep_multiplier, 1.0) || 1.0;
  if (hIn <= 4)       prepMult = num(settings.lettering_extra_small_prep_multiplier, 1.5);
  else if (hIn <= 8)  prepMult = num(settings.lettering_small_prep_multiplier, 1.3);
  else if (hIn <= 12) prepMult = num(settings.lettering_normal_prep_multiplier, 1.0);
  else if (hIn <= 20) prepMult = num(settings.lettering_medium_prep_multiplier, 0.9);
  else if (hIn <= 30) prepMult = num(settings.lettering_large_prep_multiplier, 0.8);
  else                prepMult = num(settings.lettering_extra_large_prep_multiplier, 0.7);
  const letters_labor_hours = letters_total_sqft * basePerSqft * prepMult;

  // Paint Mask (only when the second color requires masking)
  const usingMask = dl.second_color_mask === "paint_mask";
  let mask_sqft = 0, mask_material_cost = 0, mask_machine_cost = 0;
  let mask_weed_labor_cost = 0, mask_apply_labor_cost = 0, mask_labor_hours = 0;
  if (usingMask) {
    // Mask covers the face area only (returns aren't typically masked for a 2nd color)
    mask_sqft = letters_face_sqft;
    const matRate    = num(settings.paint_mask_rate_per_sqft);
    const machineRate= num(settings.paint_mask_machine_cutting_rate_per_sqft);
    const weedRate   = num(settings.paint_mask_cutting_labor_rate_per_sqft);
    const applyRate  = num(settings.paint_mask_application_labor_rate_per_sqft);
    const laborRate  = num(settings.default_labor_rate, 60) || 60;

    mask_material_cost = mask_sqft * matRate;
    mask_machine_cost  = mask_sqft * machineRate;
    mask_weed_labor_cost  = mask_sqft * weedRate;
    mask_apply_labor_cost = mask_sqft * applyRate;
    // Convert mask labor $ back into hours so it rolls into the maintenance labor pool
    const mask_labor_cost = mask_weed_labor_cost + mask_apply_labor_cost;
    mask_labor_hours = laborRate > 0 ? (mask_labor_cost / laborRate) : 0;

    // For a 2nd color the letters get painted twice on the face (base + accent),
    // double the face paint quantity.
    const secondColorExtraPaint = letters_face_sqft * liquid$PerSqft * wasteMult;
    // Add to letters_paint_cost
    // (mutate locally so the return value matches)
    // eslint-disable-next-line no-param-reassign
    return finalize({
      letters_face_sqft, letters_returns_sqft, letters_total_sqft,
      letters_gallons: letters_gallons + (letters_face_sqft * wasteMult) / coverage,
      letters_paint_cost: letters_paint_cost + secondColorExtraPaint,
      mask_sqft, mask_material_cost, mask_machine_cost,
      mask_weed_labor_cost, mask_apply_labor_cost,
      mask_labor_hours, letters_labor_hours,
    });
  }

  return finalize({
    letters_face_sqft, letters_returns_sqft, letters_total_sqft,
    letters_gallons, letters_paint_cost,
    mask_sqft: 0, mask_material_cost: 0, mask_machine_cost: 0,
    mask_weed_labor_cost: 0, mask_apply_labor_cost: 0,
    mask_labor_hours: 0, letters_labor_hours,
  });
};

const finalize = (r) => {
  const mask_total_cost =
    r.mask_material_cost + r.mask_machine_cost + r.mask_weed_labor_cost + r.mask_apply_labor_cost;
  const letters_total_added_cost = r.letters_paint_cost + mask_total_cost;
  return { ...r, mask_total_cost, letters_total_added_cost };
};

