    post_and_panel[actionId] = { basis: "per_cabinet", row: cabinetRow(
      Math.round(r.cab_small * PNP_MULT),
      Math.round(r.cab_medium * PNP_MULT),
      Math.round(r.cab_large * PNP_MULT),
      Math.round(r.cab_extra_large * PNP_MULT),
