];

export const getTierTheme = (tierNumber) => {
  const idx = Math.max(0, Math.min(TIER_THEMES.length - 1, (Number(tierNumber) || 1) - 1));
  return TIER_THEMES[idx];
};

export default function TierBadge({ tierNumber, size = 'md' }) {
  const theme = getTierTheme(tierNumber);
  const sizeClass = size === 'lg'
    ? 'w-12 h-12 text-lg'
    : size === 'sm'
      ? 'w-7 h-7 text-xs'
      : 'w-9 h-9 text-sm';
  return (
    <div className={`${sizeClass} ${theme.bg} ${theme.text} rounded-xl flex items-center justify-center font-bold shadow-sm ring-2 ${theme.ring} flex-shrink-0`}>
      {tierNumber}
    </div>
  );
}

// Pure utility functions for applying tier markups + volume discounts to project costs.
// Does NOT mutate project entities — produces a marked-up summary breakdown.

/**
 * Get a tier's markup multiplier for a given category_key.
 * Falls back to 1.0 (no markup) when the value is missing or non-positive.
 * Values between 0 and 1 are valid discount markups and are honored — only
 * ≤0 and non-numeric entries are treated as "not configured".
 */
export function getMarkup(tier, categoryKey) {
  if (!tier || !tier.markups) return 1.0;
  const v = tier.markups[categoryKey];
  return typeof v === 'number' && v > 0 ? v : 1.0;
}

/**
 * Parse volume discount brackets from Settings records.
 * Returns array of {min, pct} sorted high-to-low so we can pick the highest qualifying bracket.
 */
export function parseVolumeDiscountBrackets(settings) {
  const get = (name) => {
    const s = settings.find(x => x.setting_name === name);
    return s ? parseFloat(s.setting_value) : null;
  };
  const brackets = [];
  for (let i = 1; i <= 4; i++) {
    const min = get(`volume_discount_bracket_${i}_min`);
    const pct = get(`volume_discount_bracket_${i}_pct`);
    if (min !== null && pct !== null) brackets.push({ min, pct });
  }
  return brackets.sort((a, b) => b.min - a.min);
}

/**
 * Parse the list of category keys eligible for volume discount.
 */
export function parseVolumeDiscountCategories(settings) {
  const s = settings.find(x => x.setting_name === 'volume_discount_applies_to');
  if (!s) return [];
  return s.setting_value.split(',').map(x => x.trim()).filter(Boolean);
}

/**
 * Given an eligible subtotal, find the highest qualifying volume discount %.
 */
export function getVolumeDiscountPct(eligibleSubtotal, brackets) {
  for (const b of brackets) {
    if (eligibleSubtotal >= b.min) return b.pct;
  }
  return 0;
}

/**
 * Apply tier markup + volume discount to a list of cost lines.
 *
 * @param {Array<{label, cost, category_key, module}>} lines
 * @param {Object} tier - MarkupTier record
 * @param {Object} settings - { brackets, eligibleCategoryKeys }
 * @returns {Object} { lines: [...withMarkupApplied], totals: {...} }
 */
// Skip-recompute memo (#414): identical line/tier objects with identical
// settings content return the last result without re-running the markup
// waterfall. WeakMap on lines (a new array = new payload = fresh compute).
const _applyCache = new WeakMap();

export function applyMarkups(lines, tier, settings) {
  if (!lines || typeof lines !== "object") return _applyMarkupsComputed(lines, tier, settings);
  const settingsKey = JSON.stringify(settings || {});
  let byTier = _applyCache.get(lines);
  const hit = byTier?.get(tier);
  if (hit && hit.key === settingsKey) return hit.out;
  const out = _applyMarkupsComputed(lines, tier, settings);
  if (!byTier) { byTier = new Map(); _applyCache.set(lines, byTier); }
  byTier.set(tier, { key: settingsKey, out });
  return out;
}

function _applyMarkupsComputed(lines, tier, settings) {
  const { brackets = [], eligibleCategoryKeys = [], categoryFlags = {} } = settings || {};
  const isDiscountEligible = (key) => eligibleCategoryKeys.includes(key) && categoryFlags[key] !== false;

  // First pass: compute marked-up cost per line (no volume discount yet)
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const markup = getMarkup(tier, line.category_key);
    const markedCost = cost * markup;
    return {
      ...line,
      cost,
      markup_multiplier: markup,
      marked_up_cost: markedCost,
    };
  });

  // Compute eligible subtotal for volume discount
  const eligibleSubtotal = marked
    .filter(l => isDiscountEligible(l.category_key))
    .reduce((sum, l) => sum + l.marked_up_cost, 0);

  const volumeDiscountPct = getVolumeDiscountPct(eligibleSubtotal, brackets);
  const volumeDiscountFactor = 1 - (volumeDiscountPct / 100);

  // Second pass: apply volume discount only to eligible lines
  const finalLines = marked.map(line => {
    const isEligible = isDiscountEligible(line.category_key);
    const final = isEligible ? line.marked_up_cost * volumeDiscountFactor : line.marked_up_cost;
    return {
      ...line,
      volume_discount_applied: isEligible ? volumeDiscountPct : 0,
      final_cost: final,
    };
  });

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);
  const markedSubtotal = finalLines.reduce((s, l) => s + l.marked_up_cost, 0);
  const grandTotal = finalLines.reduce((s, l) => s + l.final_cost, 0);

  // Readability merge: collapse lines sharing a category_key into one row.
  // Same-category lines always share markup multiplier + discount eligibility,
  // so summing cost fields is exact. Per-item detail stays in detail_lines.
  const mergedLines = [];
  const byKey = new Map();
  for (const l of finalLines) {
    const key = l.category_key || "";
    const existing = byKey.get(key);
    if (!existing) {
      const g = { ...l, merged_count: 1, base_label: l.label };
      byKey.set(key, g);
      mergedLines.push(g);
    } else {
      existing.merged_count += 1;
      existing.cost += l.cost;
      existing.marked_up_cost += l.marked_up_cost;
      existing.final_cost += l.final_cost;
      existing.label = `${existing.base_label} (+${existing.merged_count - 1} merged)`;
    }
  }

  return {
    lines: mergedLines,
    detail_lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      eligible_subtotal: eligibleSubtotal,
      volume_discount_pct: volumeDiscountPct,
      grand_total: grandTotal,
    },
  };
}

/**
 * Cost-Plus pricing engine — alternative to applyMarkups().
 *
 * Pipeline (per line):
 *   1. category_markup_pct (optional)  → cost × (1 + pct/100)
 *   2. labor_multiplier                → applied only to lines flagged as labor
 *   3. overhead_percent                → flat % on the marked subtotal
 *   4. profit_percent                  → flat % on the post-overhead subtotal
 *
 * @param {Array<{label, cost, category_key, module, is_labor?}>} lines
 * @param {Object} config - CostPlusConfig record
 * @returns {Object} { lines: [...], totals: {...} }
 */
export function applyCostPlus(lines, config) {
  const cfg = config || {};
  const laborMult = Number(cfg.labor_multiplier) || 1;
  const overheadPct = Number(cfg.overhead_percent) || 0;
  const profitPct = Number(cfg.profit_percent) || 0;
  const catMarkups = cfg.category_markups || {};

  // 1+2: per-line category markup, then labor burden on labor lines
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const catPct = Number(catMarkups[line.category_key]) || 0;
    const afterCatMarkup = cost * (1 + catPct / 100);
    const afterBurden = line.is_labor ? afterCatMarkup * laborMult : afterCatMarkup;
    return {
      ...line,
      cost,
      category_markup_pct: catPct,
      labor_burden_applied: line.is_labor ? laborMult : 1,
      marked_up_cost: afterBurden,
    };
  });

  const markedSubtotal = marked.reduce((s, l) => s + l.marked_up_cost, 0);
  const overheadAmount = markedSubtotal * (overheadPct / 100);
  const afterOverhead = markedSubtotal + overheadAmount;
  const profitAmount = afterOverhead * (profitPct / 100);
  const grandTotal = afterOverhead + profitAmount;

  // Distribute overhead + profit proportionally so each line still has a "final_cost"
  const totalLift = markedSubtotal > 0 ? grandTotal / markedSubtotal : 1;
  const finalLines = marked.map(line => ({
    ...line,
    volume_discount_applied: 0,
    final_cost: line.marked_up_cost * totalLift,
  }));

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);

  return {
    lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      overhead_pct: overheadPct,
      overhead_amount: overheadAmount,
      profit_pct: profitPct,
      profit_amount: profitAmount,
      grand_total: grandTotal,
    },
  };
}
/**
 * Target-margin price calculator ("price for X% margin").
 * margin% is the share of the SALE that is profit: price = cost / (1 - margin).
 * Differs from markup-on-cost: a 50% margin requires a 100% markup.
 * Returns 0 for a non-positive cost; null for invalid margins (>=100 or <0).
 */
export function priceForTargetMargin(cost, marginPct) {
  const c = Number(cost);
  const m = Number(marginPct);
  if (!Number.isFinite(c) || c <= 0) return 0;
  if (!Number.isFinite(m) || m < 0 || m >= 100) return null;
  return c / (1 - m / 100);
}

// Extracts cost lines from each module's project records and tags them
// with the proper category_key for tier-markup application.
//
// Mapping (from user's tier sheet):
//   Channel/Raceway/Capsule letter purchases  -> outsourced_fab
//   Dimensional Letter substrate (material)   -> substrates
//   Dimensional Letter paint materials        -> outsourced_fab
//   Dimensional Letter fab labor (CNC+paint)  -> inhouse_labor
//   Channel Letter install labor              -> inhouse_labor
//   Install materials/supplies (hardware)     -> outsourced_fab
//   Equipment rental (lifts)                  -> outsourced_services
//   Concrete + rebar materials                -> outsourced_fab
//   Foundation labor                          -> inhouse_labor
//   Poles                                     -> outsourced_fab
//   Foundation equipment rental               -> outsourced_services
//   Brick/stone material                      -> outsourced_fab
//   Masonry outsourced labor                  -> outsourced_services
//   Mortar + supplies                         -> outsourced_fab
//   Paint Estimator materials                 -> outsourced_fab
//   Paint Estimator labor                     -> inhouse_labor
//   Laser machine time                        -> machine_time
//   Laser labor                               -> inhouse_labor
//   Laser materials                           -> substrates
//   CNC machine time                          -> machine_time
//   CNC labor                                 -> inhouse_labor
//   CNC materials                             -> substrates
//   Metal Fab material                        -> substrates
//   Metal Fab labor                           -> inhouse_labor

const num = (v) => Number(v) || 0;

// Per-project memoization (#412): categorize output depends only on the
// project payload. A WeakMap keyed on the project object skips recompute when
// React re-renders pass the same object, and entries GC with the object.
const _catCache = new WeakMap();
const _catMemo = (p, compute) => {
  if (!p || typeof p !== "object") return compute(p);
  let byFn = _catCache.get(p);
  if (byFn && byFn.has(compute)) return byFn.get(compute);
  const out = compute(p);
  if (!byFn) { byFn = new Map(); _catCache.set(p, byFn); }
  byFn.set(compute, out);
  return out;
};

function _impl_categorizeChannelLetterProject(p) {
  if (!p) return [];
  const lines = [];

  // 1. Letter purchases - check each letter type
  (p.letter_purchases || []).forEach((lp) => {
    const isDimensional = lp.letter_type === 'dimensional_letters';
    const total = num(lp.total_cost);
    if (total <= 0) return;

    if (isDimensional && lp.fab_config) {
      // Dimensional: split into material vs labor using fab_config if present
      const matCost = num(lp.fab_config.material_cost) + num(lp.fab_config.paint_material_cost);
      const laborCost = num(lp.fab_config.cnc_labor_cost) + num(lp.fab_config.paint_labor_cost);
      if (matCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Material — ${lp.description || ''}`, cost: matCost, category_key: 'substrates' });
      }
      if (laborCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Fab Labor — ${lp.description || ''}`, cost: laborCost, category_key: 'inhouse_labor' });
      }
      const remainder = total - matCost - laborCost;
      if (remainder > 0.01) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter (other) — ${lp.description || ''}`, cost: remainder, category_key: 'substrates' });
      }
    } else if (isDimensional) {
      // Dimensional with no fab_config breakdown — categorize whole as substrates (material side)
      lines.push({ module: 'channel_letter', label: `Dimensional Letters — ${lp.description || ''}`, cost: total, category_key: 'substrates' });
    } else {
      // Channel / Raceway / Capsule / Logo = outsourced fab
      lines.push({ module: 'channel_letter', label: `Letter Purchase — ${lp.description || lp.letter_type}`, cost: total, category_key: 'outsourced_fab' });
    }
  });

  // 1b. Letter-level fees
  // Delivery doesn't apply when every product is dimensional (matches lettersCalculator)
  const onlyDimensional = (p.letter_purchases || []).length > 0 &&
    (p.letter_purchases || []).every(lp => lp.letter_type === 'dimensional_letters');
  const letterFees =
    (onlyDimensional ? 0 : num(p.letters_delivery_fee)) + num(p.letters_design_fee) +
    num(p.letters_install_supplies_fee) + num(p.letters_permitting_fee) +
    num(p.letters_other_fee);
  if (letterFees > 0) {
    lines.push({ module: 'channel_letter', label: 'Letter Fees (delivery/design/permit/etc.)', cost: letterFees, category_key: 'outsourced_fab' });
  }

  // 2. Installation labor — when a crew is assigned, personnel pricing replaces
  // the flat-rate labor (labor_cost_in_subtotal = 0), so labor is never double-counted.
  const baseLabor = p.labor_cost_in_subtotal !== undefined
    ? num(p.labor_cost_in_subtotal)
    : num(p.labor_cost);
  const installLabor = baseLabor + num(p.total_personnel_cost);
  if (installLabor > 0) {
    lines.push({ module: 'channel_letter', label: 'Installation Labor', cost: installLabor, category_key: 'inhouse_labor' });
  }

  // 3. Materials/supplies (hardware, mounting)
  const matCost = num(p.total_materials_cost) + num(p.total_supplies_cost);
  if (matCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Install Materials & Supplies', cost: matCost, category_key: 'outsourced_fab' });
  }

  // 4. Equipment rental
  const eqCost = num(p.total_equipment_cost);
  if (eqCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Equipment Rental', cost: eqCost, category_key: 'outsourced_services' });
  }

  // 5. Travel — was previously missing, so categorized lines didn't sum to the subtotal
  const travelCost = num(p.total_travel_cost);
  if (travelCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Travel & Fuel', cost: travelCost, category_key: 'outsourced_services' });
  }

  return lines;
}

function _impl_categorizeFoundationProject(p) {
  if (!p) return [];
  const lines = [];
  const concrete = num(p.total_concrete_cost) + num(p.total_rebar_cost) + num(p.total_forming_materials_cost);
  if (concrete > 0) lines.push({ module: 'foundation', label: 'Concrete / Rebar / Forming Materials', cost: concrete, category_key: 'outsourced_fab' });
  const fLabor = num(p.total_labor_cost) + num(p.total_excavation_cost);
  if (fLabor > 0) lines.push({ module: 'foundation', label: 'Foundation Labor', cost: fLabor, category_key: 'inhouse_labor' });
  const poles = num(p.total_pole_cost) + num(p.total_pole_painting_cost);
  if (poles > 0) lines.push({ module: 'foundation', label: 'Poles & Pole Painting', cost: poles, category_key: 'outsourced_fab' });
  const eq = num(p.total_equipment_cost);
  if (eq > 0) lines.push({ module: 'foundation', label: 'Foundation Equipment Rental', cost: eq, category_key: 'outsourced_services' });

  // Foundation wall totals already contain their material, mortar and labor. Use
  // the calculated wall rows directly so tier pricing neither double-counts the
  // aggregate brick/fill fields nor treats masonry labor as purchased material.
  const wallMaterial = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.materialCost) + num(costs.mortarCost) + num(costs.internalMaterialCost) + num(costs.internalMortarCost);
  }, 0);
  const wallLabor = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.laborCost) + num(costs.internalLaborCost);
  }, 0);
  if (wallMaterial > 0) lines.push({ module: 'foundation', label: 'Brick / Wall / Mortar Materials', cost: wallMaterial, category_key: 'outsourced_fab' });
  if (wallLabor > 0) lines.push({ module: 'foundation', label: 'Masonry Labor', cost: wallLabor, category_key: 'outsourced_services' });

  const wallCaps = num(p.total_wall_cap_cost);
  if (wallCaps > 0) lines.push({ module: 'foundation', label: 'Wall Cap Materials', cost: wallCaps, category_key: 'outsourced_fab' });
  const cabinets = num(p.total_signage_cabinet_cost);
  if (cabinets > 0) lines.push({ module: 'foundation', label: 'Purchased Signage Cabinets', cost: cabinets, category_key: 'outsourced_fab' });
  const landscape = num(p.total_landscape_cost);
  if (landscape > 0) lines.push({ module: 'foundation', label: 'Landscape / Site Materials', cost: landscape, category_key: 'outsourced_fab' });
  return lines;
}

